		end
		local function bindHover(target, plate)
			target.MouseEnter:Connect(function() Tween(plate, { BackgroundTransparency = 0.97 }, 0.1) end)
			target.MouseLeave:Connect(function() Tween(plate, { BackgroundTransparency = 1 }, 0.14) end)
		end

