		local function MakeSettingBtn(text, textColor, iconKind, callback)
			sfOrder = sfOrder + 1
			local btn = Instance.new("TextButton")
			btn.Name = "MenuItem"
			btn.LayoutOrder = sfOrder
			btn.Size = UDim2.new(1, 0, 0, 30)
			btn.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
