---------------------------------------------------------------- диагностика на экране
-- На телефоне консоль недоступна: ошибки сборки меню и счётчик созданных элементов показываются плашкой
-- внизу слева. Тап по плашке скрывает её. Плашка появляется через 8 с после создания окна и сама
-- всплывает при новой ошибке.
local GENV = (getgenv and getgenv()) or _G
GENV.KilledDiagQueue = GENV.KilledDiagQueue or {}
local STATS = {}
local WIN_READY, diagDismissed, diagGui, diagLabel = false, false, nil, nil

local function diagRender()
	if not (diagLabel and diagLabel.Parent) then return end
	local q = GENV.KilledDiagQueue
	local out = {
		string.format("menu built: toggles %d | sliders %d | dropdowns %d | colors %d | buttons %d | keybinds %d | sections %d",
			STATS.tgl or 0, STATS.sld or 0, STATS.dd or 0, (STATS.cpk or 0), STATS.btn or 0, STATS.key or 0, STATS.sec or 0),
		"errors: " .. #q .. "  (tap to hide)",
	}
	for i = math.max(1, #q - 11), #q do out[#out + 1] = string.sub(tostring(q[i]), 1, 150) end
	diagLabel.Text = table.concat(out, "\n")
end

local function diagShow()
	if diagDismissed then return end
	if diagGui and diagGui.Parent then diagRender() return end
	pcall(function()
		local parent
		pcall(function() parent = gethui and gethui() end)
		if not parent then pcall(function() parent = game:GetService("CoreGui") end) end
		if not parent then parent = game:GetService("Players").LocalPlayer:FindFirstChildOfClass("PlayerGui") end
		local sg = Instance.new("ScreenGui")
		sg.Name = "KilledDiag"
		sg.ResetOnSpawn = false
		sg.DisplayOrder = 100000
		sg.IgnoreGuiInset = true
		sg.Parent = parent
		local b = Instance.new("TextButton")
		b.AutoButtonColor = false
		b.AnchorPoint = Vector2.new(0, 1)
		b.Position = UDim2.new(0, 6, 1, -6)
		b.Size = UDim2.new(0.62, 0, 0, 0)
		b.AutomaticSize = Enum.AutomaticSize.Y
		b.BackgroundColor3 = Color3.fromRGB(10, 10, 14)
		b.BackgroundTransparency = 0.2
		b.BorderSizePixel = 0
		b.TextColor3 = Color3.fromRGB(255, 150, 150)
		b.TextXAlignment = Enum.TextXAlignment.Left
		b.TextYAlignment = Enum.TextYAlignment.Top
		b.TextWrapped = true
		b.TextSize = 11
		b.Font = Enum.Font.Code
		b.Text = ""
		b.Parent = sg
		b.MouseButton1Click:Connect(function()
			diagDismissed = true
			pcall(function() sg:Destroy() end)
		end)
		diagGui, diagLabel = sg, b
		diagRender()
	end)
end

local function diagPush(msg)
	warn(msg)
	table.insert(GENV.KilledDiagQueue, msg)
	if WIN_READY then diagShow() end
end

---------------------------------------------------------------- утилиты
-- Любой неизвестный метод меню не должен ронять скрипт: возвращаем self.
-- Поля данных адаптера: если их нет, это nil, а не "заглушка-функция" (иначе любой `if not self._st`,
-- `if self.host`, `if self.obj` всегда истинен, а дальше код индексирует эту функцию и падает).
local DATA_FIELDS = { host = true, obj = true, win = true, val = true, opts = true, kind = true, pages = true, fl = true, flags = true, W = true }

local function tolerant(t, class)
	return setmetatable(t, {
		__index = function(_, k)
			if class and class[k] ~= nil then return class[k] end
			if type(k) ~= "string" then return nil end
			if DATA_FIELDS[k] or string.sub(k, 1, 1) == "_" then return nil end
			return function(self) return self end
		end,
	})
end

local function safe(fn, ...)
	if type(fn) ~= "function" then return end
	local ok, err = pcall(fn, ...)
	if not ok then warn("[nl_adapter] callback error: " .. tostring(err)) end
end

local KEYS = { "None" }
for _, k in ipairs(Enum.KeyCode:GetEnumItems()) do
	if k.Name:match("^%a$") or k.Name:match("^F%d+$") then
		KEYS[#KEYS + 1] = k.Name
	end
end
for _, n in ipairs({ "LeftAlt", "LeftControl", "LeftShift", "Insert", "Home", "End", "Delete", "Space" }) do
	KEYS[#KEYS + 1] = n
end

local function keyName(v)
	if typeof(v) == "EnumItem" then return v.Name end
	if type(v) == "string" and v ~= "" then return v end
	return "None"
end

---------------------------------------------------------------- контейнеры и элементы
local Container = {}
Container.__index = Container

-- Любой конструктор элемента либы идёт через pcall: упавший элемент пропускается (с именем и причиной в консоли),
-- а не обрывает весь модуль вместе со всеми тоглами, которые в нём ниже.
local function guard(raw)
	return setmetatable({}, { __index = function(_, k)
		local f = raw[k]
		if type(f) ~= "function" then return f end
		return function(_, ...)
			local ok, res = pcall(f, raw, ...)
			if ok then return res end
			diagPush("[nl_adapter] " .. tostring(k) .. " '" .. tostring((...)) .. "' failed: " .. tostring(res))
			return nil
		end
	end })
end

local function newContainer(win, host)
	if type(host) == "table" then host = guard(host) else host = nil end
	return tolerant({ win = win, host = host }, Container)
end

-- общий конструктор элемента-обёртки: хранит значение и флаг, зовёт cb скрипта
local function newElement(win, o, kind, default)
	local e = tolerant({ kind = kind, opts = o, val = default, win = win })
	STATS[kind] = (STATS[kind] or 0) + 1
	-- поля, которые скрипт читает у элемента (экранные тогглы, _.finish): без них tolerant() отдаёт функцию вместо nil/таблицы
	e.flag = o.flag or false
	e.c = false
	e.spbtn = false
	function e.fire() end -- дефолты уже синхронизирует initial(), повторный cb не нужен
	function e.opensp() if e._st and e._st.Open then pcall(e._st.Open, e._st) end end
	if win and win.els then win.els[#win.els + 1] = e end
	if o.flag then
		win.fl[o.flag] = e
		win.flags[o.flag] = default
	end
	function e:report(v)
		self.val = v
		if o.flag then win.flags[o.flag] = v end
		safe(o.cb, v)
	end
	function e:set(v)
		self.val = v
		if o.flag then win.flags[o.flag] = v end
		if self.obj and self.obj.Set then pcall(self.obj.Set, self.obj, v) else safe(o.cb, v) end
	end
	function e:get() return self.val end
	function e:dep() return self end
	function e:hide() return self end
	function e:show() return self end
	-- ":settings()" = меню "три точки" у строки элемента
	function e:settings()
		if not self.obj or not self.obj.AddSettings then return newContainer(win, nil) end
		if not self._st then
			local okS, st = pcall(self.obj.AddSettings, self.obj)
			if not okS then diagPush("[nl_adapter] settings failed: " .. tostring(st)) end
			self._st = okS and st or nil
		end
		return newContainer(win, self._st)
	end
	-- ":color{...}" на тогле/слайдере: цветпикер внутри "трёх точек"
	function e:color(co)
		self:settings():color(co)
		return self
	end
	function e:keybind(ko)
		self:settings():keybind(ko)
		return self
	end
	return e
end

local function initial(e, default)
	-- синхронизируем состояние скрипта с дефолтом меню (после сборки всех модулей)
	if default ~= nil then
		task.delay(0.6, function() safe(e.opts.cb, default) end)
	end
end

function Container:toggle(o)
	o = o or {}
	local default = o.default == true
	local e = newElement(self.win, o, "tgl", default)
	if self.host then
		e.obj = self.host:AddToggle(o.name or "toggle", default, function(v) e:report(v) end)
	end
	initial(e, default)
	if o.bind or o.key then self:keybind({ name = (o.name or "toggle") .. " key", default = o.bind or o.key, flag = o.flag and (o.flag .. "_bind") or nil, onpress = function() e:set(not e.val) end }) end
	return e
end

function Container:slider(o)
	o = o or {}
	local min, max = o.min or 0, o.max or 100
	local default = o.default or min
	local e = newElement(self.win, o, "sld", default)
	if self.host then
		e.obj = self.host:AddSlider(o.name or "value", min, max, default, function(v) e:report(v) end, o.suffix)
	end
	initial(e, default)
	return e
end

function Container:dropdown(o)
	o = o or {}
	local values = o.values or o.items or {}
	local default = o.default
	if default == nil then default = values[1] end
	if type(default) == "table" then default = default[1] end
	local e = newElement(self.win, o, "dd", default)
	if self.host then
		e.obj = self.host:AddDropdown(o.name or "list", values, default, function(v)
			e:report(o.multi and { v } or v) -- multi упрощён до одиночного выбора
		end)
	end
	initial(e, o.multi and { default } or default)
	return e
end

function Container:color(o)
	o = o or {}
	local default = typeof(o.default) == "Color3" and o.default or Color3.new(1, 1, 1)
	local e = newElement(self.win, o, "cpk", default)
	if self.host and self.host.AddColorpicker then
		e.obj = self.host:AddColorpicker(o.name or "color", default, function(c) e:report(c) end)
	end
	initial(e, default)
	return e
end

-- Скрипт зовёт :colorpicker{name, flag, default, alpha, cb(color, alpha)} в "трёх точках" (fill/outline highlight,
-- grenade/smoke/molotov зоны, bomb timer, penetration yes/no). Раньше адаптер знал только :color,
-- а неизвестные методы глотает tolerant() -> эти цветпикеры просто не создавались.
function Container:colorpicker(o)
	o = o or {}
	local default = typeof(o.default) == "Color3" and o.default or Color3.new(1, 1, 1)
	local alpha = o.alpha
	local e = newElement(self.win, o, "cpk", default)
	if self.host and self.host.AddColorpicker then
		e.obj = self.host:AddColorpicker(o.name or "color", default, function(c)
			e.val = c
			if o.flag then self.win.flags[o.flag] = c end
			safe(o.cb, c, alpha)
		end)
	end
	if o.cb then task.delay(0.6, function() safe(o.cb, default, alpha) end) end
	return e
end

-- Кнопок/биндов в либе нет: кнопка = самосбрасывающийся тогл, бинд = дропдаун клавиш + слушатель
function Container:button(o)
	o = o or {}
	local e = newElement(self.win, o, "btn", false)
	if self.host then
		e.obj = self.host:AddToggle(o.name or "button", false, function(v)
			if v then
				safe(o.cb or o.onclick)
				task.delay(0.15, function() if e.obj then pcall(e.obj.Set, e.obj, false) end end)
			end
		end)
	end
	return e
end

function Container:keybind(o)
	o = o or {}
	local current = keyName(o.default)
	local e = newElement(self.win, o, "key", current)
	local function apply(name)
		current = name
		e.val = name
		if o.flag then self.win.flags[o.flag] = name end
	end
	if self.host then
		e.obj = self.host:AddDropdown(o.name or "key", KEYS, current, function(name)
			apply(name)
			safe(o.cb, name)
		end)
	end
	UIS.InputBegan:Connect(function(input, processed)
		if processed or current == "None" then return end
		if input.KeyCode and input.KeyCode.Name == current then safe(o.onpress) end
	end)
	return e
end

-- Сетка карточек (скины ножей / перчаток / стволов, агенты). Раньше метода не было вообще:
-- tolerant() молча возвращал self и карточки просто не создавались.
function Container:cards(o)
	o = o or {}
	local win = self.win
	local e = newElement(win, o, "crd", o.default)
	e.values = o.values or {}
	local sides = type(o.sides) == "table" and o.sides or nil
	local function state(v)
		if v == nil or v == "__add" then return nil end
		if sides and type(sides.get) == "function" then
			local okT, t = pcall(sides.get, "t")
			local okC, c = pcall(sides.get, "ct")
			if okT and okC and (t ~= nil or c ~= nil) then
				if t == v and c == v then return "both" end
				if t == v then return "t" end
				if c == v then return "ct" end
				return nil
			end
		end
		return e.val == v and "both" or nil
	end
	if self.host then
		e.obj = self.host:AddCards({
			cols = o.cols,
			values = e.values,
			add = o.add,
			state = state,
			onpick = function(v)
				e:report(v)
				if e.obj then pcall(e.obj.Refresh, e.obj) end
			end,
		})
	end
	-- l:set(v, true) = только подсветка, без cb (иначе сброс/повторное применение скина)
	function e:set(v, silent)
		self.val = v
		if o.flag then win.flags[o.flag] = v end
		if self.obj then pcall(self.obj.Refresh, self.obj) end
		if not silent then safe(o.cb, v) end
	end
	function e:setvalues(vals)
		self.values = vals or {}
		if self.obj then pcall(self.obj.SetValues, self.obj, self.values) end
	end
	if e.obj then e.pool = e.obj.pool end
	return e
end

-- Пустая область под превью (вкладка agents): отдаём настоящий Frame, скрипт сам кладёт в него ViewportFrame
function Container:free(h)
	if not self.host then return nil end
	return self.host:AddCustom(tonumber(h) or 100, "Free")
end

function Container:label(o) return newElement(self.win, type(o) == "table" and o or {}, "lbl", nil) end
function Container:input(o)
	o = o or {}
	local e = newElement(self.win, o, "inp", o.default or "")
	-- текстовых полей в либе нет; значение хранится, менять через win:set(flag, value)
	return e
end

---------------------------------------------------------------- страницы, вкладки, окно
local function newPage(win, host, isSub)
	local page = tolerant({})
	function page:section(o)
		o = type(o) == "table" and o or { name = tostring(o) }
		local side = (o.side == 2 or o.side == "right") and "right" or "left"
		local okSec, sec = pcall(host.AddSection, host, o.name or "Section", side)
		if not okSec then diagPush("[nl_adapter] section '" .. tostring(o.name) .. "' failed: " .. tostring(sec)); sec = nil end
		STATS.sec = (STATS.sec or 0) + 1
		local c = newContainer(win, sec)
		function c:blk() return self end
		return c
	end
	function page:settings() return page:section({ name = "Settings" }) end
	return page
end

-- иконки скрипта -> имена иконок Neverlose-либы
local ICONMAP = {
	crosshair = "crosshair", trigger = "mouse", eye = "visuals", gear = "gear",
	skins = "knife", zap = "code", sliders = "gear", gamepad = "run",
}

local function newTab(win, W, o)
	o = type(o) == "table" and o or { name = tostring(o) }
	local tabObj = W:AddTab(o.name or "tab", ICONMAP[o.icon] or o.icon)
	local tab = tolerant({ pages = {} })
	local usedSub = false

	function tab:page(name)
		usedSub = true
		if type(name) == "table" then name = name.name or name.title or name[1] end -- page{name=..., cols=...}
		local sub = tabObj:AddSubTab(tostring(name or "Main"), nil)
		local p = newPage(win, sub, true)
		p.name = tostring(name or "Main")
		function p:Activate()
			if sub and type(sub.Activate) == "function" then sub:Activate() end
			return self
		end
		function p:AddLoadout(options)
			if sub and type(sub.AddLoadout) == "function" then return sub:AddLoadout(options) end
			return nil
		end
		self.pages[#self.pages + 1] = p
		return p
	end
	function tab:section(o2)
		if not self._main then self._main = newPage(win, tabObj, false) end
		return self._main:section(o2)
	end
	function tab:settings() return self:section({ name = "Settings" }) end
	return tab
end

local Adapter = tolerant({ parts = {} })

function Adapter:window(o)
	o = o or {}
	local W = Lib:AddWindow(o.title or "Killed.wtf", "", "BlockStrike")
	WIN_READY = true
	task.delay(8, diagShow)
	local keyEnum = Enum.KeyCode[o.key or "Insert"] or Enum.KeyCode.Insert
	pcall(function() W:SetMenuBind(keyEnum) end)

	local win = tolerant({ fl = {}, flags = {}, els = {}, W = W, _unload = {}, pages = {} })
	-- список наблюдателей: либа по умолчанию рисует всех мёртвых/без персонажа игроков сервера;
	-- ручной режим, список приходит из Adapter:spectators (те, у кого IsSpectating и кто смотрит на тебя)
	pcall(function() W:SetSpectators({}) end)
	function win:tab(t) return newTab(self, W, t) end
	function win:get(flag) return self.flags[flag] end
	function win:set(flag, v)
		local e = self.fl[flag]
		if e then e:set(v) end
		return e
	end
	function win:el(flag) return self.fl[flag] end
	function win:notify(msg, kind) print("[" .. tostring(kind or "info") .. "] " .. tostring(msg)) end
	function win:onunload(fn) self._unload[#self._unload + 1] = fn end
	function win:unload()
		for i = #self._unload, 1, -1 do safe(self._unload[i]) end
		pcall(function() W:GetMainFrame().Parent:Destroy() end)
	end
	Adapter.win = win
	-- скрипт ходит в N.flags / N.fl / N.els / N.thm / N:set прямо на адаптере (экранные тогглы, _.finish)
	Adapter.flags, Adapter.fl, Adapter.els = win.flags, win.fl, win.els
	Adapter.thm = {
		acc = Color3.fromRGB(78, 139, 255),
		txt = Color3.fromRGB(230, 232, 240),
		knob = Color3.fromRGB(146, 150, 164),
		win = Color3.fromRGB(14, 16, 24),
	}
	return win
end

function Adapter:set(flag, v)
	local w = Adapter.win
	if w then return w:set(flag, v) end
end
function Adapter:get(flag)
	local w = Adapter.win
	if w then return w:get(flag) end
end
-- реальные наблюдатели: массив Player от модуля spectators
function Adapter:spectators(list)
	local w = Adapter.win
	if w and w.W then pcall(w.W.SetSpectators, w.W, list or {}) end
end

function Adapter:notify(msg, kind) print("[" .. tostring(kind or "info") .. "] " .. tostring(msg)) end

return Adapter

