							end;
					else 
						if not(snap)then 
							return;
						end;
						for i=1,#snap.slots,1 do 
							local r=snap.slots[i];
							r.e.model=r.model;
							r.e.skin=r.skin;
						end;
						for i=1,#snap.guns,1 do 
								local r=snap.guns[i];
								GS[r[1]][r[2]]=r[3];
							end;
						snap=nil;
					end;
					q();
				end;
				return U;
			end;
			K.aA=function()
				-- Inventory-style loadout plus an item-specific skin browser.
				local R, S = K.load("e"), K.load("aw")
				local Players = game:GetService("Players")
				local lp = Players.LocalPlayer
				local sidews, syncs = {}, {}
				local SIDE_LABEL = { both = "both", t = "T", ct = "CT" }
				local SIDE_VALUE = { both = "both", T = "t", CT = "ct" }
				local function setside(value)
					if S.side == value then return end
					S.side = value
					for i = 1, #sidews do sidews[i]:set(SIDE_LABEL[value], true) end
					for i = 1, #syncs do pcall(syncs[i]) end
				end
				local function sidedd(sec)
					sidews[#sidews + 1] = sec:dropdown({
						name = "apply to", values = { "both", "T", "CT" }, default = SIDE_LABEL[S.side],
						cb = function(v) setside(SIDE_VALUE[v] or "both") end,
					})
				end

				-- Keep the original knife / glove skin changer intact as its own page.
				local function addModelCategory(sec, category, hasWear)
					local current = function()
						return S.side == "ct" and S.sel[category].ct or S.sel[category].t
					end
					sidedd(sec)
					local cards
					local model = sec:dropdown({
						name = "model", flag = "skins." .. category .. ".model",
						values = S.models(category),
						cb = function(value)
							if category == "glove" then
								if value == "Stock" then S.set(category, "model", "Stock"); S.set(category, "skin", "Stock") end
								if cards then cards:setvalues(S.cards(category, value, current().wear)); cards:set(nil, true) end
								return
							end
							S.set(category, "model", value)
							if cards then
								local state = current()
								local values = S.cards(category, value, state.wear)
								local selected = values[1] and values[1].value or nil
								for _, item in ipairs(values) do if item.value == state.skin then selected = state.skin; break end end
								cards:setvalues(values); cards:set(selected)
							end
						end,
					})
					if hasWear then
						sec:slider({ name = "wear", flag = "skins." .. category .. ".wear", min = 0, max = 100, suffix = "%", cb = function(v)
							S.set(category, "wear", v / 100)
							if cards then cards:setvalues(S.cards(category, model.val, current().wear)) end
						end })
					end
					cards = sec:cards({
						flag = "skins." .. category .. ".skin", cols = 3,
						values = S.cards(category, "Stock", 0), default = "Stock",
						sides = {
							get = function(which)
								local entry = S.sel[category][which]
								return entry and entry.skin or "Stock"
							end,
							set = function(which, value)
								S.setfor(category, which, "skin", value or "Stock")
							end,
						},
						cb = function(value)
							if category == "glove" and model.val ~= "Stock" then S.set(category, "model", model.val) end
							S.set(category, "skin", value)
						end,
					})
					syncs[#syncs + 1] = function()
						local state = current()
						model:set(state.model, true)
						if hasWear then sec.win.fl["skins." .. category .. ".wear"]:set(math.floor((tonumber(state.wear) or 0) * 100 + 0.5), true) end
						cards:setvalues(S.cards(category, state.model, state.wear)); cards:set(state.skin, true)
					end
				end

				-- The loadout is built from the game's enabled weapon database.
				local allGuns = S.guns()
				local pistolSet = { ["USP-S"] = true, ["P2000"] = true, ["Glock-18"] = true, ["Dual Berettas"] = true, ["P250"] = true, ["Five-SeveN"] = true, ["Tec-9"] = true, ["CZ75-Auto"] = true, ["Desert Eagle"] = true, ["R8 Revolver"] = true }
				local rifleSet = { ["AK-47"] = true, ["M4A4"] = true, ["M4A1-S"] = true, ["FAMAS"] = true, ["Galil AR"] = true, ["SG 553"] = true, ["AUG"] = true, ["SSG 08"] = true, ["AWP"] = true, ["G3SG1"] = true, ["SCAR-20"] = true }
				local categorized = { Pistols = {}, ["Mid-Tier"] = {}, Rifles = {} }
				local seen = {}
				for _, weaponName in ipairs(allGuns or {}) do
					if type(weaponName) == "string" and not seen[weaponName] then
						seen[weaponName] = true
						local category = pistolSet[weaponName] and "Pistols" or (rifleSet[weaponName] and "Rifles" or "Mid-Tier")
						table.insert(categorized[category], weaponName)
					end
				end
				for _, list in pairs(categorized) do table.sort(list) end
				local weaponLists = { CT = {}, T = {} }
				for _, teamName in ipairs({ "CT", "T" }) do
					for category, list in pairs(categorized) do weaponLists[teamName][category] = table.clone(list) end
				end

				local initialTeam = lp:GetAttribute("Team") == "Counter-Terrorists" and "CT" or "T"
				local loadoutPage = R.tabs.skins:page({ name = "Loadout", cols = 2 })
				local weaponPage = R.tabs.skins:page({ name = "Weapon skins", cols = 2 })
				local knifePage = R.tabs.skins:page({ name = "Knives", cols = 2 })
				addModelCategory(knifePage:section({ name = "knives" }), "knife", true)
				addModelCategory(knifePage:section({ name = "gloves", side = 2 }), "glove", false)

				local selectedWeapon, selectedTeam, selectedSide
				local loadout
				local cardElement, wearElement, rarityElement
				local previewImage, previewTitle, searchBox
				local rarityFilter, searchText = "All", ""
				local function getWeaponState(weaponName, side)
					local entry = S.ggetfor(weaponName, side)
					if type(entry) ~= "table" then return { skin = "Stock", wear = 0 } end
					return entry
				end
				local function rarityKey(color)
					if typeof(color) ~= "Color3" then return "Stock" end
					local r, g, b = math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5)
					if r == 176 and g == 195 then return "Consumer" end
					if r == 94 and g == 152 then return "Industrial" end
					if r == 75 and g == 105 then return "Mil-Spec" end
					if r == 136 and g == 71 then return "Restricted" end
					if r == 211 and g == 44 then return "Classified" end
					if r == 235 and g == 75 then return "Covert" end
					if r == 228 and g == 174 then return "Special" end
					return "Other"
				end
				local function currentValues()
					if not selectedWeapon then return {} end
					local state = getWeaponState(selectedWeapon, selectedSide)
					return S.gcards(selectedWeapon, tonumber(state.wear) or 0)
				end
				local function findSelected(values)
					local state = selectedWeapon and getWeaponState(selectedWeapon, selectedSide) or { skin = "Stock" }
					for _, item in ipairs(values or {}) do if item.value == state.skin then return item end end
					return values and values[1] or nil
				end
				local function refreshDetail()
					if not selectedWeapon then return end
					local values = currentValues()
					local chosen = findSelected(values)
					if previewImage then previewImage.Image = chosen and type(chosen.image) == "string" and chosen.image or "" end
					if previewTitle then previewTitle.Text = selectedWeapon .. "  |  " .. tostring(chosen and chosen.name or "Stock") end
					local filtered = {}
					local query = string.lower(searchText or "")
					for _, item in ipairs(values) do
						local name = string.lower(tostring(item.name or item.value or ""))
						local nameOK = query == "" or string.find(name, query, 1, true) ~= nil
						local rarityOK = rarityFilter == "All" or rarityKey(item.rarity) == rarityFilter
						if nameOK and rarityOK then filtered[#filtered + 1] = item end
					end
					if cardElement then cardElement:setvalues(filtered) end
					if wearElement then wearElement:set(math.floor((tonumber(getWeaponState(selectedWeapon, selectedSide).wear) or 0) * 100 + 0.5), true) end
				end

				local detailSection = weaponPage:section({ name = "Selected weapon" })
				local topRow = detailSection:free(36)
				if topRow then
					local back = Instance.new("TextButton")
					back.Name = "BackToLoadout"
					back.Position = UDim2.fromOffset(2, 2)
					back.Size = UDim2.fromOffset(116, 30)
					back.BackgroundColor3 = Color3.fromRGB(30, 33, 46)
					back.Text = "‹  LOADOUT"
					back.TextColor3 = Color3.fromRGB(230, 232, 240)
					back.TextSize = 12
					back.Font = Enum.Font.GothamMedium
					back.AutoButtonColor = true
					back.Parent = topRow
					local corner = Instance.new("UICorner"); corner.CornerRadius = UDim.new(0, 7); corner.Parent = back
					back.MouseButton1Click:Connect(function()
						if loadout then loadout:Refresh() end
						loadoutPage:Activate()
					end)
					local title = Instance.new("TextLabel")
					title.Name = "SelectedWeaponTitle"
					title.Position = UDim2.new(0, 128, 0, 2)
					title.Size = UDim2.new(1, -132, 0, 30)
					title.BackgroundTransparency = 1
					title.Text = "Select a weapon"
					title.TextColor3 = Color3.fromRGB(230, 232, 240)
					title.TextSize = 14
					title.Font = Enum.Font.GothamMedium
					title.TextXAlignment = Enum.TextXAlignment.Left
					title.Parent = topRow
					previewTitle = title
				end
				local previewRow = detailSection:free(174)
				if previewRow then
					previewImage = Instance.new("ImageLabel")
					previewImage.Name = "SelectedSkinPreview"
					previewImage.AnchorPoint = Vector2.new(0.5, 0.5)
					previewImage.Position = UDim2.new(0.5, 0, 0.5, 0)
					previewImage.Size = UDim2.new(1, -24, 1, -12)
					previewImage.BackgroundTransparency = 1
					previewImage.ScaleType = Enum.ScaleType.Fit
					previewImage.Parent = previewRow
				end
				-- The right column is reserved for the selected weapon's skin browser;
				-- the left column keeps the large selected-item preview.
				local skinsSection = weaponPage:section({ name = "Skins", side = 2 })
				local filterRow = skinsSection:free(38)
				if filterRow then
					searchBox = Instance.new("TextBox")
					searchBox.Name = "SkinSearch"
					searchBox.Position = UDim2.fromOffset(4, 2)
					searchBox.Size = UDim2.new(1, -8, 1, -4)
					searchBox.BackgroundColor3 = Color3.fromRGB(18, 20, 29)
					searchBox.BorderSizePixel = 0
					searchBox.ClearTextOnFocus = false
					searchBox.PlaceholderText = "Search skins..."
					searchBox.PlaceholderColor3 = Color3.fromRGB(120, 124, 140)
					searchBox.Text = ""
					searchBox.TextColor3 = Color3.fromRGB(230, 232, 240)
					searchBox.TextSize = 13
					searchBox.Font = Enum.Font.Gotham
					searchBox.Parent = filterRow
					local corner = Instance.new("UICorner"); corner.CornerRadius = UDim.new(0, 7); corner.Parent = searchBox
					local pad = Instance.new("UIPadding"); pad.PaddingLeft = UDim.new(0, 9); pad.Parent = searchBox
					searchBox:GetPropertyChangedSignal("Text"):Connect(function()
						searchText = searchBox.Text or ""
						refreshDetail()
					end)
				end
				rarityElement = skinsSection:dropdown({
					name = "rarity", values = { "All", "Consumer", "Industrial", "Mil-Spec", "Restricted", "Classified", "Covert", "Special" }, default = "All",
					cb = function(value) rarityFilter = value or "All"; refreshDetail() end,
				})
				wearElement = skinsSection:slider({
					name = "wear", min = 0, max = 100, suffix = "%", default = 0,
					cb = function(value)
						if not selectedWeapon or not selectedSide then return end
						S.side = selectedSide
						S.gset(selectedWeapon, "wear", value / 100)
						refreshDetail()
					end,
				})
				cardElement = skinsSection:cards({
					flag = "skins.selected_weapon.skin", cols = 4, values = {}, default = "Stock",
					sides = {
						get = function(which)
							if not selectedWeapon then return "Stock" end
							local state = getWeaponState(selectedWeapon, which)
							return state.skin or "Stock"
						end,
						set = function(which, value)
							if selectedWeapon then S.gsetfor(selectedWeapon, which, "skin", value or "Stock") end
						end,
					},
					cb = function(value)
						if not selectedWeapon or not selectedSide then return end
						S.side = selectedSide
						S.gset(selectedWeapon, "skin", value or "Stock")
						refreshDetail()
					end,
				})

				loadout = loadoutPage:AddLoadout({
					team = initialTeam,
					weapons = weaponLists,
					getWeaponInfo = function(teamName, weaponName)
						local which = teamName == "CT" and "ct" or "t"
						local state = getWeaponState(weaponName, which)
						local values = S.gcards(weaponName, tonumber(state.wear) or 0)
						for _, item in ipairs(values) do
							if item.value == state.skin then return item.image, item.name, item.rarity end
						end
						return values[1] and values[1].image, "Stock", values[1] and values[1].rarity
					end,
					onSelect = function(teamName, category, index, weaponName)
						if category == "Gear" then
							if weaponName == "Knife" or weaponName == "Gloves" then
								knifePage:Activate()
							elseif weaponName == "Agent" then
								for _, existingPage in ipairs(R.tabs.skins.pages or {}) do
									if existingPage.name == "Agents" then existingPage:Activate(); break end
								end
							end
							return
						end
						selectedWeapon = weaponName
						selectedTeam = teamName
						selectedSide = teamName == "CT" and "ct" or "t"
						setside(selectedSide)
						searchText, rarityFilter = "", "All"
						if searchBox then searchBox.Text = "" end
						if rarityElement then rarityElement:set("All", true) end
						refreshDetail()
						weaponPage:Activate()
					end,
				})
				if loadout then loadout:SetTeam(initialTeam) end

				-- Update the loadout thumbnails if the active team or its skin changes.
				lp:GetAttributeChangedSignal("Team"):Connect(function()
					local teamName = lp:GetAttribute("Team") == "Counter-Terrorists" and "CT" or "T"
					if loadout then loadout:SetTeam(teamName) end
				end)
				return true
			end;
			K.aG=function()
				-- Agents: родные агенты Bloxstrike (карточки T/CT) + скин по нику. Всё только на клиенте.
				-- Агенты ищутся в ReplicatedStorage сами (папки с "agent" в имени), Kontra-дамп больше не нужен.
				local E,A=K.load("e"),K.load("a");
				local Players=game:GetService("Players");
				local RS=game:GetService("RunService");
				local RSt=game:GetService("ReplicatedStorage");
				local CS=game:GetService("CollectionService");
				local lp=Players.LocalPlayer;
				local lbl,cards,nick;
				local function say(t)
					pcall(function() if lbl then lbl:settext(t);end;end);
				end;
				local recs=setmetatable({},{__mode="k"});
				local busy=setmetatable({},{__mode="k"});
				local failed,ucache={},{};
				local agents,order={}, {};          -- key -> {inst,name,side}
				local sel={t=nil,ct=nil,user=nil};  -- t/ct = key агента, user = ник
				local M={auto=true,to="both"};

				local function rec_of(char)
					local r=recs[char];
					if not r then r={o={},made={}};recs[char]=r;end;
					return r;
				end;
				-- меняем свойство и помним оригинал, чтобы reset вернул как было
				local function setp(r,inst,prop,val)
					local t=r.o[inst];
					if not t then t={};r.o[inst]=t;end;
					if t[prop]==nil then
						local ok,cur=pcall(function() return inst[prop];end);
						if ok then t[prop]=cur;end;
					end;
					pcall(function() inst[prop]=val;end);
				end;
				local function restore(char)
					local r=recs[char];
					if not r then return;end;
					recs[char]=nil;
					for inst,props in pairs(r.o) do
						for p,v in pairs(props) do
							pcall(function() inst[p]=v;end);
						end;
					end;
					for i=1,#r.made do pcall(r.made[i].Destroy,r.made[i]);end;
						if r.gunc then pcall(r.gunc.Destroy,r.gunc);end;
				end;
				local function cloth(char,r,class,prop,val)
					if val==nil or val=="rbxassetid://2" then val="";end;
					local c=char:FindFirstChildOfClass(class);
					if not c then
						c=Instance.new(class);
						c.Parent=char;
						r.made[#r.made+1]=c;
					end;
					setp(r,c,prop,val);
				end;
				local function curside()
					return lp:GetAttribute("Team")=="Counter-Terrorists" and "ct" or "t";
				end;

				-- надеваем «внешку» из модели: рубашка/штаны/цвета/лицо/аксессуары (подходит и для агента, и для ника)
				local function apply_model(char,model,w)
					if not(char and char.Parent and model) then return;end;
					restore(char);
					local r=rec_of(char);
					r.want=w;
					local BODY={Head=1,UpperTorso=1,LowerTorso=1,LeftUpperArm=1,LeftLowerArm=1,LeftHand=1,RightUpperArm=1,RightLowerArm=1,RightHand=1,LeftUpperLeg=1,LeftLowerLeg=1,LeftFoot=1,RightUpperLeg=1,RightLowerLeg=1,RightFoot=1};
					for _,part in ipairs(char:GetChildren()) do
						if BODY[part.Name] and part:IsA("MeshPart") then
							local sa=part:FindFirstChildOfClass("SurfaceAppearance");
							if sa then setp(r,sa,"Parent",nil);end;
						end;
					end;
					local armor=char:FindFirstChild("CharacterArmor");
					if armor then
						for _,p in ipairs(armor:GetDescendants()) do
							if p:IsA("BasePart") then setp(r,p,"Transparency",1);end;
						end;
					end;
					for _,x in ipairs(char:GetDescendants()) do
						if x:IsA("Accessory") then
							for _,p in ipairs(x:GetDescendants()) do
								if p:IsA("BasePart") then setp(r,p,"Transparency",1);end;
							end;
						end;
					end;
					local shirt=model:FindFirstChildWhichIsA("Shirt",true);
					local pants=model:FindFirstChildWhichIsA("Pants",true);
					cloth(char,r,"Shirt","ShirtTemplate",shirt and shirt.ShirtTemplate);
					cloth(char,r,"Pants","PantsTemplate",pants and pants.PantsTemplate);
					local mbc=model:FindFirstChildWhichIsA("BodyColors",true);
					if mbc then
						local bc=char:FindFirstChildOfClass("BodyColors");
						if not bc then
							bc=Instance.new("BodyColors");
							bc.Parent=char;
							r.made[#r.made+1]=bc;
						end;
						for _,p in ipairs({"HeadColor3","TorsoColor3","LeftArmColor3","RightArmColor3","LeftLegColor3","RightLegColor3"}) do
							pcall(function() setp(r,bc,p,mbc[p]);end);
						end;
					end;
					local head=char:FindFirstChild("Head");
					local fd=head and head:FindFirstChildOfClass("Decal");
					if fd then
						for _,x in ipairs(model:GetDescendants()) do
							if x:IsA("Decal") and x.Name:lower()=="face" then
								setp(r,fd,"Texture",x.Texture);
								break;
							end;
						end;
					end;
					local hum=char:FindFirstChildOfClass("Humanoid");
					local n=0;
					for _,acc in ipairs(model:GetDescendants()) do
						if acc:IsA("Accessory") then
							local c=acc:Clone();
							local ok=pcall(function()
								if hum then hum:AddAccessory(c);else c.Parent=char;end;
							end);
							if ok then
								r.made[#r.made+1]=c;
								-- чтобы аим/эсп логика чита считала их аксессуарами, а не хитбоксом
								pcall(CS.AddTag,CS,c,"CharacterAccessory");
								n=n+1;
							end;
						end;
					end;
					local info=(char.Name..": shirt="..(shirt and "y" or "n").." pants="..(pants and "y" or "n").." R="..(hum and tostring(hum.RigType.Name) or "?"));
					return n,info;
				end;

				----------------------------------------------------------------
				-- OVERLAY: полноценная R15-копия аватара, приваренная к частям родной модели игры.
				-- Не зависит от мешей / Humanoid / одежды самой игры: родные части скрываются, оверлей ходит по ним.
				----------------------------------------------------------------
				local BODYSET={Head=1,UpperTorso=1,LowerTorso=1,LeftUpperArm=1,LeftLowerArm=1,LeftHand=1,RightUpperArm=1,RightLowerArm=1,RightHand=1,LeftUpperLeg=1,LeftLowerLeg=1,LeftFoot=1,RightUpperLeg=1,RightLowerLeg=1,RightFoot=1};
				local COLMAP={HeadColor3={"Head"},TorsoColor3={"UpperTorso","LowerTorso"},LeftArmColor3={"LeftUpperArm","LeftLowerArm","LeftHand"},RightArmColor3={"RightUpperArm","RightLowerArm","RightHand"},LeftLegColor3={"LeftUpperLeg","LeftLowerLeg","LeftFoot"},RightLegColor3={"RightUpperLeg","RightLowerLeg","RightFoot"}};
				local tcache=setmetatable({},{__mode="k"});
				-- безопасный клон: Archivable/Clone в pcall (на части потомков "lacking capability Plugin")
				tcache.__lclone=function(d)
	local function try()
		local ok,x=pcall(function() local a=d.Archivable;d.Archivable=true;local c=d:Clone();d.Archivable=a;return c;end);
		return ok and x or nil;
	end;
	local x=try();
	if x then return x;end;
	local bad={};
	for _,ch in ipairs(d:GetDescendants()) do
		local okc,cl=pcall(function() local a=ch.Archivable;ch.Archivable=true;local c=ch:Clone();ch.Archivable=a;return c;end);
		if not(okc and cl) then bad[#bad+1]={ch,ch.Parent};end;
	end;
	for _,b in ipairs(bad) do pcall(function() b[1].Parent=nil;end);end;
	x=try();
	for _,b in ipairs(bad) do pcall(function() b[1].Parent=b[2];end);end;
	if #bad>0 then pcall(function() if M and M.dbg then M.dbg("CLONEBAD "..d.Name.." children="..#bad.." first="..tostring(bad[1][1].ClassName).." "..tostring(bad[1][1].Name).." recovered="..tostring(x~=nil));end;end);end;
	return x;
end;
tcache.__sclone=function(inst)
					local saved={};
					local function mark(d)
						local okA,arch=pcall(function() return d.Archivable;end);
						if okA and arch==false then
							if pcall(function() d.Archivable=true;end) then saved[#saved+1]=d;end;
						end;
					end;
					pcall(mark,inst);
					local okd,desc=pcall(inst.GetDescendants,inst);
					if okd then for _,d in ipairs(desc) do pcall(mark,d);end;end;
					local okc,c=pcall(inst.Clone,inst);
					for _,d in ipairs(saved) do pcall(function() d.Archivable=false;end);end;
					if okc and c then return c;end;
					-- запасной путь: клонируем части/одежду по отдельности и собираем модель вручную
					local okm,mm=pcall(Instance.new,"Model");
					if not(okm and mm) then return nil;end;
					local cmap={};
					for _,d in ipairs(okd and desc or {}) do
						-- FIX: Handle аксессуара уже внутри клона Accessory - второй раз его отдельной деталью не клонируем (двойные шапки/детали)
						local inAcc=d:IsA("BasePart") and d:FindFirstAncestorWhichIsA("Accessory")~=nil;
						if not inAcc and (d:IsA("BasePart") or d:IsA("Accessory") or d:IsA("Clothing") or d:IsA("BodyColors") or d:IsA("ShirtGraphic")) then
							local cc=tcache.__lclone(d);
					local o1=cc~=nil;
					if not cc then pcall(function() if M and M.dbg then M.dbg("CLONEFAIL "..d.ClassName.." "..d.Name);end;end);end;
							if o1 and cc then
								pcall(function() cc.Parent=mm;end);
								if d:IsA("BasePart") then cmap[d]=cc;end;
							end;
						end;
					end;
					-- FIX: Motor6D у модели из CreateHumanoidModelFromDescription не клонируются (Archivable/capability) -> копия без суставов, rig_build=nil, анимации нет.
					-- пересоздаём суставы вручную между клонами частей
					for _,d in ipairs(okd and desc or {}) do
						if d:IsA("Motor6D") then
							pcall(function()
								local a0,a1=cmap[d.Part0],cmap[d.Part1];
								if a0 and a1 then
									local ex=a1:FindFirstChild(d.Name);
									if ex and ex:IsA("Motor6D") then
										ex.Part0=a0;ex.Part1=a1;
									else
										local j=Instance.new("Motor6D");
										j.Name=d.Name;j.C0=d.C0;j.C1=d.C1;j.Part0=a0;j.Part1=a1;j.Parent=a1;
									end;
								end;
							end);
						end;
					end;
					if #mm:GetChildren()==0 then pcall(function() mm:Destroy();end);return nil;end;
					return mm;
				end;
				-- WorldModel: Instance.new("WorldModel") в этом потоке даёт "lacking capability Plugin"; пробуем создать, потом клон из игры, потом обычная Model
				tcache.__wm=function(parent)
					local ok,w=pcall(Instance.new,"WorldModel");
					if not(ok and w) then
						w=nil;
						pcall(function()
							local pg=game:GetService("Players").LocalPlayer:FindFirstChildOfClass("PlayerGui");
							local ex=pg and pg:FindFirstChildWhichIsA("WorldModel",true);
							if ex then
								local c=tcache.__sclone(ex);
								if c then
									for _,x in ipairs(c:GetChildren()) do pcall(function() x:Destroy();end);end;
									w=c;
								end;
							end;
						end);
					end;
					if not w then
						local ok2,m=pcall(Instance.new,"Model");
						if ok2 and m then w=m;end;
					end;
					if w then pcall(function() w.Name="PreviewWM";w.Parent=parent;end);end;
					return w;
				end;
				-- поднимаем identity/caps потока: из хукнутых игровых потоков Instance.new падает с "lacking capability Plugin"
				tcache.__elev=function()
					pcall(function() if setthreadidentity then setthreadidentity(8);end;end);
					pcall(function() if set_thread_identity then set_thread_identity(8);end;end);
					pcall(function() if syn and syn.set_thread_identity then syn.set_thread_identity(8);end;end);
					pcall(function() if setidentity then setidentity(8);end;end);
					pcall(function() if setthreadcaps then setthreadcaps(getthreadcaps and getthreadcaps() or 0xFFFFFFFF);end;end);
				end;
				local function findpart(char,name)
					local d=char:FindFirstChild(name,true);
					if d and d:IsA("BasePart") then return d;end;
					return nil;
				end;
				-- шаблон оверлея: если источник — полная модель с телом, берём её как есть, иначе пустой R15 + одежда/цвета/лицо/аксессуары из источника
				local function make_tpl(src)
					local t=tcache[src];
					if t then return t;end;
					local own=0;
					for _,x in ipairs(src:GetDescendants()) do
						if x:IsA("MeshPart") and BODYSET[x.Name] then own=own+1;end;
					end;
					if own>=8 then
						t=tcache.__sclone(src);
						if not t then return nil;end;
						for _,x in ipairs(t:GetDescendants()) do
							if x:IsA("Script") or x:IsA("LocalScript") then pcall(function() x:Destroy();end);end;
						end;
						tcache[src]=t;
						return t;
					end;
					local dm=Players:CreateHumanoidModelFromDescription(Instance.new("HumanoidDescription"),Enum.HumanoidRigType.R15);
					local hum=dm:FindFirstChildOfClass("Humanoid");
					for _,x in ipairs(dm:GetChildren()) do
						if x:IsA("Shirt") or x:IsA("Pants") or x:IsA("ShirtGraphic") or x:IsA("BodyColors") then pcall(function() x:Destroy();end);end;
					end;
					for _,cls in ipairs({"Shirt","Pants","ShirtGraphic","BodyColors"}) do
						local o=src:FindFirstChildWhichIsA(cls,true);
						if o then o:Clone().Parent=dm;end;
					end;
					local bc=dm:FindFirstChildOfClass("BodyColors");
					if bc then
						for prop,names in pairs(COLMAP) do
							local ok,col=pcall(function() return bc[prop];end);
							if ok and col then
								for _,nm in ipairs(names) do
									local p=dm:FindFirstChild(nm);
									if p then p.Color=col;end;
								end;
							end;
						end;
					end;
					local head=dm:FindFirstChild("Head");
					if head then
						local face;
						for _,x in ipairs(src:GetDescendants()) do
							if x:IsA("Decal") and x.Name:lower()=="face" then face=x;break;end;
						end;
						if face then
							local fd=head:FindFirstChildOfClass("Decal");
							if not fd then
								fd=Instance.new("Decal");
								fd.Name="face";
								fd.Face=Enum.NormalId.Front;
								fd.Parent=head;
							end;
							fd.Texture=face.Texture;
						end;
					end;
					for _,acc in ipairs(src:GetDescendants()) do
						if acc:IsA("Accessory") then
							local c=acc:Clone();
							local ok=false;
							if hum then ok=pcall(function() hum:AddAccessory(c);end);end;
							if not ok then pcall(function() c.Parent=dm;end);end;
						end;
					end;
					tcache[src]=dm;
					return dm;
				end;

				-- вешаем оверлей на персонажа. Возвращает число приваренных частей (или nil, причина)
				do
					M.dbgl={"BUILD nyx-p8 armfk+gun"};
					local gui,box,dirty;
					local function ui_parent()
						local ok,h=pcall(function() return gethui and gethui();end);
						if ok and h then return h;end;
						local ok2,cg=pcall(function() return game:GetService("CoreGui");end);
						if ok2 and cg then return cg;end;
						return game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui");
					end;
					local function build()
						if gui and gui.Parent then return;end;
						gui=Instance.new("ScreenGui");
						gui.Name="KW_DBG";gui.ResetOnSpawn=false;gui.DisplayOrder=2000000;gui.IgnoreGuiInset=true;
						local f=Instance.new("Frame");
						f.Size=UDim2.new(0.62,0,0.5,0);f.Position=UDim2.new(0.02,0,0.46,0);
						f.BackgroundColor3=Color3.fromRGB(10,10,14);f.BackgroundTransparency=0.05;f.Parent=gui;
						local sc=Instance.new("ScrollingFrame");
						sc.Size=UDim2.new(1,-8,1,-34);sc.Position=UDim2.fromOffset(4,30);sc.BackgroundTransparency=1;
						sc.AutomaticCanvasSize=Enum.AutomaticSize.Y;sc.CanvasSize=UDim2.new();sc.ScrollBarThickness=6;sc.Parent=f;
						box=Instance.new("TextBox");
						box.Size=UDim2.new(1,-8,0,0);box.AutomaticSize=Enum.AutomaticSize.Y;box.BackgroundTransparency=1;
						box.MultiLine=true;box.TextWrapped=true;box.ClearTextOnFocus=false;box.TextEditable=false;
						box.TextXAlignment=Enum.TextXAlignment.Left;box.TextYAlignment=Enum.TextYAlignment.Top;
						box.Font=Enum.Font.Code;box.TextSize=11;box.TextColor3=Color3.fromRGB(220,230,255);box.Text="";box.Parent=sc;
						local function btn(txt,x,cb)
							local b=Instance.new("TextButton");
							b.Size=UDim2.fromOffset(70,24);b.Position=UDim2.new(1,x,0,3);b.Text=txt;b.TextSize=13;
							b.BackgroundColor3=Color3.fromRGB(45,45,70);b.TextColor3=Color3.new(1,1,1);b.Parent=f;
							b.MouseButton1Click:Connect(cb);
						end;
						btn("close",-74,function() gui.Enabled=false;end);
						btn("copy",-148,function() pcall(function() setclipboard(table.concat(M.dbgl,"\n"));end);end);
						local t=Instance.new("TextLabel");
						t.Size=UDim2.new(1,-160,0,24);t.Position=UDim2.fromOffset(6,3);t.BackgroundTransparency=1;
						t.Text="killed.wtf debug";t.TextColor3=Color3.new(1,1,1);t.TextSize=13;t.TextXAlignment=Enum.TextXAlignment.Left;t.Parent=f;
						pcall(function() gui.Parent=ui_parent();end);
					end;
					-- FIX: M.dbg только копит буфер (последние 300 строк). Окно / файл / буфер обмена - по кнопке M.dbgkey (F8)
					-- FIX (кривые кости в лобби): как в эталонной версии - каждая часть скина просто идёт за родной, без цепочки суставов, IK и подгонки длины.
					-- вернуть IK/цепочку: M.no_joint_chain=false (до первого оверлея)
					if M.no_joint_chain==nil then M.no_joint_chain=true;end;
					M.dbg=function(line)
						local t=M.dbgl;t[#t+1]=string.format("[%.2f] ",os.clock())..tostring(line);
						if #t>300 then table.remove(t,1);end;
					end;
					M.dbgkey=M.dbgkey or Enum.KeyCode.F8;
					M.dbg_toggle=function()
						if gui and gui.Parent and gui.Enabled then gui.Enabled=false;return;end;
						if M.snap then pcall(M.snap);end;
						local txt=table.concat(M.dbgl,"\n");
						pcall(function() if writefile then writefile("preview_debug.txt",txt);end;end);
						pcall(function() if setclipboard then setclipboard(txt);end;end);
						pcall(function() build();gui.Enabled=true;box.Text=txt;end);
					end;
					pcall(function()
						local UIS=game:GetService("UserInputService");
						if M.dbg_conn then pcall(function() M.dbg_conn:Disconnect();end);end;
						M.dbg_conn=UIS.InputBegan:Connect(function(i)
							if i.KeyCode==M.dbgkey and not UIS:GetFocusedTextBox() then pcall(M.dbg_toggle);end;
						end);
					end);
					-- FIX: экранная кнопка DBG для телефона (F8 там нечем нажать)
					pcall(function()
						if M.dbg_btn then pcall(function() M.dbg_btn:Destroy();end);end;
						local sg=Instance.new("ScreenGui");
						sg.Name="KW_DBGBTN";sg.ResetOnSpawn=false;sg.DisplayOrder=2000001;sg.IgnoreGuiInset=true;
						local b=Instance.new("TextButton");
						b.Size=UDim2.fromOffset(52,52);b.Position=UDim2.new(0,8,0.72,0);
						b.BackgroundColor3=Color3.fromRGB(20,20,28);b.BackgroundTransparency=0.15;
						b.Text="DBG";b.TextColor3=Color3.new(1,1,1);b.TextSize=16;b.Font=Enum.Font.GothamBold;b.AutoButtonColor=true;b.Parent=sg;
						local cr=Instance.new("UICorner");cr.CornerRadius=UDim.new(0,12);cr.Parent=b;
						b.Activated:Connect(function() pcall(M.dbg_toggle);end);
						pcall(function() sg.Parent=ui_parent();end);
						M.dbg_btn=sg;
					end);
				end;
				local function overlay(char,tpl,w)
					if not M.dbg then
						M.dbgl={"BUILD nyx-p8 armfk+gun"};
						M.dbg=function(line)
							local t=M.dbgl;t[#t+1]=string.format("[%.2f] ",os.clock())..tostring(line);
							if #t>300 then table.remove(t,1);end;
							if M.dbgq then return;end;
							M.dbgq=true;
							task.delay(1.5,function()
								M.dbgq=false;
								local txt=table.concat(M.dbgl,"\n");
								pcall(function() if writefile then writefile("preview_debug.txt",txt);end;end);
								pcall(function() if setclipboard then setclipboard(txt);end;end);
							end);
						end;
					end;
					if not(char and char.Parent and tpl) then return nil,"нет персонажа";end;
					restore(char);
					local r=rec_of(char);
					r.want=w;
					local dm=tpl:Clone();
					dm.Name="ClientOverlay";
					local hum=dm:FindFirstChildOfClass("Humanoid");
					if hum then
						pcall(function()
							hum.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None;
							hum.HealthDisplayType=Enum.HumanoidHealthDisplayType.AlwaysOff;
							hum.RequiresNeck=false;
							hum.BreakJointsOnDeath=false;
							hum.WalkSpeed=0;
							hum.JumpPower=0;
						end);
					end;
					local jrel,s0={},1;
					pcall(function() s0=dm:GetScale();end);
					-- суставы между частями оверлея дрались бы с приварками к родной модели
					for _,d in ipairs(dm:GetChildren()) do
						if d:IsA("BasePart") then
							for _,j in ipairs(d:GetChildren()) do
								if j:IsA("Motor6D") then
									if j.Part0 and j.Part1==d and j.Part0.Parent==dm then jrel[d.Name]={j.Part0,j.Part0.CFrame:ToObjectSpace(d.CFrame)};end;
									pcall(function() j:Destroy();end);
								end;
							end;
						end;
					end;
					local pts={};
					for _,d in ipairs(dm:GetDescendants()) do
						if d:IsA("BasePart") then
							d.Anchored=false;
							d.CanCollide=false;
							d.CanQuery=false;
							d.CanTouch=false;
							d.Massless=true;
							pcall(CS.AddTag,CS,d,"CharacterAccessory");
							if d.Name=="HumanoidRootPart" then
								d.Transparency=1;
							else
								pts[#pts+1]=d;
							end;
						end;
					end;
					-- подгоняем масштаб под родную модель
					local ct,dt=findpart(char,"UpperTorso"),dm:FindFirstChild("UpperTorso");
					if ct and dt and dt.Size.Y>0 then
						local ratio=ct.Size.Y/dt.Size.Y;
						if ratio>0.3 and ratio<3 and math.abs(ratio-1)>0.03 then
							pcall(function() dm:ScaleTo(dm:GetScale()*ratio);end);
						end;
					end;
					-- FIX (лобби): масштаб по длине рук/ног, а не только по высоте торса - иначе у скина конечности короче родных и кисти/стопы не достают (рука отрывалась, ноги левитировали).
					-- масштаб только по ногам (чтобы стояли на земле без глубокого приседа); руки длиннее/короче - IK сам подгонит
					if M.lobby and char==M.lobby and M.use_joint_chain then
						pcall(function()
							local function blen(part,a,b)
								local x,y=part and part:FindFirstChild(a),part and part:FindFirstChild(b);
								if x and y and x:IsA("Attachment") and y:IsA("Attachment") then return (x.CFrame.Position-y.CFrame.Position).Magnitude;end;
								return nil;
							end;
							local function limb(side,kind)
								local U,Lw,A,B,C;
								if kind=="arm" then U,Lw,A,B,C=side.."UpperArm",side.."LowerArm",side.."ShoulderRigAttachment",side.."ElbowRigAttachment",side.."WristRigAttachment";
								else U,Lw,A,B,C=side.."UpperLeg",side.."LowerLeg",side.."HipRigAttachment",side.."KneeRigAttachment",side.."AnkleRigAttachment";end;
								local function total(getp)
									local l1=blen(getp(U),A,B);
									local l2=blen(getp(Lw),B,C);
									return (l1 and l2) and (l1+l2) or nil;
								end;
								local ln=total(function(n) return findpart(char,n);end);
								local lo=total(function(n) return dm:FindFirstChild(n);end);
								if ln and lo and lo>0.01 then return ln/lo;end;
								return nil;
							end;
							local f;
							local fl,fr=limb("Left","leg"),limb("Right","leg");
							if fl and fr then f=(fl+fr)/2;else f=fl or fr;end;
							if f then
								f=math.clamp(f,0.8,1.3);
								if math.abs(f-1)>0.02 then dm:ScaleTo(dm:GetScale()*f);end;
								pcall(function() if M.dbg then M.dbg(string.format("LIMBSCALE f=%.3f",f));end;end);
							end;
						end);
					end;

					-- FIX (кривые руки/ноги в лобби): у скина конечности короче родных, IK не достаёт до родных кистей/стоп (IKREACH unreachable=true),
					-- конечность выпрямляется и торчит криво. подгоняем длину КАЖДОЙ конечности скина под родную (только удлиняем, макс x1.35).
					-- выключить: M.no_limb_match=true
					if M.lobby and char==M.lobby and M.use_joint_chain and not M.no_limb_match and (getgenv and getgenv().Z_LIMB_MATCH)==true then
						pcall(function()
							local function blen2(part,a,b)
								local x,y=part and part:FindFirstChild(a),part and part:FindFirstChild(b);
								if x and y and x:IsA("Attachment") and y:IsA("Attachment") then return (x.CFrame.Position-y.CFrame.Position).Magnitude;end;
								return nil;
							end;
							local function total2(pU,pL,A,B,C)
								local l1,l2=blen2(pU,A,B),blen2(pL,B,C);
								return (l1 and l2) and (l1+l2) or nil;
							end;
							local function sp(p,r)
								if p and p:IsA("BasePart") then
									p.Size=p.Size*r;
									for _,a in ipairs(p:GetChildren()) do
										if a:IsA("Attachment") then a.Position=a.Position*r;end;
									end;
								end;
							end;
							for _,side in ipairs({"Left","Right"}) do
								for _,kind in ipairs({"arm","leg"}) do
									local U,Lw,A,B,C;
									if kind=="arm" then U,Lw,A,B,C=side.."UpperArm",side.."LowerArm",side.."ShoulderRigAttachment",side.."ElbowRigAttachment",side.."WristRigAttachment";
									else U,Lw,A,B,C=side.."UpperLeg",side.."LowerLeg",side.."HipRigAttachment",side.."KneeRigAttachment",side.."AnkleRigAttachment";end;
									local ln=total2(findpart(char,U),findpart(char,Lw),A,B,C);
									local lo=total2(dm:FindFirstChild(U),dm:FindFirstChild(Lw),A,B,C);
									if ln and lo and lo>0.01 then
										local r=math.clamp(ln/lo,1,1.35);
										if r>1.03 then
											sp(dm:FindFirstChild(U),r);
											sp(dm:FindFirstChild(Lw),r);
											pcall(function() if M.dbg then M.dbg(string.format("LIMBMATCH %s%s r=%.3f",side,kind,r));end;end);
										end;
									end;
								end;
							end;
						end);
					end;
					local holder=workspace:FindFirstChild("ClientOverlay");
					if not holder then
						holder=Instance.new("Folder");
						holder.Name="ClientOverlay";
						holder.Parent=workspace;
					end;
					dm.Parent=holder;
					-- FIX: оверлей садится на родные части по суставным аттачментам (а не по центрам частей) -
					-- у родного рига пивоты/ориентации частей могут отличаться от стандартного R15, из-за этого конечности "разлетались"
					local JOINTATT={HumanoidRootPart="RootRigAttachment",LowerTorso="RootRigAttachment",UpperTorso="WaistRigAttachment",Head="NeckRigAttachment",
						LeftUpperArm="LeftShoulderRigAttachment",LeftLowerArm="LeftElbowRigAttachment",LeftHand="LeftWristRigAttachment",
						RightUpperArm="RightShoulderRigAttachment",RightLowerArm="RightElbowRigAttachment",RightHand="RightWristRigAttachment",
						LeftUpperLeg="LeftHipRigAttachment",LeftLowerLeg="LeftKneeRigAttachment",LeftFoot="LeftAnkleRigAttachment",
						RightUpperLeg="RightHipRigAttachment",RightLowerLeg="RightKneeRigAttachment",RightFoot="RightAnkleRigAttachment"};
					local islobby=(M.lobby and char==M.lobby) and true or false;
					local welds,origs,welded={}, {},0;
					local natw={};
					local tcf={};
					for _,tp in ipairs(dm:GetChildren()) do if tp:IsA("BasePart") then tcf[tp]=tp.CFrame;end;end;
					local drive={};
					local placed={};
					for _,p in ipairs(dm:GetChildren()) do
						if p:IsA("BasePart") and (BODYSET[p.Name] or p.Name=="HumanoidRootPart") then
							local o=findpart(char,p.Name);
							if o then
								local c0,c1=CFrame.new(),CFrame.new();
								local jn=JOINTATT[p.Name];
								local oa=jn and o:FindFirstChild(jn);
								local pa=jn and p:FindFirstChild(jn);
								if oa and pa and oa:IsA("Attachment") and pa:IsA("Attachment") then
									c0,c1=oa.CFrame,pa.CFrame;
								end;
								p.CFrame=o.CFrame*c0*c1:Inverse();
								-- страховка: если по аттачментам часть улетела от родной больше чем на её габарит - откат на совмещение по центрам
								if (p.Position-o.Position).Magnitude>math.max(o.Size.Magnitude,2) then
									c0,c1=CFrame.new(),CFrame.new();
									p.CFrame=o.CFrame;
								end;
								if islobby then
									-- лобби: без сварок (сварка с якорной частью тянула бы родную модель), часть якорится и каждый кадр ставится по родной со смещением
									p.Anchored=true;
									drive[#drive+1]={p,o,o.CFrame:ToObjectSpace(p.CFrame)};
								else
									local wd=Instance.new("Weld");
									wd.Name="OverlayWeld";
									wd.Part0=o;
									wd.Part1=p;
									wd.C0=c0;
										natw[#natw+1]={wd,o,c0};
									wd.C1=c1;
									wd.Parent=p;
									welds[#welds+1]=wd;
								end;
								welded=welded+1;
								placed[p]=true;
								if BODYSET[p.Name] then origs[#origs+1]=o;end;
							end;
						end;
					end;
					-- талия: LowerTorso сажаем относительно UpperTorso так же, как в шаблоне (по аттачментам родного рига он уезжал и между торсом и ногами была дыра)
					do
						local UT,LT=dm:FindFirstChild("UpperTorso"),dm:FindFirstChild("LowerTorso");
						if UT and LT and placed[UT] and placed[LT] and tcf[UT] and tcf[LT] then
							local rel=tcf[UT]:ToObjectSpace(tcf[LT]);
							local want=UT.CFrame*rel;
							local gap=(LT.Position-want.Position).Magnitude;
							pcall(function() if M.dbg then M.dbg(string.format("WAIST tplgap=%.2f placedgap=%.2f fix=%s lobby=%s",rel.Position.Magnitude,(LT.Position-UT.Position).Magnitude,tostring(gap>0.08),tostring(islobby)));end;end);
							if gap>0.08 then
								LT.CFrame=want;
								if islobby then
									for _,e in ipairs(drive) do
										if e[1]==LT then
											for _,e2 in ipairs(drive) do
												if e2[1]==UT then e[2]=e2[2];e[3]=e2[2].CFrame:ToObjectSpace(want);break;end;
											end;
										end;
									end;
								else
									local wd=LT:FindFirstChild("OverlayWeld");
									if wd then wd.Part0=UT;wd.C0=rel;wd.C1=CFrame.new();end;
								end;
							end;
						end;
					end;
					-- части оверлея без родной пары: сажаем на родителя оверлея по исходному суставу шаблона
					local fac=1;
					pcall(function() fac=dm:GetScale()/(s0>0 and s0 or 1);end);
					for _=1,4 do
						for _,p in ipairs(dm:GetChildren()) do
							if p:IsA("BasePart") and not placed[p] and p.Name~="HumanoidRootPart" then
								local ji=jrel[p.Name];
								local par=ji and ji[1];
								if par and placed[par] then
									local rel=CFrame.new(ji[2].Position*fac)*ji[2].Rotation;
									p.CFrame=par.CFrame*rel;
									if islobby then
										p.Anchored=true;
										drive[#drive+1]={p,par,par.CFrame:ToObjectSpace(p.CFrame),true};
									else
										local wd=Instance.new("Weld");
										wd.Name="OverlayWeld";
										wd.Part0=par;
										wd.Part1=p;
										wd.C0=rel;
										wd.C1=CFrame.new();
										wd.Parent=p;
										welds[#welds+1]=wd;
									end;
									placed[p]=true;
								end;
							end;
						end;
					end;
					do
						local q;
						for _,nm in ipairs({"LowerTorso","UpperTorso","Head"}) do
							local c=dm:FindFirstChild(nm);
							if c and placed[c] then q=c;break;end;
						end;
						if not q then for c in pairs(placed) do q=c;break;end;end;
						if q and tcf[q] then
							for _,p in ipairs(dm:GetChildren()) do
								if p:IsA("BasePart") and not placed[p] and p.Name~="HumanoidRootPart" and tcf[p] then
									local rel=tcf[q]:ToObjectSpace(tcf[p]);
									p.CFrame=q.CFrame*rel;
									if islobby then
										p.Anchored=true;
										drive[#drive+1]={p,q,q.CFrame:ToObjectSpace(p.CFrame),true};
									else
										local wd=Instance.new("Weld");
										wd.Name="OverlayWeld";
										wd.Part0=q;wd.Part1=p;wd.C0=rel;wd.C1=CFrame.new();
										wd.Parent=p;
										welds[#welds+1]=wd;
									end;
									placed[p]=true;
								end;
							end;
						end;
					end;
					pcall(function()
						local nat,ovl={}, {};
						local hrp=findpart(char,"HumanoidRootPart");
						for _,d in ipairs(char:GetDescendants()) do
							if d:IsA("BasePart") and not d:FindFirstAncestorWhichIsA("Accessory") then nat[#nat+1]=d.Name.."("..d.ClassName.." T"..string.format("%.1f",d.Transparency)..")";end;
						end;
						for _,q in ipairs(dm:GetChildren()) do
							if q:IsA("BasePart") then ovl[#ovl+1]=q.Name..(placed[q] and "+" or "-").." d"..string.format("%.1f",hrp and (q.Position-hrp.Position).Magnitude or -1);end;
						end;
						M.dbg("OVERLAY w="..tostring(w).." char="..char:GetFullName().." lobby="..tostring(islobby).." welded="..welded.." tplParts="..#ovl);
						M.dbg(" NATIVE: "..table.concat(nat,", "));
						M.dbg(" OVERLAY(+placed/-not, dist from native root): "..table.concat(ovl,", "));
					end);
					if welded==0 then
						pcall(function() dm:Destroy();end);
						return nil,"в модели нет R15-частей (UpperTorso и т.д.)";
					end;
					r.made[#r.made+1]=dm;
					r.dummy,r.welds,r.pts,r.hide,r.head=dm,welds,pts,{},findpart(char,"Head");
					-- FIX (лобби): руки/ноги/голова разъезжались с торсом, потому что каждая часть оверлея шла за СВОЕЙ родной частью отдельно.
					-- теперь части сидят цепочкой: ребёнок = сустав родителя оверлея * поза этого сустава у родного рига * свой аттачмент. суставы всегда сходятся.
					-- выключить: M.no_joint_chain=true
					if islobby and M.use_joint_chain then
						local ORDER={{"UpperTorso","LowerTorso"},{"Head","UpperTorso"},{"LeftUpperArm","UpperTorso"},{"LeftLowerArm","LeftUpperArm"},{"LeftHand","LeftLowerArm"},
							{"RightUpperArm","UpperTorso"},{"RightLowerArm","RightUpperArm"},{"RightHand","RightLowerArm"},
							{"LeftUpperLeg","LowerTorso"},{"LeftLowerLeg","LeftUpperLeg"},{"LeftFoot","LeftLowerLeg"},
							{"RightUpperLeg","LowerTorso"},{"RightLowerLeg","RightUpperLeg"},{"RightFoot","RightLowerLeg"}};
						local chain,skip={}, {};
						for _,lk in ipairs(ORDER) do
							local cn,pn=lk[1],lk[2];
							local oc,op=dm:FindFirstChild(cn),dm:FindFirstChild(pn);
							local nc,np=findpart(char,cn),findpart(char,pn);
							local an=JOINTATT[cn];
							if oc and op and nc and np and an and placed[oc] and placed[op] then
								local oca,opa,nca,npa=oc:FindFirstChild(an),op:FindFirstChild(an),nc:FindFirstChild(an),np:FindFirstChild(an);
								if oca and opa and nca and npa and oca:IsA("Attachment") and opa:IsA("Attachment") and nca:IsA("Attachment") and npa:IsA("Attachment") then
									chain[#chain+1]={oc,op,nc,np,oca.CFrame:Inverse(),opa.CFrame,nca.CFrame,npa.CFrame};
									skip[oc]=true;
								end;
							end;
						end;
						if #chain>0 then r.chain,r.chain_skip=chain,skip;end;
						-- конечности: 2-костный IK. кисть/стопа ставятся ТОЧНО в родные (ствол в руках, ноги на земле), локоть/колено считаются по длинам костей скина
						local LIMBS={
							{"LeftUpperArm","LeftLowerArm","LeftHand","LeftShoulderRigAttachment","LeftElbowRigAttachment","LeftWristRigAttachment"},
							{"RightUpperArm","RightLowerArm","RightHand","RightShoulderRigAttachment","RightElbowRigAttachment","RightWristRigAttachment"},
							{"LeftUpperLeg","LeftLowerLeg","LeftFoot","LeftHipRigAttachment","LeftKneeRigAttachment","LeftAnkleRigAttachment"},
							{"RightUpperLeg","RightLowerLeg","RightFoot","RightHipRigAttachment","RightKneeRigAttachment","RightAnkleRigAttachment"}};
						local limbs={};
						for _,lm in ipairs(LIMBS) do
							local oU,oL,oE=dm:FindFirstChild(lm[1]),dm:FindFirstChild(lm[2]),dm:FindFirstChild(lm[3]);
							local nE=findpart(char,lm[3]);
							if oU and oL and oE and nE and skip[oU] and skip[oL] and skip[oE] then
								local sh,el1,el2,wr1,wr2,nwr=oU:FindFirstChild(lm[4]),oU:FindFirstChild(lm[5]),oL:FindFirstChild(lm[5]),oL:FindFirstChild(lm[6]),oE:FindFirstChild(lm[6]),nE:FindFirstChild(lm[6]);
								if sh and el1 and el2 and wr1 and wr2 and nwr and sh:IsA("Attachment") and el1:IsA("Attachment") and el2:IsA("Attachment") and wr1:IsA("Attachment") and wr2:IsA("Attachment") and nwr:IsA("Attachment") then
									local nU=findpart(char,lm[1]);
									local nsh,nel=nU and nU:FindFirstChild(lm[4]),nU and nU:FindFirstChild(lm[5]);
									limbs[#limbs+1]={oU,oL,oE,nE,sh.CFrame,el1.CFrame,el2.CFrame,wr1.CFrame,wr2.CFrame,nwr.CFrame,
										(nU and nsh and nel and nsh:IsA("Attachment") and nel:IsA("Attachment")) and nU or nil,nsh and nsh.CFrame,nel and nel.CFrame,
										findpart(char,lm[2]),(findpart(char,lm[2]) and findpart(char,lm[2]):FindFirstChild(lm[6]) and findpart(char,lm[2]):FindFirstChild(lm[6]).CFrame) or nil};
								end;
							end;
						end;
						if #limbs>0 then r.limbs=limbs;end;
						pcall(function() if M.dbg then M.dbg("LIMBIK limbs="..#limbs.."/4");end;end);
						pcall(function() if M.dbg then M.dbg("JOINTCHAIN links="..#chain.."/14");end;end);
					end;
					-- FIX (лобби, дыра между торсом и ногами): части скина идут за родными, но у родной модели бёдра/колени/щиколотки стоят не там, где у скина,
					-- поэтому между торсом и ногами была щель. теперь ноги сшиваются по СУСТАВНЫМ аттачментам скина (бедро -> LowerTorso, колено -> бедро, щиколотка -> голень).
					-- только сдвиг: масштаб не трогаем (длины костей скина как есть), поворот не трогаем (оси как у родных костей).
					-- выключить: M.no_leg_snap=true
					if islobby and not M.use_joint_chain and not M.no_leg_snap then
						local snaps={};
						-- NOSTRETCH: то же сшивание суставов (только сдвиг, без масштаба и поворота) для рук и шеи. выключить: getgenv().Z_UPPER_SNAP=false
						local upperSnap=(getgenv and getgenv().Z_UPPER_SNAP)~=false;
						local function att(pt,n) local a=pt and pt:FindFirstChild(n);if a and a:IsA("Attachment") then return a;end;return nil;end;
						for _,side in ipairs({"Left","Right"}) do
							local links={
								{"LowerTorso",side.."UpperLeg",side.."HipRigAttachment"},
								{side.."UpperLeg",side.."LowerLeg",side.."KneeRigAttachment"},
								{side.."LowerLeg",side.."Foot",side.."AnkleRigAttachment"}};
							if upperSnap then
								links[#links+1]={"UpperTorso",side.."UpperArm",side.."ShoulderRigAttachment",1};
								links[#links+1]={side.."UpperArm",side.."LowerArm",side.."ElbowRigAttachment",1};
								links[#links+1]={side.."LowerArm",side.."Hand",side.."WristRigAttachment",1};
							end;
							for _,lk in ipairs(links) do
								local par,ch=dm:FindFirstChild(lk[1]),dm:FindFirstChild(lk[2]);
								local pa,ca=att(par,lk[3]),att(ch,lk[3]);
								if par and ch and pa and ca and placed[par] and placed[ch] then snaps[#snaps+1]={par,ch,pa,ca,lk[4]};end;
							end;
						end;
						if upperSnap then
							local par,ch=dm:FindFirstChild("UpperTorso"),dm:FindFirstChild("Head");
							local pa,ca=att(par,"NeckRigAttachment"),att(ch,"NeckRigAttachment");
							if par and ch and pa and ca and placed[par] and placed[ch] then snaps[#snaps+1]={par,ch,pa,ca,1};end;
						end;
						if #snaps>0 then r.snaps=snaps;end;
						pcall(function() if M.dbg then M.dbg("LEGSNAP links="..#snaps..(upperSnap and "/13 (legs+arms+neck)" or "/6"));end;end);
					end;
					-- ARMIK: кисти скина строго в родные кисти, ориентация кисти как у родной (абсолютная). только руки, кости не тянем. выключить: getgenv().Z_ARM_IK=false
					-- GUNFOLLOW: родной ган в лобби прячется, вместо него клон, который сидит в кисти СКИНА (тот же хват, что у родной кисти). выключить: getgenv().Z_GUN_FOLLOW=false
					if islobby and not M.use_joint_chain and not M.no_arm_ik and (getgenv and getgenv().Z_ARM_IK)~=false then
						pcall(function()
							local function att(pt,n) local a=pt and pt:FindFirstChild(n);if a and a:IsA("Attachment") then return a;end;return nil;end;
							local limbs={};
							local rightL;
							for _,side in ipairs({"Left","Right"}) do
								local nU0,nL0,nH0=side.."UpperArm",side.."LowerArm",side.."Hand";
								local SH,EL,WR=side.."ShoulderRigAttachment",side.."ElbowRigAttachment",side.."WristRigAttachment";
								local oU,oL,oE=dm:FindFirstChild(nU0),dm:FindFirstChild(nL0),dm:FindFirstChild(nH0);
								local nE,nU,nL=findpart(char,nH0),findpart(char,nU0),findpart(char,nL0);
								if oU and oL and oE and nE and placed[oU] and placed[oL] and placed[oE] then
									local sh,el1,el2,wr1,wr2,nwr=att(oU,SH),att(oU,EL),att(oL,EL),att(oL,WR),att(oE,WR),att(nE,WR);
									if sh and el1 and el2 and wr1 and wr2 and nwr then
										local nsh,nel,nlw=att(nU,SH),att(nU,EL),att(nL,WR);
										limbs[#limbs+1]={oU,oL,oE,nE,sh.CFrame,el1.CFrame,el2.CFrame,wr1.CFrame,wr2.CFrame,nwr.CFrame,
											(nU and nsh and nel) and nU or nil,nsh and nsh.CFrame,nel and nel.CFrame,nL,nlw and nlw.CFrame};
										if side=="Right" then rightL={nE,nwr.CFrame,oE,wr2.CFrame};end;
									else
										M.dbg("ARMIK skip "..side.." native wrist att="..tostring(nwr~=nil).." skin wrist att="..tostring(wr1~=nil and wr2~=nil));
									end;
								end;
							end;
							if #limbs>0 then r.limbs=limbs;end;
							M.dbg("ARMIK limbs="..#limbs.."/2");
							-- ARMFK: руки скина идут по цепочке СВОИХ суставов от торса скина, поза каждого сустава берётся с родной руки лобби-агента (так же, как в превью).
							-- рукав больше не отрывается от плеча (раньше IK «подъезжал» к родной кисти и сдвигал всю руку). выключить: getgenv().Z_ARM_FK=false
							if (getgenv and getgenv().Z_ARM_FK)~=false then
								local fk,keep={},{};
								for _,side in ipairs({"Left","Right"}) do
									local nm3={side.."UpperArm",side.."LowerArm",side.."Hand"};
									local pm3={"UpperTorso",side.."UpperArm",side.."LowerArm"};
									local an3={side.."ShoulderRigAttachment",side.."ElbowRigAttachment",side.."WristRigAttachment"};
									local links,good={},true;
									for i=1,3 do
										local sc,sp=dm:FindFirstChild(nm3[i]),dm:FindFirstChild(pm3[i]);
										local nc,np=findpart(char,nm3[i]),findpart(char,pm3[i]);
										if sc and sp and nc and np and placed[sc] and placed[sp] then
											local pa,ca=att(sp,an3[i]),att(sc,an3[i]);
											links[#links+1]={sc,sp,np,nc,pa and pa.CFrame,ca and ca.CFrame};
										else
											good=false;
											break;
										end;
									end;
									if good then fk[#fk+1]=links;keep[side]=true;end;
								end;
								if #fk>0 then
									r.armfk=fk;
									-- IK для рук, которые теперь идут по цепочке, не нужен
									if r.limbs then
										local rest={};
										for _,L in ipairs(r.limbs) do
											local sd=(L[1].Name:sub(1,4)=="Left") and "Left" or "Right";
											if not keep[sd] then rest[#rest+1]=L;end;
										end;
										r.limbs=(#rest>0) and rest or nil;
									end;
								end;
								M.dbg("ARMFK arms="..#fk.."/2");
							end;
							if rightL and (getgenv and getgenv().Z_GUN_FOLLOW)~=false then
								local mz=char:FindFirstChild("MuzzlePart",true);
								local w=mz and mz.Parent;
								if w and w~=char and not BODYSET[w.Name] and w.Name~="HumanoidRootPart" and not w:IsA("Accessory") then
									for _=1,3 do
										local pr=w.Parent;
										if not pr or pr==char or BODYSET[pr.Name] or pr.Name=="HumanoidRootPart" or pr:IsA("Accessory") then break;end;
										local direct=0;
										for _,cc in ipairs(w:GetChildren()) do if cc:IsA("BasePart") and cc.Transparency<0.9 then direct=direct+1;end;end;
										if w.Name:lower()=="interactables" or direct==0 then w=pr;else break;end;
									end;
									local gc=tcache.__sclone(w);
									if gc then
										local prs={};
										local function walk(a,b)
											if a:IsA("BasePart") and b:IsA("BasePart") then prs[#prs+1]={a,b};end;
											local ca,cb=a:GetChildren(),b:GetChildren();
											if #ca==#cb then
												for i=1,#ca do walk(ca[i],cb[i]);end;
											else
												local used={};
												for _,x in ipairs(ca) do
													for j,y in ipairs(cb) do
														if not used[j] and y.Name==x.Name and y.ClassName==x.ClassName then used[j]=true;walk(x,y);break;end;
													end;
												end;
											end;
										end;
										walk(w,gc);
										if #prs>0 then
											for _,x in ipairs(gc:GetDescendants()) do
												if x:IsA("BaseScript") or x:IsA("JointInstance") or x:IsA("WeldConstraint") then pcall(function() x:Destroy();end);end;
											end;
											local paired={};
											for _,pr in ipairs(prs) do paired[pr[2]]=true;end;
											local function fix(x)
												x.Anchored=true;x.CanCollide=false;x.CanQuery=false;x.CanTouch=false;x.Massless=true;
												if not paired[x] then x.Transparency=1;end;
											end;
											if gc:IsA("BasePart") then fix(gc);end;
											for _,x in ipairs(gc:GetDescendants()) do
												if x:IsA("BasePart") then fix(x);end;
											end;
											for _,x in ipairs(w:GetDescendants()) do
												if x:IsA("BasePart") or x:IsA("Decal") or x:IsA("Texture") then setp(r,x,"Transparency",1);r.hide[#r.hide+1]=x;end;
											end;
											if w:IsA("BasePart") then setp(r,w,"Transparency",1);r.hide[#r.hide+1]=w;end;
											gc.Name="OverlayGun";
											gc.Parent=holder;
											r.gunc=gc;
											r.gunf={char=char,root=w,gc=gc,nH=rightL[1],nA=rightL[2],sH=rightL[3],sA=rightL[4],pairs=prs};
											M.dbg("GUNFOLLOW root="..w:GetFullName().." pairs="..#prs);
										else
											pcall(function() gc:Destroy();end);
											M.dbg("GUNFOLLOW skip: no part pairs for "..w:GetFullName());
										end;
									else
										M.dbg("GUNFOLLOW skip: clone failed "..w:GetFullName());
									end;
								else
									M.dbg("GUNFOLLOW skip: no weapon root (MuzzlePart)");
								end;
							end;
						end);
					end;
					if islobby and #drive>0 then r.drive=drive;end;
					-- DROP: опускаем скин так, чтобы его стопы стояли там же, где родные (на земле). выключить: getgenv().Z_SKIN_DROP=false, вручную: getgenv().Z_SKIN_DROP=0.3 (studs)
					do
						local fs,fn={}, {};
						for _,nm in ipairs({"LeftFoot","RightFoot"}) do
							local sp,np=dm:FindFirstChild(nm),findpart(char,nm);
							if sp and np and sp:IsA("BasePart") and np:IsA("BasePart") then fs[#fs+1]=sp;fn[#fn+1]=np;end;
						end;
						r.drop={fs=fs,fn=fn,dd=0};
						if not islobby then r.dropw=natw;end;
					end;
					-- родные части скрываем (и держим скрытыми каждый кадр, см. RenderStepped)
					for _,o in ipairs(origs) do
						setp(r,o,"Transparency",1);
						r.hide[#r.hide+1]=o;
					end;
					local nhead=findpart(char,"Head");
					if nhead then
						for _,x in ipairs(nhead:GetDescendants()) do
							if x:IsA("Decal") or x:IsA("Texture") then setp(r,x,"Transparency",1);r.hide[#r.hide+1]=x;end;
						end;
					end;
					local armor=char:FindFirstChild("CharacterArmor");
					if armor then
						for _,p in ipairs(armor:GetDescendants()) do
							if p:IsA("BasePart") then setp(r,p,"Transparency",1);r.hide[#r.hide+1]=p;end;
						end;
					end;
					for _,x in ipairs(char:GetDescendants()) do
						if x:IsA("Accessory") then
							for _,p in ipairs(x:GetDescendants()) do
								if p:IsA("BasePart") then setp(r,p,"Transparency",1);r.hide[#r.hide+1]=p;end;
							end;
						end;
					end;
					return welded,nil;
				end;

				local function welds_ok(r,c)
					if not(r and r.welds) then return true;end;
					if not c:IsDescendantOf(workspace) then return true;end;
					if not(r.dummy and r.dummy.Parent) then return false;end;
					for i=1,#r.welds do
						local wd=r.welds[i];
						if not(wd.Parent and wd.Part0 and wd.Part0.Parent) then return false;end;
					end;
					return true;
				end;

				-- главная точка входа: оверлей, а если не вышло — старый метод (рубашка/штаны/цвета на родной модели)
				----------------------------------------------------------------
				-- КАРТОЧКА слева: превью выбранного скина, пересобирается при каждой смене
				----------------------------------------------------------------
				M.card=true;
				local card={ang=0,dist=9,center=Vector3.new(0,3,0)};
				local lobby_model,card_show;
				local function card_destroy()
					if card.gui then pcall(function() card.gui:Destroy();end);end;
					card.gui,card.vp,card.cam,card.title,card.sub,card.model=nil,nil,nil,nil,nil,nil;
				end;
				local function card_build()
					tcache.__elev();
					if card.gui and card.gui.Parent then return true;end;
					local host=card.host;
					if not(host and host.Parent) then return false;end;
					local th={};
					pcall(function() th=E.lib.thm or {};end);
					local function col(k,d)
						local v=th[k];
						return typeof(v)=="Color3" and v or d;
					end;
					local f=Instance.new("Frame");
					f.Name="Card";
					f.Size=UDim2.new(1,0,1,0);
					f.BackgroundColor3=Color3.new(1,1,1);
					f.BackgroundTransparency=0.94;
					f.BorderSizePixel=0;
					f.ClipsDescendants=true;
					f.Parent=host;
					local cr=Instance.new("UICorner");
					cr.CornerRadius=UDim.new(0,8);
					cr.Parent=f;
					local st=Instance.new("UIStroke");
					st.Color=Color3.new(1,1,1);
					st.Transparency=0.9;
					st.Thickness=1;
					st.Parent=f;
					local t=Instance.new("TextLabel");
					t.Name="Title";
					t.BackgroundTransparency=1;
					t.Position=UDim2.fromOffset(12,10);
					t.Size=UDim2.new(1,-24,0,20);
					t.Font=Enum.Font.GothamBold;
					t.TextSize=15;
					t.TextXAlignment=Enum.TextXAlignment.Left;
					t.TextTruncate=Enum.TextTruncate.AtEnd;
					t.TextColor3=col("txt",Color3.fromRGB(255,255,255));
					t.Text="default";
					t.Parent=f;
					local s=Instance.new("TextLabel");
					s.Name="Sub";
					s.BackgroundTransparency=1;
					s.Position=UDim2.fromOffset(12,30);
					s.Size=UDim2.new(1,-24,0,16);
					s.Font=Enum.Font.Gotham;
					s.TextSize=12;
					s.TextXAlignment=Enum.TextXAlignment.Left;
					s.TextTruncate=Enum.TextTruncate.AtEnd;
					s.TextColor3=col("dim",Color3.fromRGB(140,148,175));
					s.Text="no skin selected";
					s.Parent=f;
					local vp=Instance.new("ViewportFrame");
					vp.Name="View";
					vp.BackgroundTransparency=1;
					vp.Position=UDim2.fromOffset(6,52);
					vp.Size=UDim2.new(1,-12,1,-58);
					vp.Ambient=Color3.fromRGB(190,190,200);
					vp.LightColor=Color3.fromRGB(255,255,255);
					vp.Parent=f;
					local cam=Instance.new("Camera");
					cam.FieldOfView=35;
					cam.Parent=vp;
vp.CurrentCamera=cam;
						-- вращение превью мышью/тачем: тянешь влево-вправо по превью (автовращения нет)
						vp.Active=true;
						-- ЗУМ превью: колёсико мыши (ПК) и щипок двумя пальцами (телефон). card.zoom: 1 = как было, дальше FOV делится на zoom
						local function zclamp(z) return math.clamp(z,0.6,4);end;
						vp.InputChanged:Connect(function(input)
							if input.UserInputType==Enum.UserInputType.MouseWheel then
								local z=card.zoom or 1;
								card.zoom=zclamp(z*(1+input.Position.Z*0.12));
							end;
						end);
						pcall(function() vp.TouchPinch:Connect(function(tpos,scale,vel,state)
							if state==Enum.UserInputState.Begin then
								card.pinching=true;
								card.pinch_base=card.zoom or 1;
							elseif state==Enum.UserInputState.Change then
								card.zoom=zclamp((card.pinch_base or 1)*scale);
							else
								card.pinching=false;
								card.dragging=nil;
							end;
						end) end);
						vp.InputBegan:Connect(function(input)
							local t=input.UserInputType;
							if t==Enum.UserInputType.MouseButton1 or t==Enum.UserInputType.Touch then card.dragging=input;end;
						end);
						if not card.drag_hooked then
							card.drag_hooked=true;
							local UISd=game:GetService("UserInputService");
							local function hk(sig,fn)
								local ok=pcall(function() A.connect(sig,fn);end);
								if not ok then sig:Connect(fn);end;
							end;
							hk(UISd.InputChanged,function(input)
								if not card.dragging or card.pinching then return;end;
								local t=input.UserInputType;
								if t==Enum.UserInputType.MouseMovement or t==Enum.UserInputType.Touch then
									card.drag_yaw=(card.drag_yaw or 0)-input.Delta.X*0.012;
								end;
							end);
							hk(UISd.InputEnded,function(input)
								local t=input.UserInputType;
								if t==Enum.UserInputType.MouseButton1 or t==Enum.UserInputType.Touch then card.dragging=nil;end;
							end);
						end;
						card.gui,card.vp,card.cam,card.title,card.sub=f,vp,cam,t,s;
					return true;
				end;
				local function card_hide()
					if card.dflt and (card.model or os.clock()-(card.dt or 0)<3) then return;end;
					card.dflt=true;
					card.dt=os.clock();
					task.defer(function()
						pcall(function()
							if card.title then
								card.title.Text="default";
								card.sub.Text="main menu operative";
							end;
						end);
						local okd,st=pcall(function() return card.mstart(nil,nil,true);end);
						if okd and st then return;end;
						local ok,m=pcall(lobby_model);
						if not card.dflt then return;end;
						if ok and m then
							pcall(card_show,m,nil,true);
						elseif card.model then
							pcall(function() card.model:Destroy();end);
							card.model=nil;
						end;
					end);
				end;
				-- tpl: шаблон оверлея, w: "user:ник" / "agent:ключ", ok: false = оверлей не вышел (классический режим)
				-- ===== превью: анимации / сцена / камера из лобби =====
				-- всё в одной таблице PV, чтобы не плодить локалы (лимит 200 на функцию)
				local PV={
					anim="lobby idle",scene="none",cam="fit",
					-- камера лобби из дампа: fov 70, наклон вниз 15°, фокус +1.5 над корнем, дистанция ~12.16
					fov=70,pitch=math.rad(15),dist=12.159,focusY=1.5,
					sway=0,swayhz=0,
					-- то, что реально играет у оперативников в лобби: CharacterIdle + поза меню (обе Idle, loop)
					idle={"rbxassetid://85183085739560","rbxassetid://96024725229380"},
					kc={},scanned={},fc={},gun="none",yaw0=math.rad(25),
				};

				-- кейфреймы анимации по id (через KeyframeSequenceProvider), кэш
				PV.load_kfs=function(id)
					local c=PV.kc[id];
					if c then return c;end;
					if c==false then return nil;end;
					-- FIX: раньше первая неудача кэшировалась навсегда (kc[id]=false) и модель оставалась в T-позе до перезапуска скрипта.
					-- теперь до 3 попыток, а сбой загрузки не кэшируется
					for attempt=1,3 do
						local ok,seq=pcall(function()
							return game:GetService("KeyframeSequenceProvider"):GetKeyframeSequenceAsync(id);
						end);
						if ok and seq then
							local kfs={};
							for _,k in ipairs(seq:GetKeyframes()) do
								local poses={};
								for _,p in ipairs(k:GetDescendants()) do
									-- вес 0 = контейнерная поза, сустав не трогает
									if p:IsA("Pose") and p.Weight>0 then poses[p.Name]={p.CFrame,p.EasingStyle};end;
								end;
								kfs[#kfs+1]={t=k.Time,poses=poses};
							end;
							local loop=seq.Loop;
							pcall(function() seq:Destroy();end);
							if #kfs==0 then PV.kc[id]=false;return nil;end;
							table.sort(kfs,function(a,b) return a.t<b.t;end);
							local tr={kfs=kfs,len=kfs[#kfs].t,loop=loop};
							PV.kc[id]=tr;
							return tr;
						end;
						if attempt<3 then task.wait(0.4);end;
					end;
					return nil;
				end;

				-- пара соседних кейфреймов и доля между ними
				PV.locate=function(tr,t)
					local kfs=tr.kfs;
					if tr.loop and tr.len>0 then t=t%tr.len;elseif t>tr.len then t=tr.len;end;
					local ia=1;
					for i=1,#kfs do
						if kfs[i].t<=t then ia=i;else break;end;
					end;
					local a=kfs[ia];
					local b=kfs[ia+1] or a;
					local al=0;
					if b~=a and b.t>a.t then al=(t-a.t)/(b.t-a.t);end;
					return a,b,al;
				end;

				-- граф суставов модели от корня (в ViewportFrame физики нет, части двигаем сами)
				PV.rig_build=function(m)
					local root=m:FindFirstChild("HumanoidRootPart",true);
					if not(root and root:IsA("BasePart")) then root=m.PrimaryPart;end;
					if not root then return nil;end;
					local adj={};
					local function add(jt)
						adj[jt.p0]=adj[jt.p0] or {};
						table.insert(adj[jt.p0],jt);
					end;
					for _,d in ipairs(m:GetDescendants()) do
						if d:IsA("JointInstance") then
							local p0,p1=d.Part0,d.Part1;
							if p0 and p1 and p0:IsDescendantOf(m) and p1:IsDescendantOf(m) then
								if d:IsA("Motor6D") then
									add({p0=p0,p1=p1,motor=true,name=p1.Name,jname=d.Name,c0=d.C0,c1inv=d.C1:Inverse()});
								else
									-- обычный Weld (аксессуары, глаза): ходим в обе стороны
									add({p0=p0,p1=p1,c0=d.C0,c1inv=d.C1:Inverse()});
									add({p0=p1,p1=p0,c0=d.C1,c1inv=d.C0:Inverse()});
								end;
							end;
						elseif d:IsA("WeldConstraint") then
							local p0,p1=d.Part0,d.Part1;
							if p0 and p1 then
								local rel=p0.CFrame:ToObjectSpace(p1.CFrame);
								add({p0=p0,p1=p1,rel=rel});
								add({p0=p1,p1=p0,rel=rel:Inverse()});
							end;
						end;
					end;
					local order,seen,queue={}, {[root]=true},{root};
					local qi=1;
					while queue[qi] do
						local p=queue[qi];
						qi=qi+1;
						for _,jt in ipairs(adj[p] or {}) do
							if not seen[jt.p1] then
								seen[jt.p1]=true;
								order[#order+1]=jt;
								queue[#queue+1]=jt.p1;
							end;
						end;
					end;
					if #order==0 then return nil;end;
					local orig={};
					for _,jt in ipairs(order) do orig[jt.p1]=jt.p1.CFrame;end;
					return {root=root,rootcf=root.CFrame,order=order,orig=orig};
				end;

				-- один кадр: поза каждого Motor6D = Pose.CFrame из дорожек (поздняя дорожка перекрывает раннюю)
				PV.rig_step=function(rig,tracks,t)
					local loc={};
					for i=1,#tracks do
						local a,b,al=PV.locate(tracks[i],t);
						loc[i]={a=a,b=b,al=al};
					end;
					local cfs={[rig.root]=rig.rootcf};
					for _,jt in ipairs(rig.order) do
						local base=cfs[jt.p0];
						if base then
							local cf;
							if jt.motor then
								local tf;
								for i=1,#loc do
									local L=loc[i];
									local pa,pb=L.a.poses[jt.name],L.b.poses[jt.name];
									if pa and pb then
										if pb[2]==Enum.PoseEasingStyle.Constant then tf=pa[1];else tf=pa[1]:Lerp(pb[1],L.al);end;
									elseif pa or pb then
										tf=(pa or pb)[1];
									end;
								end;
								cf=base*jt.c0*(tf or CFrame.identity)*jt.c1inv;
							elseif jt.rel then
								cf=base*jt.rel;
							else
								cf=base*jt.c0*jt.c1inv;
							end;
							cfs[jt.p1]=cf;
							jt.p1.CFrame=cf;
						end;
					end;
				end;

				-- ----- полная модель ника: одежда, слоёная одежда, аксессуары, цвета (как собирает сама Роблокс) -----
				PV.full=function(w)
					local name=w:sub(6);
					local key=name:lower();
					if PV.fc[key]~=nil then return PV.fc[key] or nil;end;
					local Pl=game:GetService("Players");
					local ok,uid=pcall(function() return Pl:GetUserIdFromNameAsync(name);end);
					if not(ok and uid) then uid=tonumber(name);end;
					if not uid then PV.fc[key]=false;return nil;end;
					local ok2,mdl=pcall(function()
						local okd,hd=pcall(function() return Pl:GetHumanoidDescriptionFromUserId(uid);end);
						if okd and hd then
							pcall(function() hd.HeightScale=1;hd.WidthScale=1;hd.DepthScale=1;hd.HeadScale=1;hd.BodyTypeScale=0;hd.ProportionScale=0;end);
							local okm,mm=pcall(function() return Pl:CreateHumanoidModelFromDescription(hd,Enum.HumanoidRigType.R15);end);
							if okm and mm then return mm;end;
						end;
						local okf,mf=pcall(function() return Pl:CreateHumanoidModelFromUserId(uid);end);
						if okf and mf then return mf;end;
						return Pl:GetCharacterAppearanceAsync(uid);
					end);
					if not(ok2 and mdl) then PV.fc[key]=false;return nil;end;
					PV.fc[key]=mdl;
					return mdl;
				end;

				-- ----- оружие в руках -----
				PV.weapons_root=function()
					local a=game:GetService("ReplicatedStorage"):FindFirstChild("Assets");
					return a and a:FindFirstChild("Weapons");
				end;
				PV.gun_names=function()
					local out={"lobby","none"};
					local r=PV.weapons_root();
					if r then
						for _,c in ipairs(r:GetChildren()) do out[#out+1]=c.Name;end;
					end;
					return out;
				end;
				PV.gun_default=function()
					if true then return "lobby";end;
					local r=PV.weapons_root();
					if not r then return "none";end;
					for _,pat in ipairs({"^ak","galil","m4","awp"}) do
						for _,c in ipairs(r:GetChildren()) do
							if c.Name:lower():find(pat) then return c.Name;end;
						end;
					end;
					local f=r:GetChildren()[1];
					return f and f.Name or "none";
				end;
				PV.gun_scan=function(src)
					if PV.scanned["gun_"..src.Name] or type(writefile)~="function" then return;end;
					PV.scanned["gun_"..src.Name]=true;
					local log={"gun "..src:GetFullName()};
					local n=0;
					local function walk(i,d)
						if d>3 or n>300 then return;end;
						for _,c in ipairs(i:GetChildren()) do
							n=n+1;
							local ex="";
							if c:IsA("BasePart") then ex=" size="..tostring(c.Size);end;
							log[#log+1]=string.rep("  ",d)..c.ClassName.." "..c.Name..ex;
							walk(c,d+1);
						end;
					end;
					walk(src,0);
					local fn=(src.Name:gsub("[^%w_%-]","_"));
					pcall(writefile,"gun_"..fn..".txt",table.concat(log,"\n"));
				end;
				-- модель оружия из Assets.Weapons.<имя>
				PV.gun_src=function(name)
					local r=PV.weapons_root();
					local w=r and r:FindFirstChild(name);
					if not w then return nil;end;
					if w:IsA("BasePart") then return w;end;
					local direct=0;
					for _,c in ipairs(w:GetChildren()) do
						if c:IsA("BasePart") then direct=direct+1;end;
					end;
					if direct>0 then return w;end;
					local best;
					for _,d in ipairs(w:GetDescendants()) do
						if d:IsA("Model") then
							local n=d.Name:lower();
							local has=false;
							for _,c in ipairs(d:GetChildren()) do
								if c:IsA("BasePart") then has=true;break;end;
							end;
							if has and not(n:find("view") or n:find("arm") or n:find("fp") or n:find("first")) then
								if n:find("world") or n:find("third") or n:find("tp") then return d;end;
								best=best or d;
							end;
						end;
					end;
					return best or w;
				end;
				-- FIX: превью-ствол со скином из вкладки guns (через игровой модуль скинов), иначе чистая модель из Assets.Weapons
				do
					local raw_gun_src=PV.gun_src;
					-- FIX: скин берём из состояния вкладки guns (модуль aw) с учётом выбранной там стороны (both/T/CT),
					-- а не из команды локального игрока: в лобби команды нет, хук GetWorldModel отдавал стоковую модель или скин не той стороны
					local function ui_skin(name)
						local okS,S=pcall(K.load,"aw");
						if not(okS and type(S)=="table" and type(S.ggetfor)=="function") then return nil;end;
						local function get(sd)
							for _,nm in ipairs({name,tostring(name):upper(),tostring(name):lower()}) do
								local okg,e=pcall(S.ggetfor,nm,sd);
								if okg and type(e)=="table" and type(e.skin)=="string" and e.skin~="" then return e.skin;end;
							end;
							return nil;
						end;
						local sd=S.side;
						if sd=="ct" then return get("ct");end;
						if sd=="t" then return get("t");end;
						local a=get("t");
						if a and a~="Stock" then return a;end;
						local b=get("ct");
						if b and b~="Stock" then return b;end;
						return a or b;
					end;
					-- оригинал GetWorldModel (до хука): хук смотрит на реальную команду игрока и перебивает явно переданный скин
					local function raw_wm(sk)
						local fn;
						pcall(function()
							local sh=A.shared;
							local fl=sh and sh.fields and sh.fields[sk];
							fn=fl and fl.GetWorldModel;
						end);
						if type(fn)~="function" then fn=sk.GetWorldModel;end;
						return fn;
					end;
					local function check(m)
						if typeof(m)~="Instance" then return nil;end;
						local parts=0;
						if m:IsA("BasePart") then parts=1;end;
						for _,d in ipairs(m:GetDescendants()) do
							if d:IsA("Humanoid") or (d:IsA("BasePart") and d.Name:find("Arm")) then return nil;end;
							if d:IsA("BasePart") then parts=parts+1;end;
						end;
						if parts<1 or parts>120 then return nil;end;
						return m;
					end;
					-- FIX: скин-модель от игры может быть битой (пустая, огромная/крошечная, части далеко) - тогда ствол "пропадает"; такую не берём
					local function sane(m,ref)
						local parts={};
						if m:IsA("BasePart") then parts[1]=m;end;
						for _,d in ipairs(m:GetDescendants()) do if d:IsA("BasePart") then parts[#parts+1]=d;end;end;
						if #parts==0 then return false;end;
						local vis,far=0,false;
						local o=parts[1].Position;
						local mn,mx=Vector3.new(math.huge,math.huge,math.huge),Vector3.new(-math.huge,-math.huge,-math.huge);
						for _,q in ipairs(parts) do
							if q.Transparency<0.95 then vis=vis+1;end;
							if (q.Position-o).Magnitude>15 then far=true;end;
							mn=Vector3.new(math.min(mn.X,q.Position.X),math.min(mn.Y,q.Position.Y),math.min(mn.Z,q.Position.Z));
							mx=Vector3.new(math.max(mx.X,q.Position.X),math.max(mx.Y,q.Position.Y),math.max(mx.Z,q.Position.Z));
						end;
						if vis==0 or far then return false;end;
						if ref then
							local rp={};
							if ref:IsA("BasePart") then rp[1]=ref;end;
							for _,d in ipairs(ref:GetDescendants()) do if d:IsA("BasePart") then rp[#rp+1]=d;end;end;
							if #rp>0 then
								local a,b=Vector3.new(math.huge,math.huge,math.huge),Vector3.new(-math.huge,-math.huge,-math.huge);
								for _,q in ipairs(rp) do
									a=Vector3.new(math.min(a.X,q.Position.X),math.min(a.Y,q.Position.Y),math.min(a.Z,q.Position.Z));
									b=Vector3.new(math.max(b.X,q.Position.X),math.max(b.Y,q.Position.Y),math.max(b.Z,q.Position.Z));
								end;
								local rs,ms=(b-a).Magnitude,(mx-mn).Magnitude;
								if rs>0.5 and (ms<rs*0.3 or ms>rs*3) then return false;end;
							end;
						end;
						return true;
					end;
					PV.gun_root_up=function(w,top)
						for _=1,3 do
							local pr=w and w.Parent;
							if not pr or pr==top or BODYSET[pr.Name] or pr.Name=="HumanoidRootPart" or pr:IsA("Accessory") then break;end;
							local direct=0;
							for _,c in ipairs(w:GetChildren()) do if c:IsA("BasePart") and c.Transparency<0.9 then direct=direct+1;end;end;
							if w.Name:lower()=="interactables" or direct==0 then w=pr;else break;end;
						end;
						return w;
					end;
					PV.lobby_gun_src=function()
						local lm=PV.menu_fast();
						if not lm then return nil;end;
						local mz=lm:FindFirstChild("MuzzlePart",true);
						local w=mz and mz.Parent;
						if w and w~=lm and not BODYSET[w.Name] and w.Name~="HumanoidRootPart" and not w:IsA("Accessory") then
							w=PV.gun_root_up(w,lm);
							if not PV.gun_diag then
								PV.gun_diag=true;
								pcall(function()
									local out={"GUNDIAG weapon="..w:GetFullName()};
									for _,d in ipairs(lm:GetDescendants()) do
										if d:IsA("Motor6D") and d.Part1 and (d.Part1:IsDescendantOf(w) or d.Part1==w) then out[#out+1]="GUNDIAG motor "..d.Name.." P0="..tostring(d.Part0 and d.Part0.Name).." P1="..tostring(d.Part1.Name).." C0="..tostring(d.C0);end;
									end;
									if M.dbg then M.dbg(table.concat(out," | "));end;
									if type(writefile)=="function" then writefile("gun_diag.txt",table.concat(out,"\n"));end;
								end);
							end;
							return w;
						end;
						for _,d in ipairs(lm:GetChildren()) do
							if d.Name=="Equipped" or d.Name:find("^Weapon") or d:IsA("Tool") then return d;end;
						end;
						return nil;
					end;
					PV.ui_skin=ui_skin;
					-- имя ствола, который сейчас в превью (для "lobby" - имя оружия лобби-агента)
					PV.cur_gun_name=function()
						local g=PV.gun;
						if g=="lobby" then
							local okl,gs=pcall(PV.lobby_gun_src);
							return (okl and typeof(gs)=="Instance") and gs.Name or nil;
						end;
						if not g or g=="none" then return nil;end;
						return g;
					end;
					PV.gun_src=function(name)
						-- FIX: "lobby" раньше отдавал стоковый ствол лобби-агента напрямую, мимо скин-модуля -> скины не менялись.
						-- теперь берём имя оружия лобби и строим его со скином из вкладки guns; нет скина/не вышло - ствол лобби как был
						local lobbyBase;
						if name=="lobby" then
							local okl,gs=pcall(PV.lobby_gun_src);
							lobbyBase=(okl and typeof(gs)=="Instance") and gs or nil;
							if not lobbyBase then return nil;end;
							name=lobbyBase.Name;
						end;
						local how="";
						local okk,res=pcall(function()
							if not name or name=="none" then return nil;end;
							local jm=K.load("j");
							local sk=type(jm)=="table" and jm.skins;
							if type(sk)~="table" then return nil;end;
							local skin=ui_skin(name);
							do
								local okS,SS=pcall(K.load,"aw");
								how=how.."[skin="..tostring(skin).." side="..tostring(okS and type(SS)=="table" and SS.side or "?").."] ";
							end;
								if lobbyBase and (not skin or skin=="Stock") then return nil;end;
								if skin and skin~="Stock" then
									local f=raw_wm(sk);
									if type(f)=="function" then
										-- берём первый Instance из ВСЕХ возвратов (модель может идти не первым значением)
										local variants={{name,skin},{name,skin,"t"},{name,skin,"ct"},{name,skin,false}};
										local ok2,m2,nr=false,nil,0;
										for vi,av in ipairs(variants) do
											local pk=table.pack(pcall(f,table.unpack(av)));
											ok2=pk[1];
											if vi==1 then how=how.."ret="..typeof(pk[2]).."/"..tostring(pk[2]):sub(1,50).." ";end;
											if ok2 then for i=2,pk.n do if typeof(pk[i])=="Instance" then m2=pk[i];break;end;end;end
											nr=pk.n-1;
											if m2 then how=how.."raw#"..vi.." ";break;end;
										end;
										how=how.."raw="..tostring(ok2).."/"..(m2 and typeof(m2) or ("nil#"..tostring(nr))).." ";
										local c2=ok2 and check(m2);
										if c2 and sane(c2,lobbyBase) then how=how.."=> ui:"..skin;return c2;elseif c2 then how=how.."(raw model insane) ";end;
									end;
									-- запасной путь: хукнутый GetWorldModel с явным скином
									local fh=sk.GetWorldModel;
									if type(fh)=="function" and fh~=f then
										local ok4,m4=pcall(fh,name,skin);
										how=how.."hook2="..tostring(ok4).."/"..(ok4 and typeof(m4) or tostring(m4):sub(1,60)).." ";
										local c4=ok4 and check(m4);
										if c4 and sane(c4,lobbyBase) then how=how.."=> hook-skin:"..skin;return c4;elseif c4 then how=how.."(hook2 model insane) ";end;
									end;
								end;
							-- старый путь: хукнутый GetWorldModel(name), скин по реальной команде игрока
							local f=sk.GetWorldModel;
							if type(f)~="function" then return nil;end;
							local ok3,m3=pcall(f,name);
							local c3=ok3 and check(m3);
 if c3 and not sane(c3,lobbyBase) then c3=nil;how=how.."(hook model insane) ";end;
							if c3 then how=how.."=> hook";end;
							return c3 or nil;
						end);
						pcall(tcache.__elev);
						pcall(function() if M.dbg then M.dbg("GUNSKIN "..tostring(name).." via="..how.." skinned="..tostring(okk and res~=nil and res:GetFullName() or "no (fallback Assets.Weapons)"));end;end);
						if okk and typeof(res)=="Instance" then return res;end;
						if lobbyBase then return lobbyBase;end;
						if not lobbyBase then
							local okl,lg=pcall(PV.lobby_gun_src);
							if okl and typeof(lg)=="Instance" and lg.Name==name then return lg;end;
						end;
						return raw_gun_src(name);
					end;
				end;
				-- FIX (в превью пропали стволы): GUNFOLLOW прячет родной ствол лобби (Transparency=1), а превью для "lobby" клонировало именно его - выходил невидимый ствол.
				-- теперь клон ствола лобби получает ту прозрачность, что была у частей до скрытия (по записям оверлея). выключить: getgenv().Z_PV_GUN_UNHIDE=false
				do
					local base_gun_src=PV.gun_src;
					PV.gun_src=function(name)
						local res=base_gun_src(name);
						if (getgenv and getgenv().Z_PV_GUN_UNHIDE)==false then return res;end;
						if typeof(res)~="Instance" then return res;end;
						local okx,out=pcall(function()
							local lm=PV.menu_fast and PV.menu_fast();
							local rr=lm and recs[lm];
							if not(rr and rr.o) then return nil;end;
							if not(res==lm or res:IsDescendantOf(lm)) then return nil;end;
							local c=tcache.__sclone(res);
							if not c then return nil;end;
							local function walk(a,b)
								local t=rr.o[a];
								if t and t.Transparency~=nil then pcall(function() b.Transparency=t.Transparency;end);end;
								local ca,cb=a:GetChildren(),b:GetChildren();
								if #ca==#cb then
									for i=1,#ca do walk(ca[i],cb[i]);end;
								else
									local used={};
									for _,x in ipairs(ca) do
										for j,y in ipairs(cb) do
											if not used[j] and y.Name==x.Name and y.ClassName==x.ClassName then used[j]=true;walk(x,y);break;end;
										end;
									end;
								end;
							end;
							walk(res,c);
							return c;
						end);
						if okx and typeof(out)=="Instance" then return out;end;
						return res;
					end;
				end;
				PV.gun_mount=function(m)
					local hand=m:FindFirstChild("RightHand",true);
					if not(hand and hand:IsA("BasePart")) then return nil;end;
					local src=PV.gun_src(PV.gun);
					if not src then return nil;end;
					pcall(PV.gun_scan,src);
					local g=src:Clone();
					local all,junk={}, {};
					local jc0,jc1;
					if g:IsA("BasePart") then all[1]=g;end;
					for _,d in ipairs(g:GetDescendants()) do
						if d:IsA("BasePart") then
							all[#all+1]=d;
						elseif d:IsA("JointInstance") or d:IsA("WeldConstraint") or d:IsA("Script") or d:IsA("LocalScript") or d:IsA("Sound") then
							if d:IsA("Motor6D") and not jc0 then
								-- хват, который задан в самой модели оружия, главнее моего
								local n=d.Name:lower();
								if n:find("handle") or n:find("grip") or (d.Part1 and d.Part1.Name=="Handle") then jc0,jc1=d.C0,d.C1;end;
							end;
							junk[#junk+1]=d;
						end;
					end;
					for _,j in ipairs(junk) do pcall(function() j:Destroy();end);end;
					if #all==0 then pcall(function() g:Destroy();end);return nil;end;
					local handle;
					for _,p in ipairs(all) do
						if p.Name=="Handle" then handle=p;break;end;
					end;
					if not handle and g:IsA("Model") then handle=g.PrimaryPart;end;
					if not handle then
						local ba=0;
						for _,p in ipairs(all) do
							local a=p.Size.X*p.Size.Y*p.Size.Z;
							if a>ba then ba=a;handle=p;end;
						end;
					end;
					local rel={};
					for _,p in ipairs(all) do
						rel[p]=handle.CFrame:ToObjectSpace(p.CFrame);
						p.Anchored=false;
						p.CanCollide=false;
						p.CanQuery=false;
						p.CanTouch=false;
						p.Massless=true;
					end;
					local grip=hand:FindFirstChild("RightGripAttachment");
					local c0=jc0 or (grip and grip.CFrame) or (CFrame.new(0,-0.125,0)*CFrame.Angles(math.rad(-90),0,0));
					local c1=jc1 or CFrame.new();
					local hcf=hand.CFrame*c0*c1:Inverse();
					for _,p in ipairs(all) do p.CFrame=hcf*rel[p];end;
					handle.Name="Handle";
					g.Name="PreviewGun";
					g.Parent=m;
					-- сустав "Handle": его двигает поза Handle из анимации (как у настоящих персонажей игры)
					local mj=Instance.new("Motor6D");
					mj.Name="Handle";
					mj.Part0=hand;
					mj.Part1=handle;
					mj.C0=c0;
					mj.C1=c1;
					mj.Parent=hand;
					for _,p in ipairs(all) do
						if p~=handle then
							local w=Instance.new("WeldConstraint");
							w.Part0=handle;
							w.Part1=p;
							w.Parent=p;
						end;
					end;
					return {handle=handle,hand=hand};
				end;
				-- проигрываем анимации настоящим Animator (модель лежит в WorldModel внутри ViewportFrame)
				PV.play=function(m,ids)
					local animator=m:FindFirstChildWhichIsA("Animator",true);
					if not animator then
						local host=m:FindFirstChildOfClass("Humanoid") or m:FindFirstChildOfClass("AnimationController");
						if not host then
							host=Instance.new("AnimationController");
							host.Parent=m;
						end;
						animator=Instance.new("Animator");
						animator.Parent=host;
					end;
					for i,id in ipairs(ids) do
						local a=Instance.new("Animation");
						a.AnimationId=id;
						local ok,tr=pcall(function() return animator:LoadAnimation(a);end);
						if ok and tr then
							tr.Looped=true;
							tr.Priority=(i==1) and Enum.AnimationPriority.Idle or Enum.AnimationPriority.Action;
							pcall(tr.Play,tr,0);
						end;
					end;
				end;
				PV.ovr={};
				PV.play_over=function(m,ids)
					if PV.ovr[m] then return;end;
					local animator=m:FindFirstChildWhichIsA("Animator",true);
					if not animator then return;end;
					local list={};
					for i,id in ipairs(ids) do
						local a=Instance.new("Animation");
						a.AnimationId=id;
						local ok,tr=pcall(function() return animator:LoadAnimation(a);end);
						if ok and tr then
							tr.Looped=true;
							tr.Priority=(i==1) and Enum.AnimationPriority.Action3 or Enum.AnimationPriority.Action4;
							pcall(tr.Play,tr,0);
							list[#list+1]=tr;
						end;
					end;
					PV.ovr[m]=list;
				end;
				PV.stop_over=function(m)
					local list=PV.ovr[m];
					if not list then return;end;
					PV.ovr[m]=nil;
					for _,tr in ipairs(list) do pcall(function() tr:Stop(0.1);end);end;
				end;
				-- подвешиваем оружие в граф суставов: сустав "Handle" двигается позой Handle из анимации
				PV.gun_link=function(rig,gun)
					if not(rig and gun) then return;end;
					table.insert(rig.order,{p0=gun.hand,p1=gun.handle,motor=false,gun=true,name="Handle",c0=gun.c0,c1inv=gun.c1inv or CFrame.new()});
					rig.orig[gun.handle]=gun.handle.CFrame;
					for _,p in ipairs(gun.parts) do
						if p~=gun.handle then
							table.insert(rig.order,{p0=gun.handle,p1=p,rel=gun.rel[p]});
							rig.orig[p]=p.CFrame;
						end;
					end;
				end;
				-- какие анимации играть: базовая стойка + idle выбранного оружия (как в лобби), запасной вариант - поза меню
				PV.anim_ids=function()
					local ids={PV.idle[1]};
					if PV.anim=="idle only" then return ids;end;
					local wid;
					if PV.gun and PV.gun~="none" then
						local a=game:GetService("ReplicatedStorage"):FindFirstChild("Assets");
						local wa=a and a:FindFirstChild("WeaponAnimations");
						local g=wa and wa:FindFirstChild(PV.gun);
						local ca=g and g:FindFirstChild("CharacterAnimations");
						local idle=ca and ca:FindFirstChild("Idle");
						if idle and idle:IsA("Animation") and idle.AnimationId~="" then wid=idle.AnimationId;end;
					end;
					ids[#ids+1]=wid or PV.idle[2];
					return ids;
				end;
				PV.gun=PV.gun_default();
				PV.static_only=true;PV.nomirror_until=math.huge;

				-- ===== статичное превью (шаблон модели): оружие и анимация =====
				-- оружие для шаблона: части Anchored, позу каждый кадр ставит rig_step через PV.gun_link
				-- FIX: у части стволов (калаш) в превью пропадали текстуры: клон брался с лобби/мирового ствола, у которого TextureID/SurfaceAppearance
				-- уже сняты (chams/материал-оверрайд) или не догружены. сверяем клон с чистой моделью из Assets.Weapons по MeshId и возвращаем то, чего не хватает.
				-- выключить: PV.gun_retex_on=false
				PV.gun_retex_on=true;
				PV.gun_retex_skinned=true; -- на скинованных стволах тоже докидывать пропавшие текстуры (только по MeshId)
				PV.gun_retex=function(g,name)
					if not(PV.gun_retex_on and g and name) then return;end;
					local okS,sk=pcall(PV.ui_skin,name);
					local skinned=(okS and sk and sk~="Stock") and true or false;
					if skinned and not PV.gun_retex_skinned then return;end;
					local r=PV.weapons_root();
					local pr=r and r:FindFirstChild(name);
					if not pr then return;end;
					local byMesh,byName={}, {};
					for _,d in ipairs(pr:GetDescendants()) do
						if d:IsA("MeshPart") then
							local hasTex=false;
							local okT,t=pcall(function() return d.TextureID;end);
							if okT and t and t~="" then hasTex=true;end;
							if d:FindFirstChildWhichIsA("SurfaceAppearance") then hasTex=true;end;
							if hasTex then
								local mid=d.MeshId;
								if mid~="" and not byMesh[mid] then byMesh[mid]=d;end;
								if not byName[d.Name] then byName[d.Name]=d;end;
							end;
						end;
					end;
					local fixed,total=0,0;
					local assets={};
					local bare={};
					for _,d in ipairs(g:GetDescendants()) do
						if d:IsA("MeshPart") then
							total=total+1;
							local has=(d.TextureID~="") or (d:FindFirstChildWhichIsA("SurfaceAppearance")~=nil) or (d:FindFirstChildWhichIsA("Texture")~=nil) or (d:FindFirstChildWhichIsA("Decal")~=nil);
							if not has then
								local ref=(d.MeshId~="" and byMesh[d.MeshId]) or ((not skinned) and byName[d.Name]) or nil;
								if not ref then bare[#bare+1]=d.Name.."("..tostring(d.MeshId):sub(-12)..")";end;
								if ref then
									pcall(function() d.TextureID=ref.TextureID;end);
									local sa=ref:FindFirstChildWhichIsA("SurfaceAppearance");
									if sa then pcall(function() sa:Clone().Parent=d;end);end;
									if ref.TextureID~="" then assets[#assets+1]=ref.TextureID;end;
									fixed=fixed+1;
								end;
							end;
						end;
					end;
					pcall(function() if M.dbg then M.dbg("GUNRETEX "..tostring(name).." skin="..tostring(sk).." meshparts="..total.." restored="..fixed.." still_bare=["..table.concat(bare,", ").."]");end;end);
					if #assets>0 then pcall(function() game:GetService("ContentProvider"):PreloadAsync(assets);end);end;
				end;
				-- FIX: на скинах-ником (в т.ч. тонкие R15 Thin бандлы) текстуры ствола не доезжали: превью грузит кучу ассетов тела/одежды,
				-- а текстуры ствола во ViewportFrame остаются пустыми, пока ассет не догрузился. ждём загрузку ствола и "толкаем" свойства, чтобы перерисовалось.
				-- выключить: PV.gun_preload_on=false
				PV.gun_preload_on=true;
				PV.gun_preload=function(g)
					if not(PV.gun_preload_on and g) then return;end;
					task.spawn(function()
						pcall(function() game:GetService("ContentProvider"):PreloadAsync({g});end);
						local n=0;
						local okd,desc=pcall(g.GetDescendants,g);
						if not okd then return;end;
						for _,d in ipairs(desc) do
							pcall(function()
								if d:IsA("MeshPart") and d.TextureID~="" then
									local t=d.TextureID;d.TextureID="";d.TextureID=t;n=n+1;
								elseif d:IsA("SurfaceAppearance") then
									for _,pn in ipairs({"ColorMap","NormalMap","MetalnessMap","RoughnessMap"}) do
										local v=d[pn];
										if v~="" then d[pn]="";d[pn]=v;end;
									end;
									n=n+1;
								end;
							end);
						end;
						pcall(function() if M.dbg then M.dbg("GUNPRELOAD "..tostring(g.Name).." refreshed="..n);end;end);
					end);
				end;
				PV.gun_mount_a=function(m,force_base)
					local hand=m:FindFirstChild("RightHand",true);
					if not(hand and hand:IsA("BasePart")) then return nil;end;
local src=force_base or PV.gun_src(PV.gun);
if not src then return nil;end;
local g=tcache.__sclone(src);
					if not g then return nil;end;
					pcall(PV.gun_retex,g,(force_base and force_base.Name) or PV.cur_gun_name() or src.Name);
					pcall(PV.gun_preload,g);
					local all,junk={}, {};
					local jc0,jc1;
					local jpr=0;
					if g:IsA("BasePart") then all[1]=g;end;
					for _,d in ipairs(g:GetDescendants()) do
						if d:IsA("BasePart") then
							all[#all+1]=d;
						elseif d:IsA("JointInstance") or d:IsA("WeldConstraint") or d:IsA("BaseScript") or d:IsA("Sound") then
							-- FIX: раньше брался первый сустав с Part1=Handle - им оказывался MuzzlePart->Handle (смещение 3.5 вверх), ствол висел не в руке.
							-- нужен именно сустав руки: WeaponAttachment (RightHand -> Handle)
							if d:IsA("Motor6D") then
								local n=d.Name:lower();
								local pr=0;
								if n:find("weaponattach") or (d.Part0 and d.Part0.Name=="RightHand" and d.Part1 and d.Part1.Name=="Handle") then pr=3;
								elseif n:find("grip") then pr=2;end;
								if pr>jpr then jpr=pr;jc0,jc1=d.C0,d.C1;end;
							end;
							junk[#junk+1]=d;
						end;
					end;
					for _,j in ipairs(junk) do pcall(function() j:Destroy();end);end;
					if #all==0 then pcall(function() g:Destroy();end);return nil;end;
					local handle;
					for _,p in ipairs(all) do
						if p.Name=="Handle" then handle=p;break;end;
					end;
					if not handle and g:IsA("Model") then handle=g.PrimaryPart;end;
					if not handle then
						local ba=0;
						for _,p in ipairs(all) do
							local ar=p.Size.X*p.Size.Y*p.Size.Z;
							if ar>ba then ba=ar;handle=p;end;
						end;
					end;
					if not handle then pcall(function() g:Destroy();end);return nil;end;
					local rel={};
					for _,p in ipairs(all) do
						rel[p]=handle.CFrame:ToObjectSpace(p.CFrame);
						p.Anchored=true;
						p.CanCollide=false;
						p.CanQuery=false;
						p.CanTouch=false;
						p.Massless=true;
					end;
					local grip=hand:FindFirstChild("RightGripAttachment");
					-- FIX: ствол висел снизу - хват по умолчанию (RightGripAttachment) не совпадает с тем, как игра держит оружие.
					-- берём реальное смещение Handle относительно RightHand у живого лобби-агента (в его позе ствол сидит в руке)
					local lobby_c0;
					if not jc0 then
						pcall(function()
							local lb=PV.menu_fast();
							if not lb then return;end;
							local lhand=lb:FindFirstChild("RightHand",true);
							local mz=lb:FindFirstChild("MuzzlePart",true);
							local wr=mz and mz.Parent;
							local lh;
							if wr and wr~=lb then
								lh=(wr.Name=="Handle" and wr:IsA("BasePart")) and wr or wr:FindFirstChild("Handle",true);
							end;
							if not lh then
								for _,d in ipairs(lb:GetDescendants()) do
									if d:IsA("BasePart") and d.Name=="Handle" and not d:FindFirstAncestorWhichIsA("Accessory") then lh=d;break;end;
								end;
							end;
							if lhand and lhand:IsA("BasePart") and lh and lh:IsA("BasePart") then
								lobby_c0=lhand.CFrame:ToObjectSpace(lh.CFrame);
							end;
						end);
					end;
					pcall(function() if M.dbg then M.dbg("GUNGRIP via="..(jc0 and "gun-motor" or (lobby_c0 and "lobby-offset" or (grip and "grip-attachment" or "default")))..(lobby_c0 and (" off="..tostring(lobby_c0.Position)) or ""));end;end);
					local c0=jc0 or lobby_c0 or (grip and grip.CFrame) or (CFrame.new(0,-0.125,0)*CFrame.Angles(math.rad(-90),0,0));
					local c1=jc1 or CFrame.new();
					local hcf=hand.CFrame*c0*c1:Inverse();
					for _,p in ipairs(all) do p.CFrame=hcf*rel[p];end;
					g.Name="PreviewGun";
					g.Parent=m;
					return {handle=handle,hand=hand,parts=all,rel=rel,c0=c0,c1inv=c1:Inverse(),model=g};
				end;
				do
						local mount_inner=PV.gun_mount_a;
						local function mount_ok(r)
							if not(r and r.handle and r.hand and r.parts) then return false;end;
							if (r.handle.Position-r.hand.Position).Magnitude>8 then return false;end;
							for _,q in ipairs(r.parts) do if q.Transparency<0.95 then return true;end;end;
							return false;
						end;
						PV.gun_mount_a=function(m)
							pcall(tcache.__elev);
							local function H(e) return tostring(e).." | "..tostring(debug and debug.traceback and debug.traceback("",2) or ""):sub(1,400);end;
							local okm,r=xpcall(mount_inner,H,m);
							if not okm then
								pcall(function() if M.dbg then M.dbg("GUNMOUNT ERR "..tostring(r));end;end);
								pcall(tcache.__elev);
								okm,r=xpcall(mount_inner,H,m);
								if not okm then pcall(function() if M.dbg then M.dbg("GUNMOUNT ERR#2 "..tostring(r));end;end);r=nil;end;
							end;
							local how="primary";
							if PV.gun=="lobby" and not mount_ok(r) then
								local okl,b=pcall(PV.lobby_gun_src);
								if okl and typeof(b)=="Instance" then
									if r and r.model then pcall(function() r.model:Destroy();end);end;
									local okb,rb=xpcall(mount_inner,tostring,m,b);
							if okb then r=rb;else r=nil;pcall(function() if M.dbg then M.dbg("GUNMOUNT lobby ERR "..tostring(rb));end;end);end;
									how="lobby-fallback("..b:GetFullName()..")";
								end;
							end;
							local ok=mount_ok(r);
							PV.last_mount_ok=ok;
							pcall(function() if M.dbg then M.dbg("GUNMOUNT ok="..tostring(ok).." how="..how.." PV.gun="..tostring(PV.gun));end;end);
							return r;
						end;
					end;
					-- запасной режим (Animator): оружие на Motor6D + WeldConstraint, части неприкованные
				PV.gun_phys=function(gun)
					if not(gun and gun.hand and gun.handle and gun.parts) then return;end;
					local mj=Instance.new("Motor6D");
					mj.Name="Handle";
					mj.Part0=gun.hand;
					mj.Part1=gun.handle;
					mj.C0=gun.c0;
					mj.C1=(gun.c1inv or CFrame.new()):Inverse();
					mj.Parent=gun.hand;
					for _,p in ipairs(gun.parts) do
						if p~=gun.handle then
							local w=Instance.new("WeldConstraint");
							w.Part0=gun.handle;
							w.Part1=p;
							w.Parent=p;
						end;
						p.Anchored=false;
					end;
				end;
				PV.unanchor_for_animator=function(m,gun)
					if card.model~=m then return;end;
					local mine_gun={};
					if gun and gun.parts then
						for _,gp in ipairs(gun.parts) do mine_gun[gp]=true;end;
					end;
					for _,d in ipairs(m:GetDescendants()) do
						if d:IsA("BasePart") and d.Name~="HumanoidRootPart" and not mine_gun[d] then d.Anchored=false;end;
					end;
					if gun then pcall(PV.gun_phys,gun);end;
				end;
				-- родное оружие шаблона (если шаблон - клон лобби/живой модели): убираем, вместо него ставится ствол из preview gun
				PV.strip_native_gun=function(m)
					local kill={};
					local mz=m:FindFirstChild("MuzzlePart",true);
					local wroot=mz and mz.Parent;
					if wroot and wroot~=m and not BODYSET[wroot.Name] and wroot.Name~="HumanoidRootPart" and not wroot:IsA("Accessory") then
						local okU,up=pcall(PV.gun_root_up,wroot,m);
						if okU and up then wroot=up;end;
						kill[#kill+1]=wroot;
					end;
					for _,d in ipairs(m:GetChildren()) do
						if d.Name=="Equipped" or d.Name:find("^Weapon") or d:IsA("Tool") then kill[#kill+1]=d;end;
					end;
					for _,d in ipairs(kill) do pcall(function() d:Destroy();end);end;
				end;
				-- FIX: статичный шаблон раньше стоял в T-позе без анимации. Теперь на него ставится ствол и играет idle по кейфреймам (как в лобби)
				-- габариты по частям тела (R15), с запасом под причёску
				PV.body_bbox=function(m)
					local mn,mx;
					for _,d in ipairs(m:GetDescendants()) do
						if d:IsA("BasePart") and BODYSET[d.Name] then
							local p,h=d.Position,d.Size*0.5;
							local lo,hi=p-h,p+h;
							if mn then
								mn=Vector3.new(math.min(mn.X,lo.X),math.min(mn.Y,lo.Y),math.min(mn.Z,lo.Z));
								mx=Vector3.new(math.max(mx.X,hi.X),math.max(mx.Y,hi.Y),math.max(mx.Z,hi.Z));
							else
								mn,mx=lo,hi;
							end;
						end;
					end;
					if not mn then return nil;end;
					local sz=mx-mn;
					if sz.Magnitude~=sz.Magnitude or sz.Magnitude>30 then return nil;end;
					return CFrame.new((mn+mx)*0.5+Vector3.new(0,0.4,0)),sz+Vector3.new(1,1.2,1);
				end;

				PV.static_animate=function(m)
					local tok=card.tok;
					pcall(PV.strip_native_gun,m);
					local gun;
					if PV.gun and PV.gun~="none" then
						local okg,gg=pcall(PV.gun_mount_a,m);
						if okg then gun=gg;end;
					end;
					if PV.anim~="none" then
						-- "lobby idle": берём настоящую позу с живого MenuCharacter (его родные анимации) и переносим на клон превью
						local src;
						if PV.anim=="lobby idle" then
							local okf,f=pcall(PV.menu_fast);
							if okf and f then src=f;end;
						end;
						if src then
							local okr,rig=pcall(PV.rig_build,m);
							if okr and rig then
								if gun then pcall(PV.gun_link,rig,gun);end;
								card.rig,card.tracks,card.live,card.at=rig,nil,{src=src,map=PV.motor_map(src),n=0},0;
								pcall(function()
									local n,nz=0,0;
									for _,v in pairs(card.live.map) do n=n+1;if v.Transform~=CFrame.identity then nz=nz+1;end;end;
									local an=src:FindFirstChildWhichIsA("Animator",true);
									local tr=an and an:GetPlayingAnimationTracks() or {};
									local ids={};
									for _,t in ipairs(tr) do ids[#ids+1]=tostring(t.Animation and t.Animation.AnimationId)..":"..tostring(t.Priority);end;
									if M.dbg then M.dbg("LIVE src="..src:GetFullName().." motors="..n.." animated="..nz.." tracks="..table.concat(ids,","));end;
								end);
								return;
							end;
						end;
						pcall(function()
							if not M.dbg then return;end;
							local okx,rx=pcall(PV.rig_build,m);
							local hrp=m:FindFirstChild("HumanoidRootPart",true);
							local jn,mt=0,0;
							for _,d in ipairs(m:GetDescendants()) do if d:IsA("JointInstance") then jn=jn+1;end;if d:IsA("Motor6D") then mt=mt+1;end;end;
							M.dbg("LIVE none -> keyframes, src="..tostring(src).." mode="..tostring(PV.anim).." | rig_build ok="..tostring(okx).." rig="..((okx and rx) and "table" or tostring(rx)).." hrp="..tostring(hrp).." primary="..tostring(m.PrimaryPart).." joints="..jn.." motors="..mt);
						end);
						local kfids;
						if src then
							pcall(function()
								local an=src:FindFirstChildWhichIsA("Animator",true);
								if not an then return;end;
								local l={};
								for _,t in ipairs(an:GetPlayingAnimationTracks()) do
									local a=t.Animation;
									if a and a.AnimationId~="" then l[#l+1]={t.Priority.Value,a.AnimationId};end;
								end;
								table.sort(l,function(x,y) return x[1]<y[1];end);
								if #l>0 then kfids={};for _,e in ipairs(l) do kfids[#kfids+1]=e[2];end;end;
							end);
						end;
						PV.start_kf(m,kfids or PV.anim_ids(),tok,gun);
						-- FIX: скин по нику играл запасные кейфреймы (или стоял в позе), потому что лобби-агент не находился в момент сборки: дожидаемся его и переходим на ту же живую позу, что у дефолтного агента
						if PV.anim=="lobby idle" then
							task.spawn(function()
								for _=1,16 do
									task.wait(0.5);
									if card.tok~=tok or card.model~=m or card.live then return;end;
									local okf2,f2=pcall(PV.menu_fast);
									if okf2 and f2 then
										if card.rig then for part,cf0 in pairs(card.rig.orig) do pcall(function() part.CFrame=cf0;end);end;end;
										local okr2,rig2=pcall(PV.rig_build,m);
										if okr2 and rig2 then
											if gun then pcall(PV.gun_link,rig2,gun);end;
											card.rig,card.tracks,card.live,card.at=rig2,nil,{src=f2,map=PV.motor_map(f2),n=0},0;
											return;
										end;
									end;
								end;
							end);
						end;
					end;
				end;
				-- смена скина ствола во вкладке guns: превью берёт этот ствол и перестраивается
				PV.gun_skin_changed=function(n)
					-- превью берёт ствол, у которого в guns реально сменили скин (раньше PV.follow_gun нигде не включался, и превью
					-- оставалось на стволе лобби-агента - он зависит от карты: AK-47 / M4A1-S / пистолет). Хук срабатывает и без смены
					-- (пачкой по всем стволам), поэтому сравниваем скин с запомненным и дебаунсим.
					PV.gpend=PV.gpend or {};
					PV.gpend[#PV.gpend+1]=n;
					PV.gdeb=(PV.gdeb or 0)+1;
					local tk=PV.gdeb;
					task.delay(0.35,function()
						if tk~=PV.gdeb then return;end;
						local pend=PV.gpend;PV.gpend={};
						PV.skin_seen=PV.skin_seen or {};
						local function curskin(w)
							local okk,v=pcall(function() return PV.ui_skin and PV.ui_skin(w) or nil;end);
							v=okk and v or nil;
							if v=="Stock" then v=nil;end;
							return v;
						end;
						local target;
						local r=PV.weapons_root();
						for _,pn in ipairs(pend) do
							local cur=curskin(pn);
							local prev=PV.skin_seen[pn];
							PV.skin_seen[pn]=cur;
							if prev~=cur and r then
								local real=r:FindFirstChild(pn);
								if not real then
									local ln=tostring(pn):lower();
									for _,c in ipairs(r:GetChildren()) do if c.Name:lower()==ln then real=c;break;end;end;
								end;
								if real then target=real.Name;end;
							end;
						end;
						if target and PV.gun~=target then
							PV.gun=target;
							pcall(function() local dd=PV.gun_dd;if dd and dd.set then dd:set(target,true);end;end);
						end;
						local nm=PV.cur_gun_name and PV.cur_gun_name();
						local gs=tostring(nm).."|"..tostring(nm and curskin(nm) or nil);
						if PV.last_gsig==gs then
							pcall(function() if M.dbg then M.dbg("GUNHOOK no real change for preview gun ("..gs..") - skip");end;end);
							return;
						end;
						PV.last_gsig=gs;
						PV.gtok=(PV.gtok or 0)+1;
						pcall(function() if M.dbg then M.dbg("GUNHOOK skin changed -> preview gun "..gs.." (follow="..tostring(target)..")");end;end);
						PV.refresh();
					end);
				end;

				-- аксессуары в шаблоне часто не приварены (вне workspace Humanoid их не крепит): привариваем по одноимённым Attachment,
				-- а то, что приварить нельзя или улетело далеко от тела, убираем (иначе рамка модели раздувается и камера уезжает)
				PV.fix_acc=function(m)
					local root=m:FindFirstChild("HumanoidRootPart",true);
					local list={};
					for _,d in ipairs(m:GetDescendants()) do
						if d:IsA("Accessory") then list[#list+1]=d;end;
					end;
					for _,acc in ipairs(list) do
						local h=acc:FindFirstChild("Handle");
						if h and h:IsA("BasePart") then
							local has=false;
							for _,x in ipairs(h:GetChildren()) do
								if x:IsA("JointInstance") then has=true;end;
							end;
							if not has then
								local done=false;
								for _,ha in ipairs(h:GetChildren()) do
									if not done and ha:IsA("Attachment") then
										local target;
										for _,bp in ipairs(m:GetDescendants()) do
											if bp:IsA("Attachment") and bp.Name==ha.Name and bp.Parent:IsA("BasePart") and not bp.Parent:FindFirstAncestorWhichIsA("Accessory") then
												target=bp;
												break;
											end;
										end;
										if target then
											local w=Instance.new("Weld");
											w.Name="AccessoryWeld";
											w.Part0=h;
											w.Part1=target.Parent;
											w.C0=ha.CFrame;
											w.C1=target.CFrame;
											w.Parent=h;
											h.CFrame=target.Parent.CFrame*target.CFrame*ha.CFrame:Inverse();
											done=true;
										end;
									end;
								end;
								if not done then pcall(function() acc:Destroy();end);end;
							end;
							if root and acc.Parent and (h.Position-root.Position).Magnitude>12 then pcall(function() acc:Destroy();end);end;
						end;
					end;
				end;

				-- ----- FIX: чёрная кожа в превью -----
				-- части тела с почти чёрным Color (пустой BodyColors / дефолт HumanoidDescription / чёрный тинт на текстурном меше)
				-- перекрашиваем в нормальный тон кожи. выключить: PV.skin_fix=false, свой цвет: PV.skin_tone=Color3.fromRGB(r,g,b)
				PV.skin_fix=true;
				PV.skin_tone=Color3.fromRGB(190,140,105);
				PV.skin_tex_tint=Color3.fromRGB(215,190,170);
				PV.skin_dark=0.25;
				PV.fix_skin_part=function(d)
					if not PV.skin_fix then return;end;
					if not(d and d:IsA("BasePart") and BODYSET[d.Name]) then return;end;
					if d:FindFirstChildWhichIsA("SurfaceAppearance") then return;end;
					local c=d.Color;
					if math.max(c.R,c.G,c.B)>=PV.skin_dark then return;end;
					local tex="";
					if d:IsA("MeshPart") then pcall(function() tex=d.TextureID;end);end;
					pcall(function() if M.dbg then M.dbg("SKIN fix "..d.Name.." was="..tostring(c).." tex="..(tex~="" and "y" or "n"));end;end);
					if tex~="" then d.Color=PV.skin_tex_tint;else d.Color=PV.skin_tone;end;
				end;
				PV.fix_skin=function(m)
					if not(PV.skin_fix and m) then return;end;
					for _,d in ipairs(m:GetDescendants()) do
						pcall(PV.fix_skin_part,d);
						if d:IsA("BodyColors") then
							for _,p in ipairs({"HeadColor3","TorsoColor3","LeftArmColor3","RightArmColor3","LeftLegColor3","RightLegColor3"}) do
								pcall(function()
									local c=d[p];
									if math.max(c.R,c.G,c.B)<PV.skin_dark then d[p]=PV.skin_tone;end;
								end);
							end;
						end;
					end;
				end;

				-- ----- сцена -----
				PV.scene_root=function()
					local a=game:GetService("ReplicatedStorage"):FindFirstChild("Assets");
					return a and a:FindFirstChild("MenuScenes");
				end;
				PV.scene_names=function()
					local out={"auto","none"};
					local r=PV.scene_root();
					if r then
						for _,c in ipairs(r:GetChildren()) do out[#out+1]=c.Name;end;
					end;
					return out;
				end;
				PV.scene_pick=function(name)
					local r=PV.scene_root();
					if not r then return nil;end;
					if name~="auto" then return r:FindFirstChild(name);end;
					local first;
					for _,c in ipairs(r:GetChildren()) do
						local n=c.Name:lower();
						if n:find("main") or n:find("lobby") or n:find("menu") or n:find("default") then return c;end;
						first=first or c;
					end;
					return first;
				end;
				-- структура сцены в файл menuscene_<имя>.txt (чтобы потом точнее привязать якорь/камеру)
				PV.scene_scan=function(src)
					if PV.scanned[src.Name] or type(writefile)~="function" then return;end;
					PV.scanned[src.Name]=true;
					local log={"scene "..src:GetFullName()};
					local n=0;
					local function walk(i,d)
						if d>4 or n>500 then return;end;
						for _,c in ipairs(i:GetChildren()) do
							n=n+1;
							local ex="";
							if c:IsA("BasePart") then ex=" size="..tostring(c.Size).." cf="..tostring(c.CFrame);
							elseif c:IsA("Attachment") then ex=" cf="..tostring(c.WorldCFrame);
							elseif c:IsA("Model") then ex=" pivot="..tostring(c:GetPivot());end;
							log[#log+1]=string.rep("  ",d)..c.ClassName.." "..c.Name..ex;
							walk(c,d+1);
						end;
					end;
					walk(src,0);
					local fn=(src.Name:gsub("[^%w_%-]","_"));
					pcall(writefile,"menuscene_"..fn..".txt",table.concat(log,"\n"));
				end;
				-- ставит сцену во ViewportFrame так, чтобы её "точка персонажа" совпала с ногами модели.
				-- возвращает сцену и CFrame камеры сцены (если в ней нашёлся маркер камеры)
				PV.scene_mount=function(m,vp)
					if PV.scene=="none" then return nil;end;
					local pick=PV.scene_pick(PV.scene);
					if not pick then return nil;end;
					pcall(PV.scene_scan,pick);
					local cnt=0;
					for _,d in ipairs(pick:GetDescendants()) do
						if d:IsA("BasePart") then cnt=cnt+1;end;
					end;
					if cnt>6000 then return nil,"сцена "..pick.Name.." тяжёлая ("..cnt.." частей), пропускаю";end;
					local s=pick:Clone();
					if not s:IsA("Model") then
						local w=Instance.new("Model");
						for _,c in ipairs(s:GetChildren()) do c.Parent=w;end;
						pcall(function() s:Destroy();end);
						s=w;
					end;
					local anchor,camcf;
					local junk={};
					for _,d in ipairs(s:GetDescendants()) do
						local n=d.Name:lower();
						if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("Sound") then
							junk[#junk+1]=d;
						elseif d:IsA("Model") and not anchor and (d:FindFirstChildOfClass("Humanoid") or d:FindFirstChild("HumanoidRootPart")) then
							-- болванка-оперативник в сцене: берём её ноги как якорь и убираем
							local ok,bcf,bsz=pcall(function() return d:GetBoundingBox();end);
							if ok then
								local hrp=d:FindFirstChild("HumanoidRootPart");
								local rot=(hrp and hrp:IsA("BasePart")) and hrp.CFrame.Rotation or bcf.Rotation;
								anchor=CFrame.new(bcf.Position.X,bcf.Position.Y-bsz.Y/2,bcf.Position.Z)*rot;
								junk[#junk+1]=d;
							end;
						elseif d:IsA("BasePart") or d:IsA("Attachment") or d:IsA("Camera") then
							local cf=d:IsA("Attachment") and d.WorldCFrame or d.CFrame;
							if not camcf and n:find("cam") then
								camcf=cf;
								if d:IsA("BasePart") then d.Transparency=1;end;
							elseif not anchor and (n:find("^char") or n:find("^player") or n:find("operative") or n:find("^agent") or n:find("spawn") or n:find("^dummy") or n:find("^rig")) then
								anchor=cf;
								if d:IsA("BasePart") then d.Transparency=1;end;
							end;
						end;
					end;
					if not anchor then
						local ok0,bcf0,bsz0=pcall(function() return s:GetBoundingBox();end);
						anchor=ok0 and CFrame.new(bcf0.Position.X,bcf0.Position.Y-bsz0.Y/2,bcf0.Position.Z) or CFrame.new();
					end;
					for _,j in ipairs(junk) do pcall(function() j:Destroy();end);end;
					local okm,mcf,msz=pcall(function() return m:GetBoundingBox();end);
					if not okm then pcall(function() s:Destroy();end);return nil;end;
					local root=m:FindFirstChild("HumanoidRootPart",true);
					local rot=(root and root:IsA("BasePart")) and root.CFrame.Rotation or CFrame.new();
					local target=CFrame.new(mcf.Position.X,mcf.Position.Y-msz.Y/2,mcf.Position.Z)*rot;
					local T=target*anchor:Inverse();
					s:PivotTo(T*s:GetPivot());
					s.Parent=vp;
					return s,(camcf and T*camcf or nil);
				end;

				-- ===== поза с живой модели лобби: берём Transform каждого Motor6D у настоящего агента и переносим на превью =====
				PV.motor_map=function(src)
					local map={};
					for _,d in ipairs(src:GetDescendants()) do
						if d:IsA("Motor6D") and d.Part1 then
							map[d.Part1.Name]=d;
							if map["\0j:"..d.Name]==nil then map["\0j:"..d.Name]=d;end;
						end;
					end;
					return map;
				end;
				PV.foreign=function(m)
					if m==lp.Character then return false;end;
					local uid=m:GetAttribute("UserId");
					if uid~=nil and tostring(uid)~=tostring(lp.UserId) then return true;end;
					if m.Name~=lp.Name and Players:FindFirstChild(m.Name) then return true;end;
					local pr=m.Parent;
					if pr and (pr.Name=="Characters" or pr.Name=="_PVS_CulledCharacters") and m.Name~=lp.Name then return true;end;
					return false;
				end;
				PV.lobby_scan=function()
					local log={"lobby scan: все R15-риги в workspace (лучшие сверху)"};
					local cam=workspace.CurrentCamera;
					local cpos=cam and cam.CFrame.Position or Vector3.zero;
					local clook=cam and cam.CFrame.LookVector or Vector3.new(0,0,-1);
					local list={};
					local cnt=0;
					for _,d in ipairs(workspace:GetDescendants()) do
						cnt=cnt+1;
						if cnt%2500==0 then task.wait();end;
						if d.Name=="UpperTorso" and d:IsA("BasePart") then
							local m=d.Parent;
							if m and m:IsA("Model") and m:FindFirstChild("LowerTorso") and not m:FindFirstAncestor("ClientOverlay") and not(card.model and m:IsDescendantOf(card.model)) and not PV.foreign(m) then
								local root=m:FindFirstChild("HumanoidRootPart") or m:FindFirstChild("LowerTorso");
								local off=root.Position-cpos;
								local dist=off.Magnitude;
								local front=dist>0.1 and off.Unit:Dot(clook) or 0;
								local vis=PV.vis_count(m);
								local up=d.CFrame.UpVector.Y;
								local sc=-dist/15+(front>0.3 and 4 or 0)+math.min(vis,12)*0.2+(up>0.6 and 3 or -8);
								if m==lp.Character then sc=sc-1;end;
								list[#list+1]={m=m,sc=sc,dist=dist,front=front,vis=vis};
							end;
						end;
					end;
					table.sort(list,function(x,y) return x.sc>y.sc;end);
					for i=1,math.min(#list,8) do
						local c=list[i];
						log[#log+1]=string.format("%d. %s dist=%.1f front=%.2f vis=%d score=%.2f",i,c.m:GetFullName(),c.dist,c.front,c.vis,c.sc);
					end;
					if #list==0 then
						log[#log+1]="R15-ригов не нашёл. дети workspace:";
						for _,c in ipairs(workspace:GetChildren()) do log[#log+1]="  "..c.ClassName.." "..c.Name;end;
					end;
					local txt=table.concat(log,"\n");
					if not PV.scan_logged then
						PV.scan_logged=true;
						pcall(function() if type(writefile)=="function" then writefile("lobby_pose_scan.txt",txt);end;end);
						pcall(print,txt);
					end;
					local best=list[1];
					if best and best.vis>=3 then return best.m,#list;end;
					return nil,#list;
				end;
				PV.lobby_refresh=function()
					if PV.lobby_busy then return;end;
					PV.lobby_busy=true;
					local prev=PV.lobby;
					local ok,m,n;
					do
						local okf,fm=pcall(PV.menu_fast);
						if okf and fm then ok,m,n=true,fm,1;else ok,m,n=pcall(PV.lobby_scan);end;
					end;
					PV.lobby=(ok and m) or nil;
					do local f=PV.menu_fast();if f then PV.lobby=f;end;end;
					M.lobby=PV.lobby;
					PV.lobby_t=os.clock();
					PV.lobby_busy=false;
					if PV.lobby~=prev then
						say(PV.lobby and ("лобби-агент найден: "..PV.lobby:GetFullName()) or ("лобби-агента не нашёл (ригов: "..tostring(n)..", см. консоль)"));
						if PV.lobby and PV.on_lobby then task.defer(PV.on_lobby);end;
					end;
				end;
				-- без ожидания: отдаёт последнего найденного, а устаревший кэш обновляет в фоне
				PV.lobby_peek=function()
					do
						local okf,fm=pcall(PV.menu_fast);
						if okf and fm then
							if PV.lobby~=fm then
								PV.lobby=fm;M.lobby=fm;PV.lobby_t=os.clock();
								if PV.on_lobby then task.defer(PV.on_lobby);end;
							end;
							return fm;
						end;
					end;
					if PV.lobby_t==nil or (os.clock()-PV.lobby_t>4 and not PV.lobby_busy) then
						PV.lobby_t=PV.lobby_t or -1e9;
						task.spawn(PV.lobby_refresh);
					end;
					local m=PV.lobby;
					if m and m.Parent then return m;end;
					return nil;
				end;
				-- с ожиданием первого скана (для превью)
				-- источники, которые нельзя брать как лобби-агента (рэгдоллы в Debris, служебные __ модели)
				PV.bad_src=function(c)
					local d=workspace:FindFirstChild("Debris");
					if d and c:IsDescendantOf(d) then return true;end;
					if tostring(c.Name):sub(1,2)=="__" then return true;end;
					return false;
				end;
				-- МГНОВЕННЫЙ путь: прямое обращение Workspace.Reactor.MenuCharacter (без сканов и ожиданий), кэш до удаления модели
				PV.menu_fast=function()
					local c=PV.menu_c;
					if c and c.Parent and c:IsDescendantOf(workspace) then return c;end;
					PV.menu_c=nil;
					local rx=workspace:FindFirstChild("Reactor");
					-- FIX: карта не всегда Reactor (в логах Workspace.Hellena.MenuCharacter) - ищем любую папку карты с MenuCharacter/TeamSelect
					if not(rx and (rx:FindFirstChild("MenuCharacter") or rx:FindFirstChild("TeamSelect"))) then
						rx=nil;
						for _,ch in ipairs(workspace:GetChildren()) do
							if ch:FindFirstChild("MenuCharacter") or ch:FindFirstChild("TeamSelect") then rx=ch;break;end;
					end;
					end;
					if not rx then return nil;end;
					local cand={};
					local mc=rx:FindFirstChild("MenuCharacter");
					if mc then cand[#cand+1]=mc;end;
					local ts=rx:FindFirstChild("TeamSelect");
					if ts then
						for _,x in ipairs(ts:GetChildren()) do
							if x:IsA("Model") and tostring(x.Name):find("TeamSelectCharacter") then cand[#cand+1]=x;end;
						end;
					end;
					local fb;
					for _,x in ipairs(cand) do
						if x:IsA("Model") and x:FindFirstChild("UpperTorso",true) then
							local n,mo=0,0;
							for _,d in ipairs(x:GetDescendants()) do
								if d:IsA("BasePart") and d.Name~="HumanoidRootPart" and d.Transparency<0.9 then n=n+1;end;
								if d:IsA("Motor6D") then mo=mo+1;end;
							end;
							if n>=3 then PV.menu_c=x;return x;end;
							-- FIX: когда на лобби-агента надет скин по нику, оверлей прячет его родное тело (Transparency=1) - но суставы и анимации живы, поза берётся именно с них
							if mo>=6 and not fb then fb=x;end;
						end;
					end;
					if fb then PV.menu_c=fb;return fb;end;
					return nil;
				end;
				PV.find_lobby=function()
					local f=PV.menu_fast();
					if f then
						if PV.lobby~=f then PV.lobby=f;M.lobby=f;PV.lobby_t=os.clock();end;
						return f;
					end;
					if PV.lobby_t==nil or PV.lobby_t<0 then
						if PV.lobby_busy then
							-- FIX: первый скан уже идёт в фоне - ждём его (до 6с), иначе превью строилось по случайному источнику и застревало на нём
							local t0=os.clock();
							while PV.lobby_busy and os.clock()-t0<6 do task.wait(0.05);end;
						else
							PV.lobby_refresh();
						end;
					end;
					return PV.lobby_peek();
				end;
				-- поза = реальные положения частей лобби-агента: относительный CFrame ребёнка к родителю (Part0 -> Part1) переносим на сустав превью
				PV.rig_step_live=function(rig,live)
					local cfs={[rig.root]=rig.rootcf};
					for _,jt in ipairs(rig.order) do
						local base=cfs[jt.p0];
						if base then
							local cf;
							if jt.motor then
								local sm=live.map[jt.name] or (jt.jname and live.map["\0j:"..jt.jname]);
								if sm and sm.Parent and sm.Part0 and sm.Part1 then
									-- FIX: берём C0/C1 с ЖИВОГО сустава лобби-агента, а не с копии: если игра двигает руки/ствол через C0/C1 (а не только Transform), раньше это терялось
									local lc0,lc1=sm.C0,sm.C1;
									local tt=sm.Transform;
									if tt==CFrame.identity then
										local rel=sm.Part0.CFrame:ToObjectSpace(sm.Part1.CFrame);
										tt=lc0:Inverse()*rel*lc1;
									end;
									cf=base*lc0*tt*lc1:Inverse();
								else
									cf=base*jt.c0*jt.c1inv;
								end;
							elseif jt.rel then
								cf=base*jt.rel;
							else
								cf=base*jt.c0*jt.c1inv;
							end;
							cfs[jt.p1]=cf;
							jt.p1.CFrame=cf;
						end;
					end;
				end;
				-- запасной путь: кейфреймы по ID анимаций, потом Animator
				PV.start_kf=function(m,ids,tok,gun)
					task.spawn(function()
						tcache.__elev();
						local trs={};
						for _,id in ipairs(ids) do
							local okk,tr=pcall(PV.load_kfs,id);
							if okk and tr then trs[#trs+1]=tr;end;
						end;
						if card.tok~=tok or card.model~=m then return;end;
						if card.live then return;end;
						local okr,rig=pcall(PV.rig_build,m);
						if #trs>0 and okr and rig then
							if gun then pcall(PV.gun_link,rig,gun);end;
							card.rig,card.tracks,card.at,card.chk=rig,trs,0,nil;
						else
							-- запасной путь: настоящий Animator в WorldModel (нужны неприкованные части и сваренное оружие)
							pcall(PV.unanchor_for_animator,m,gun);
							pcall(PV.play,m,ids);
						end;
					end);
				end;

				PV.card_show_tpl=function(tpl,w,ok)
					tcache.__elev();
					card.tpl,card.w,card.ok=tpl,w,ok;
					card.dflt=(w==nil);
					if not M.card or not tpl then card_hide();return;end;
					if not card_build() then return;end;
					local title,subtxt=tostring(w),"";
					if w==nil then
						title,subtxt="default","main menu operative";
					elseif w:sub(1,5)=="user:" then
						title=w:sub(6);
						subtxt="skin by nickname";
					else
						local a=agents[w:sub(7)];
						title=a and a.name or w:sub(7);
						subtxt="agent"..((a and a.side and a.side~="?") and (" · "..a.side:upper()) or "");
					end;
					if ok==false then subtxt=subtxt.." · classic mode";end;
					card.title.Text=title;
					card.sub.Text=subtxt;
					local tok=(card.tok or 0)+1;
					card.tok=tok;
					if w and w:sub(1,5)=="user:" then
						local okf,full=pcall(PV.full,w);
						if card.tok~=tok then return;end;
						if okf and full then tpl=full;end;
					end;
					if card.model then pcall(function() card.model:Destroy();end);card.model=nil;end;
					if card.scene then pcall(function() card.scene:Destroy();end);card.scene=nil;end;
					card.rig,card.tracks,card.scamcf,card.at,card.chk=nil,nil,nil,0,nil;card.live=nil;
					local m=tcache and tcache.__sclone(tpl) or tpl:Clone();
					if not m then return false;end;
					for _,x in ipairs(m:GetDescendants()) do
						if x:IsA("Script") or x:IsA("LocalScript") then pcall(function() x:Destroy();end);end;
					end;
					local hum=m:FindFirstChildOfClass("Humanoid");
					if hum then
						pcall(function()
							hum.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None;
							hum.HealthDisplayType=Enum.HumanoidHealthDisplayType.AlwaysOff;
						end);
					end;
					if card.wm then pcall(function() card.wm:Destroy();end);card.wm=nil;end;
					local wm=tcache.__wm(card.vp);
					if not wm then return false;end;
					card.wm=wm;
					pcall(function() for _,c in ipairs(card.vp:GetChildren()) do if c~=wm and c.Name=="PreviewWM" then c:Destroy();end;end;end);
					pcall(PV.fix_skin,m);
					m.Parent=wm;
					do
						-- в WorldModel работает физика/суставы: корень якорим, остальное свободно, чтобы Animator двигал части
						local hrp=m:FindFirstChild("HumanoidRootPart",true);
						if not(hrp and hrp:IsA("BasePart")) then hrp=m.PrimaryPart;end;
						local joints=0;
						for _,d in ipairs(m:GetDescendants()) do
							if d:IsA("Motor6D") then joints=joints+1;end;
						end;
						for _,d in ipairs(m:GetDescendants()) do
							if d:IsA("BasePart") then
								d.Anchored=(joints==0) or (d==hrp);
								d.CanCollide=false;
							end;
						end;
						if hum then pcall(function() hum.EvaluateStateMachine=false;end);end;
					end;
					pcall(PV.fix_acc,m);
					local gun;
					if PV.gun and PV.gun~="none" then
						local okg,gg=pcall(PV.gun_mount,m);
						if okg then gun=gg;end;
					end;
					local okb,cf,size=pcall(function() return m:GetBoundingBox();end);
					if okb and cf then
						card.center=cf.Position;
						card.size=size;
						card.dist=(size.Y*0.5)/math.tan(math.rad(17.5))*1.25+size.Z*0.5;
					else
						card.center=Vector3.new(0,3,0);
						card.size=Vector3.new(2,5,1);
						card.dist=9;
					end;
					local root=m:FindFirstChild("HumanoidRootPart",true);
					card.rootcf=(root and root:IsA("BasePart")) and root.CFrame or CFrame.new(card.center);
					card.model=m;
					-- сцена из ReplicatedStorage.Assets.MenuScenes
					local oks,s,scf=pcall(PV.scene_mount,m,card.vp);
					if oks and s then
						if typeof(s)=="Instance" then
							card.scene=s;
							card.scamcf=scf;
						end;
					elseif oks and type(scf)=="string" then
						say(scf);
					end;
					-- анимации лобби: кейфреймы грузим асинхронно, двигаем части сами (см. RenderStepped ниже)
					if PV.anim~="none" then
					local ids=PV.anim_ids();
					task.spawn(function()
						local okf,src=pcall(PV.find_lobby);
						if card.tok~=tok or card.model~=m then return;end;
						local okr,rig=pcall(PV.rig_build,m);
						if okf and src and okr and rig then
							card.rig,card.live,card.at=rig,{src=src,map=PV.motor_map(src),n=0},0;
							say("поза с живого лобби: "..src:GetFullName());
						else
							PV.start_kf(m,ids,tok);
						end;
					end);
				end;
				end;
				A.connect(RS.RenderStepped,function(dt)
					if not(card.model and card.cam and card.gui and card.gui.Parent) then return;end;
					card.t=(card.t or 0)+dt;
					-- FIX: автовращения нет, вращает только игрок (card.drag_yaw)
					local live=card.live;
					if live and card.rig then
						local okl=pcall(PV.rig_step_live,card.rig,live);
						live.n=(live.n or 0)+1;
						if live.n==3 then
							local okb,_,sz=pcall(function() return card.model:GetBoundingBox();end);
							if not okl or not okb or not sz or sz.Magnitude~=sz.Magnitude or sz.Magnitude>card.size.Magnitude*1.8 then
								for part,cf0 in pairs(card.rig.orig) do pcall(function() part.CFrame=cf0;end);end;
								card.live=nil;
								say("поза с лобби сломала модель, откатил на анимации по ID");
								PV.start_kf(card.model,PV.anim_ids(),card.tok);
							end;
						end;
					end;
					local tracks=(not card.live) and card.tracks or nil;
					if tracks and card.rig and #tracks>0 then
						card.at=(card.at or 0)+dt;
						local oks=pcall(PV.rig_step,card.rig,tracks,card.at);
						if not card.chk then
							card.chk=true;
							local okb,_,sz=pcall(function() return card.model:GetBoundingBox();end);
							local bad=not oks or not okb or not sz or sz.Magnitude~=sz.Magnitude or sz.Magnitude>card.size.Magnitude*1.5 or sz.Magnitude<card.size.Magnitude*0.5;
							if bad then
								for part,cf0 in pairs(card.rig.orig) do pcall(function() part.CFrame=cf0;end);end;
								card.tracks=nil;
								say("кейфреймы сломали позу модели, откатил на Animator");
								pcall(PV.play,card.model,PV.anim_ids());
							end;
						end;
					end;
					local cam,mode=card.cam,PV.cam;
					if mode=="orbit" then
						-- старый режим: полный оборот вокруг модели
						cam.FieldOfView=35/(card.zoom or 1);
						local d=card.dist;
						local ya=card.ang+(card.drag_yaw or 0);
 local p=card.center+Vector3.new(math.sin(ya)*d,d*0.08,-math.cos(ya)*d);
						cam.CFrame=CFrame.lookAt(p,card.center);
						return;
					end;
					cam.FieldOfView=((mode=="lobby") and PV.fov or 40)/(card.zoom or 1);
					if mode=="lobby" and card.scamcf then
						-- камера, которую задаёт сама сцена
						do local rp=(card.rootcf or CFrame.new(card.center)).Position;cam.CFrame=CFrame.new(rp)*CFrame.Angles(0,card.drag_yaw or 0,0)*CFrame.new(-rp)*card.scamcf;end;
						return;
					end;
					local rcf=card.rootcf or CFrame.new(card.center);
					local fwd=Vector3.new(rcf.LookVector.X,0,rcf.LookVector.Z);
					if fwd.Magnitude>0.01 then fwd=fwd.Unit;else fwd=Vector3.new(0,0,-1);end;
					-- лёгкое покачивание вокруг лица модели (в лобби камера статична)
					local yaw=PV.yaw0+(card.drag_yaw or 0);
					local c,sn=math.cos(yaw),math.sin(yaw);
					fwd=Vector3.new(fwd.X*c+fwd.Z*sn,0,-fwd.X*sn+fwd.Z*c);
					local focus,d;
					if mode=="lobby" then
						focus=rcf.Position+Vector3.new(0,PV.focusY,0);
						d=PV.dist;
					else
						focus=rcf.Position+Vector3.new(0,-0.55,0);
						d=10.2;
					end;
					local pos=focus+fwd*(d*math.cos(PV.pitch))+Vector3.new(0,d*math.sin(PV.pitch),0);
					cam.CFrame=CFrame.lookAt(pos,focus);
				end);
				-- перестроить превью после смены настроек анимации/сцены
				PV.refresh=function()
					if not(card.gui and card.gui.Parent) then return;end;
					card.sig=nil;if card.tpl or card.w~=nil then
						task.spawn(pcall,card_show,card.tpl,card.w,card.ok);
					else
						-- FIX: дефолтное превью (агент не выбран) строится через mirror_start(nil,nil,true), card.tpl там пустой.
						-- раньше refresh молча ничего не делал, и смена ствола/анимации в preview не применялась
						card.dflt=false;
						card.dt=0;
						task.spawn(pcall,card_hide);
					end;
				end;

				-- проп/аксессуар (custom models): крепим к родной модели напрямую (сварка в матче, покадровая посадка в лобби), тело прячем только если у модели стоит bs_hide
				-- M.cust: живые настройки из секции "custom models" (size / height offset)
				M.cust=M.cust or {sizeMul=1,yoff=0,off=CFrame.new()};
				-- параметры дефолтной R15 (та же болванка, из которой скрипт собирает скин по нику): высота торса, рост, длина ноги
				local function bs_blen(part,a,b)
					local x,y=part and part:FindFirstChild(a),part and part:FindFirstChild(b);
					if x and y and x:IsA("Attachment") and y:IsA("Attachment") then return (x.CFrame.Position-y.CFrame.Position).Magnitude;end;
					return nil;
				end;
				local function bs_std()
					local c=M.cust;
					if c.std then return c.std;end;
					local info={ut=1.6,h=5.0,leg=nil};
					pcall(function()
						local m=Players:CreateHumanoidModelFromDescription(Instance.new("HumanoidDescription"),Enum.HumanoidRigType.R15);
						local ut=m:FindFirstChild("UpperTorso");
						if ut then info.ut=ut.Size.Y;end;
						local hd,lf=m:FindFirstChild("Head"),m:FindFirstChild("LeftFoot");
						if hd and lf then
							local h=(hd.Position.Y+hd.Size.Y/2)-(lf.Position.Y-lf.Size.Y/2);
							if h>1 then info.h=h;end;
						end;
						local l1=bs_blen(m:FindFirstChild("LeftUpperLeg"),"LeftHipRigAttachment","LeftKneeRigAttachment");
						local l2=bs_blen(m:FindFirstChild("LeftLowerLeg"),"LeftKneeRigAttachment","LeftAnkleRigAttachment");
						if l1 and l2 then info.leg=l1+l2;end;
						pcall(m.Destroy,m);
					end);
					c.std=info;
					return info;
				end;
				local function apply_prop(char,src,w)
					if not(char and char.Parent and src) then return 0,"нет персонажа";end;
					restore(char);
					local r=rec_of(char);
					r.want=w;
					if src:GetAttribute("bs_hide") then
						local hl={};
						for _,p in ipairs(char:GetDescendants()) do
							if p:IsA("BasePart") and (BODYSET[p.Name] or p:FindFirstAncestorWhichIsA("Accessory") or p:FindFirstAncestor("CharacterArmor")) then
								setp(r,p,"Transparency",1);
								hl[#hl+1]=p;
							end;
						end;
						r.bshide=hl;
					end;
					local function find_att(name)
						for _,d in ipairs(char:GetDescendants()) do
							if d:IsA("Attachment") and d.Name==name and not d:FindFirstAncestorWhichIsA("Accessory") then return d;end;
						end;
						return nil;
					end;
					local function fallback_part(name)
						local nl=tostring(name):lower();
						local want="UpperTorso";
						if nl:find("hat") or nl:find("hair") or nl:find("face") then want="Head";
						elseif nl:find("waist") or nl:find("root") then want="LowerTorso";end;
						local p=char:FindFirstChild(want,true);
						if p and p:IsA("BasePart") then return p;end;
						p=char:FindFirstChild("HumanoidRootPart",true);
						if p and p:IsA("BasePart") then return p;end;
						return char:FindFirstChildWhichIsA("BasePart",true);
					end;
					r.bsparts={};
					r.bsdrive={};
					r.bsweld={};
					r.bshead=char:FindFirstChild("Head",true);
					-- размер как у модели "по нику": дефолтная R15 масштабируется по высоте родного UpperTorso (+ в лобби по длине ног) - повторяем ту же математику
					local autoMul,ratio,lf,std=1,1,1,nil;
					if src:GetAttribute("bs_mesh") then
						std=bs_std();
						local ct=findpart(char,"UpperTorso");
						if ct and std.ut>0 then ratio=math.clamp(ct.Size.Y/std.ut,0.3,3);end;
						if M.lobby and char==M.lobby and M.use_joint_chain and std.leg then
							local function legn(side)
								local l1=bs_blen(findpart(char,side.."UpperLeg"),side.."HipRigAttachment",side.."KneeRigAttachment");
								local l2=bs_blen(findpart(char,side.."LowerLeg"),side.."KneeRigAttachment",side.."AnkleRigAttachment");
								return (l1 and l2) and (l1+l2) or nil;
							end;
							local la,lb=legn("Left"),legn("Right");
							local ln=(la and lb) and (la+lb)/2 or la or lb;
							if ln then lf=math.clamp(ln/(std.leg*ratio),0.8,1.3);end;
						end;
						local baked=tonumber(src:GetAttribute("bs_h"));
						if baked and baked>0 then
							-- полная модель: рост = как у дефолтной модельки (или height= из имени папки), пересчитанный на размер родного персонажа
							local want=tonumber(src:GetAttribute("bs_hu")) or std.h;
							autoMul=want*ratio*lf/baked;
						else
							autoMul=ratio*lf;
						end;
						autoMul=math.clamp(autoMul,0.1,8);
					end;
					r.bsmul=autoMul;
					local mul=autoMul*(M.cust.sizeMul or 1);
					-- свой персонаж в матче = сварка; лобби/выбор команды/рэгдолл = якорим части и ставим по родной каждый кадр (как делает оверлей)
					local islobby=not(char==lp.Character or char.Name:lower()==lp.Name:lower());
					local holder=workspace:FindFirstChild("ClientOverlay");
					if not holder then
						holder=Instance.new("Folder");
						holder.Name="ClientOverlay";
						holder.Parent=workspace;
					end;
					local n,viaatt,viafb=0,0,0;
					for _,acc in ipairs(src:GetDescendants()) do
						if acc:IsA("Accessory") then
							local c=tcache.__lclone(acc);
							local handle=c and c:FindFirstChild("Handle");
							if handle and handle:IsA("BasePart") then
								local hat=handle:FindFirstChildOfClass("Attachment");
								local tgt,c0,c1;
								if hat then
									local ca=find_att(hat.Name);
									if ca and ca.Parent and ca.Parent:IsA("BasePart") then
										tgt,c0,c1=ca.Parent,ca.CFrame,hat.CFrame;viaatt=viaatt+1;
									else
										tgt,c0,c1=fallback_part(hat.Name),CFrame.new(),hat.CFrame;viafb=viafb+1;
									end;
								else
									tgt,c0,c1=fallback_part(""),CFrame.new(),CFrame.new();viafb=viafb+1;
								end;
								if tgt then
									local c1s=CFrame.new(c1.Position*autoMul)*c1.Rotation;
									local rels={};
									for _,x in ipairs(c:GetDescendants()) do
										if x:IsA("BasePart") then
											x.Anchored=false;x.CanCollide=false;x.CanQuery=false;x.CanTouch=false;x.Massless=true;
											rels[x]=handle.CFrame:ToObjectSpace(x.CFrame);
											r.bsparts[#r.bsparts+1]=x;
											local sm=x:FindFirstChildOfClass("SpecialMesh");
											if sm then
												local b=sm:GetAttribute("bs_s");
												if typeof(b)=="Vector3" then sm.Scale=b*mul;end;
											end;
										end;
									end;
									local hoff=c0*c1s:Inverse();
									if islobby then
										for x,rel in pairs(rels) do
											x.Anchored=true;
											x.CFrame=tgt.CFrame*M.cust.off*hoff*rel;
											r.bsdrive[#r.bsdrive+1]={x,tgt,hoff*rel};
										end;
									else
										handle.CFrame=tgt.CFrame*M.cust.off*hoff;
										local wd=Instance.new("Weld");
										wd.Name="BSAccWeld";wd.Part0=tgt;wd.Part1=handle;wd.C0=c0*M.cust.off;wd.C1=c1s;
										wd.Parent=handle;
										r.bsweld[#r.bsweld+1]={wd,c0};
									end;
									local ok=pcall(function() c.Parent=holder;end);
									if ok then
										r.made[#r.made+1]=c;
										n=n+1;
									end;
								end;
							end;
						end;
					end;
					pcall(function()
						M.dbg("PROP apply w="..tostring(w).." char="..char:GetFullName().." acc="..n.." parts="..#r.bsparts.." weldAtt="..viaatt.." weldFallback="..viafb.." lobby="..tostring(islobby).." drive="..#r.bsdrive.." autoMul="..string.format("%.3f",autoMul).." ratio="..string.format("%.3f",ratio).." legF="..string.format("%.3f",lf).." stdH="..(std and string.format("%.2f",std.h) or "-").." stdUT="..(std and string.format("%.2f",std.ut) or "-").." sizeMul="..tostring(M.cust.sizeMul).." hidden="..tostring(r.bshide and #r.bshide or 0));
					end);
					return n,"проп, аксессуаров: "..n..(r.bshide and (", скрыто родных частей: "..#r.bshide) or "");
				end;

				local function dress(char,src,w)
					if src:GetAttribute("bs_prop") then return apply_prop(char,src,w);end;
					local ok,tpl=pcall(make_tpl,src);
					if ok and tpl then
						local cnt,why=overlay(char,tpl,w);
						pcall(card_show,tpl,w,cnt~=nil);
						if cnt then return cnt,"оверлей, частей: "..cnt;end;
						local n,info=apply_model(char,src,w);
						return n,tostring(info).." | оверлей не вышел: "..tostring(why);
					end;
					local n,info=apply_model(char,src,w);
					return n,tostring(info).." | шаблон не собрался: "..tostring(tpl);
				end;

				local function user_model(name)
					local key=name:lower();
					if ucache[key] then return ucache[key];end;
					local okId,uid=pcall(function() return Players:GetUserIdFromNameAsync(name);end);
					if not(okId and uid) then
						uid=tonumber(name);
						if not uid then return nil,"ник не найден: "..name;end;
					end;
					local ok,m=pcall(function()
						local okd,hd=pcall(function() return Players:GetHumanoidDescriptionFromUserId(uid);end);
						if okd and hd then
							pcall(function() hd.HeightScale=1;hd.WidthScale=1;hd.DepthScale=1;hd.HeadScale=1;hd.BodyTypeScale=0;hd.ProportionScale=0;end);
							local okm,mm=pcall(function() return Players:CreateHumanoidModelFromDescription(hd,Enum.HumanoidRigType.R15);end);
							if okm and mm then return mm;end;
						end;
						local okf,mf=pcall(function() return Players:CreateHumanoidModelFromUserId(uid);end);
						if okf and mf then return mf;end;
						return Players:GetCharacterAppearanceAsync(uid);
					end);
					if not(ok and m) then return nil,"не смог загрузить внешку: "..name;end;
					ucache[key]=m;
					return m;
				end;

				local function want()
					if sel.user then return "user:"..sel.user;end;
					local k=sel[curside()];
					if k and agents[k] then return "agent:"..k;end;
					return nil;
				end;

				PV.pend=setmetatable({},{__mode="k"});
				local function apply_async(char,w)
					if failed[w] then return;end;
					if busy[char] then PV.pend[char]=w;return;end;
					busy[char]=true;
					task.spawn(function()
						local ok,err=pcall(function()
							if w:sub(1,5)=="user:" then
								local name=w:sub(6);
								say("ищу "..name.."...");
								local m,why=user_model(name);
								if not m then
									failed[w]=true;
									say(why);
									return;
								end;
								local n,info=dress(char,m,w);
								say(name..": надето, аксессуаров "..tostring(n).." | "..tostring(info));
							else
								local a=agents[w:sub(7)];
								pcall(function() M.dbg("APPLY agent w="..tostring(w).." char="..char:GetFullName().." found="..tostring(a~=nil).." parent="..tostring(a and a.inst.Parent~=nil));end);
								if not a or not a.inst.Parent then
									failed[w]=true;
									say("агент не найден в игре");
									return;
								end;
								local n,info=dress(char,a.inst,w);
								say(a.name..": надето, аксессуаров "..tostring(n).." | "..tostring(info));
							end;
						end);
						busy[char]=nil;
						if not ok then
							failed[w]=true;
							pcall(function() M.dbg("APPLY ERROR w="..tostring(w).." err="..tostring(err));end);
							say("ошибка: "..tostring(err));
						end;
						do
							local pw=PV.pend[char];
							PV.pend[char]=nil;
							if pw and pw~=w and not failed[pw] and char.Parent and want()==pw then apply_async(char,pw);end;
						end;
					end);
				end;

				local function mine()
					local out,seen={},{};
					local function add(c)
						if typeof(c)=="Instance" and c.Parent and not seen[c] then
							seen[c]=true;
							out[#out+1]=c;
						end;
					end;
					add(lp.Character);
					local okj,J=pcall(K.load,"j");
					local cr=okj and J and J.char_resolver or nil;
					if type(cr)=="table" and type(cr.getPlayerCharacter)=="function" then
						local ok,c=pcall(cr.getPlayerCharacter,lp);
						if ok then add(c);end;
					end;
					local holders={};
					for _,nm in ipairs({"Characters","_PVS_CulledCharacters"}) do
						local h=workspace:FindFirstChild(nm);
						if h then holders[#holders+1]=h;end;
					end;
					for _,h in ipairs(holders) do
						add(h:FindFirstChild(lp.Name));
						for _,c in ipairs(h:GetChildren()) do
							local uid=c:GetAttribute("UserId");
							if uid~=nil and tostring(uid)==tostring(lp.UserId) then add(c);end;
						end;
					end;
					local okp,lm=pcall(PV.lobby_peek);
					if okp then add(lm);end;
					return out;
				end;

				local function apply_now()
					local w=want();
					local list,n=mine(),0;
					for i=1,#list do
						if list[i]:FindFirstChild("UpperTorso",true) then
							n=n+1;
							if w then
								recs[list[i]]=recs[list[i]] and (function() recs[list[i]].want=nil;return recs[list[i]];end)() or nil;
								apply_async(list[i],w);
							else restore(list[i]);card_hide();
							end;
						end;
					end;
					if n==0 then say("не нашёл персонажа с UpperTorso");end;
				end;

				local function reset_all()
					sel.t,sel.ct,sel.user=nil,nil,nil;
					failed={};
					local list=mine();
					for i=1,#list do restore(list[i]);end;
					for c in pairs(recs) do restore(c);end;
					if cards then pcall(function() cards:set("Stock",true);end);end;
					card_hide();say("сброшено");
				end;

				-- смена респавна/стороны: докидываем нужное
				local t=0;
				A.connect(RS.Heartbeat,function(dt)
					t=t+dt;
					if t<0.5 then return;end;
					t=0;
					if not M.auto then return;end;
					local w=want();
					if not w then card_hide();end;
					local list=mine();
					local inset={};
					for i=1,#list do inset[list[i]]=true;end;
					for c in pairs(recs) do if not inset[c] then restore(c);end;end;
					for i=1,#list do
						local c=list[i];
						if not busy[c] and c:FindFirstChild("UpperTorso",true) then
							local r=recs[c];
							if w then
								if not r or r.want~=w or not welds_ok(r,c) then apply_async(c,w);end;
							elseif r then
								restore(c);
							end;
						end;
					end;
				end);
				A.connect(RS.RenderStepped,function()
					for c,r in pairs(recs) do
						local dm=r.dummy;
						if dm and dm.Parent then
							local h=r.hide;
							for i=1,#h do
								local p=h[i];
								if p.Parent and p.Transparency<1 then p.Transparency=1;end;
							end;
							local hide=c:GetAttribute("ClientCharacterPresentationVisible")==false or c:GetAttribute("Dead")==true or not c:IsDescendantOf(workspace);
							if not hide then
								local cam=workspace.CurrentCamera;
								local head=r.head;
								if cam and head and head.Parent and (cam.CFrame.Position-head.Position).Magnitude<1.3 then hide=true;end;
							end;
							local lt=hide and 1 or 0;
							local pts=r.pts;
							for i=1,#pts do
								local p=pts[i];
								if p.Parent and p.LocalTransparencyModifier~=lt then p.LocalTransparencyModifier=lt;end;
							end;
						end;
					end;
				end);
				A.teardown(function()
					pcall(card_destroy);
					local list=mine();
					for i=1,#list do restore(list[i]);end;
					for c in pairs(recs) do restore(c);end;
				end);

				----------------------------------------------------------------
				-- поиск родных агентов в ReplicatedStorage
				----------------------------------------------------------------
				local function norm_side(s)
					s=tostring(s):lower();
					if s:find("counter") or s=="ct" then return "ct";end;
					if s:find("terror") or s=="t" then return "t";end;
					return nil;
				end;
				local function side_of(inst)
					local a=inst:GetAttribute("Team") or inst:GetAttribute("Side");
					local r=a and norm_side(a);
					if r then return r;end;
					local p=inst;
					while p and p~=RSt do
						local n=p.Name:lower();
						if n:find("counter") or n:find("^ct[%s_%-]") or n:find("[%s_%-]ct$") or n=="ct" then return "ct";end;
						if n:find("terror") or n:find("^t[%s_%-]") or n:find("[%s_%-]t$") or n=="t" then return "t";end;
						p=p.Parent;
					end;
					return "?";
				end;
				local function is_outfit(i)
					if not(i:IsA("Model") or i:IsA("Folder")) then return false;end;
					for _,d in ipairs(i:GetDescendants()) do
						if d:IsA("Accessory") or d:IsA("Shirt") or d:IsA("Pants") or d:IsA("BodyColors") then return true;end;
					end;
					return false;
				end;

				-- оперативник из главного меню: ищем модель с телом во ViewportFrame'ах PlayerGui (меню), запасной вариант — своя модель
					lobby_model=function()
						do local okf,fm=pcall(PV.menu_fast);if okf and fm then return fm;end;end;
						local log={"lobby scan"};
						local best,score=nil,-1;
						local function consider(m,why)
							if not m:IsA("Model") then return;end;
							local sc=0;
							if m:FindFirstChildOfClass("Humanoid") then sc=sc+2;end;
							if is_outfit(m) then sc=sc+2;end;
							if m:FindFirstChild("UpperTorso",true) then sc=sc+2;end;
							local n=m.Name:lower();
							if n==lp.Name:lower() or n:find("operative") or n:find("agent") or n:find("char") then sc=sc+1;end;
							log[#log+1]=why..": "..m:GetFullName().." score="..sc;
							if sc>score then best,score=m,sc;end;
						end;
						local pg=lp:FindFirstChildOfClass("PlayerGui");
						if pg then
							local cnt=0;
							for _,d in ipairs(pg:GetDescendants()) do
								cnt=cnt+1;
								if cnt%2500==0 then task.wait();end;
								if d:IsA("Model") and d:FindFirstAncestorWhichIsA("ViewportFrame") and d:FindFirstAncestorWhichIsA("ViewportFrame")~=card.vp then
									consider(d,"viewport");
								end;
							end;
						end;
						if score<2 then
							local list=mine();
							for i=1,#list do consider(list[i],"character");end;
							local w=workspace:FindFirstChild(lp.Name);
							if w then consider(w,"workspace");end;
						end;
						if not card.logged then
							card.logged=true;
							pcall(function() if type(writefile)=="function" then writefile("lobby_scan.txt",table.concat(log,"\n"));end;end);
						end;
						if best and score>=2 then return best;end;
						return nil;
					end;

					-- превью выбранной плитки: строится из шаблона сразу, не ждёт матча/персонажа
					PV.on_lobby=function()
						pcall(apply_now);
						-- FIX: лобби-агента нашли позже, чем собралось превью (статичная модель/случайный источник): переходим на зеркало лобби
						local lob=PV.lobby;
						local mir=card.mirror;
						if lob and card.gui and card.gui.Parent and os.clock()>=(PV.nomirror_until or 0) and not(mir and mir.src==lob) then
							PV.refresh();
						end;
					end;
					local function fromTo(a,b)
						local dot=math.clamp(a:Dot(b),-1,1);
						local ax=a:Cross(b);
						if ax.Magnitude<1e-5 then
							if dot>0 then return CFrame.identity;end;
							local pp=a:Cross(Vector3.yAxis);
							if pp.Magnitude<1e-3 then pp=a:Cross(Vector3.xAxis);end;
							return CFrame.fromAxisAngle(pp.Unit,math.pi);
						end;
						return CFrame.fromAxisAngle(ax.Unit,math.acos(dot));
					end;
					local function rotAbout(cf,pivot,R) return CFrame.new(pivot)*R*CFrame.new(-pivot)*cf;end;
					local function ik_limb(L,ddrop)
						local oU,oL,oE,nE=L[1],L[2],L[3],L[4];
						if not(oU.Parent and oL.Parent and oE.Parent and nE.Parent) then return;end;
						local a_sh,a_el1,a_wr1,a_wr2,a_nwr=L[5],L[6],L[8],L[9],L[10];
						local S=(oU.CFrame*a_sh).Position;
						local Ec=(oU.CFrame*a_el1).Position;
						local l1=(a_el1.Position-a_sh.Position).Magnitude;
						local l2=(a_wr1.Position-L[7].Position).Magnitude;
						local up=Vector3.new(0,ddrop or 0,0); -- dropStep опустит весь скин на ddrop после IK, цель поднимаем заранее
						local T=(nE.CFrame*a_nwr).Position+up;
						local v=T-S;
						local dist=v.Magnitude;
						if dist<1e-4 or l1<1e-4 or l2<1e-4 then return;end;
						local dir=v/dist;
						-- NOSTRETCH: bones are never scaled. If the skin arm cannot reach the native hand, slide the whole arm toward it (translation only). Disable: getgenv().Z_ARM_SLIDE=false
						if (getgenv and getgenv().Z_ARM_SLIDE)~=false and oE.Name:find("Hand") then
							local reach=(l1+l2)*0.97;
							if dist>reach then
								local sh=dir*math.min(dist-reach,(l1+l2)*0.25);
								oU.CFrame=oU.CFrame+sh;
								oL.CFrame=oL.CFrame+sh;
								S=S+sh;
								Ec=Ec+sh;
								v=T-S;
								dist=v.Magnitude;
								if dist<1e-4 then return;end;
								dir=v/dist;
							end;
						end;
						local d=math.clamp(dist,math.abs(l1-l2)+0.01,l1+l2-0.01);
						local a=(l1*l1-l2*l2+d*d)/(2*d);
						local h=math.sqrt(math.max(l1*l1-a*a,0));
						-- направление сгиба берём у родной конечности (она в правильной позе), запасной вариант - по цепочке скина
						local perp;
						if L[11] and L[11].Parent and L[12] and L[13] then
							local nS=(L[11].CFrame*L[12]).Position+up;
							local nEl=(L[11].CFrame*L[13]).Position+up;
							local nd=T-nS;
							if nd.Magnitude>1e-3 then
								local ndir=nd.Unit;
								local nv=nEl-nS;
								local pn=nv-ndir*nv:Dot(ndir);
								if pn.Magnitude>0.03*l1 then perp=pn;end;
							end;
						end;
						if not perp then
							local pv=Ec-S;
							perp=pv-dir*pv:Dot(dir);
						end;
						if perp.Magnitude<1e-3 then
							perp=dir:Cross(Vector3.yAxis);
							if perp.Magnitude<1e-3 then perp=dir:Cross(Vector3.xAxis);end;
						end;
						perp=perp.Unit;
						local E=S+dir*a+perp*h;
						local Tp=S+dir*d;
						local R1=fromTo((Ec-S).Unit,(E-S).Unit);
						oU.CFrame=rotAbout(oU.CFrame,S,R1);
						local oL1=rotAbout(oL.CFrame,S,R1);
						local W1=(oL1*a_wr1).Position;
						local R2=fromTo((W1-E).Unit,(Tp-E).Unit);
						oL.CFrame=rotAbout(oL1,E,R2);
						-- кисть/стопа сидит на конце нижней кости (не отрывается, даже если до родной точки не достать), ориентация - как у родной
						local wcf=nE.CFrame*a_nwr;
						local wp=(oL.CFrame*a_wr1).Position;
						if not L.logged then
							L.logged=true;
							pcall(function() if M.dbg then M.dbg(string.format("IKREACH %s dist=%.2f l1=%.2f l2=%.2f unreachable=%s",oU.Name,dist,l1,l2,tostring(dist>l1+l2-0.01)));end;end);
						end;
						if (getgenv and getgenv().Z_HAND_REL)==true and oE.Name:find("Hand") and L[14] and L[14].Parent and L[15] then
							-- кисть: поза запястья как у родной относительно предплечья (без излома), положение - конец нижней кости
							local J=(L[14].CFrame*L[15]):ToObjectSpace(wcf);
							local jr=J-J.Position;
							local base=oL.CFrame*a_wr1;
							oE.CFrame=(CFrame.new(wp)*((base-base.Position)*jr))*a_wr2:Inverse();
						else
							oE.CFrame=(CFrame.new(wp)*(wcf-wcf.Position))*a_wr2:Inverse();
						end;
					end;
					-- DROP helpers: самая низкая точка детали по мировой Y (по габариту с учётом поворота)
					local function lowY(pt)
						local cf,sz=pt.CFrame,pt.Size;
						local h=(math.abs(cf.XVector.Y)*sz.X+math.abs(cf.YVector.Y)*sz.Y+math.abs(cf.ZVector.Y)*sz.Z)*0.5;
						return cf.Position.Y-h;
					end;
					local function dropStep(r,dr)
						local D=r.drop;
						if not D then return;end;
						local ov=getgenv and getgenv().Z_SKIN_DROP;
						local target=0;
						if ov==false then
							target=0;
						elseif tonumber(ov) then
							target=math.clamp(tonumber(ov),-1,2);
						else
							local sl,nl=math.huge,math.huge;
							for i=1,#D.fs do
								local sp,np=D.fs[i],D.fn[i];
								if not(sp.Parent and np.Parent) then return;end;
								sl=math.min(sl,lowY(sp));
								nl=math.min(nl,lowY(np));
							end;
							if sl==math.huge then return;end;
							-- в лобби части каждый кадр ставятся заново (сдвиг в замере = 0), в игре замер уже включает прошлый сдвиг
							local raw=(sl-nl)+(dr and 0 or D.dd);
							target=math.clamp(raw,0,0.9);
						end;
						D.dd=dr and target or (D.dd+(target-D.dd)*0.2);
						local dd=D.dd;
						if math.abs(dd)<1e-3 and not(dr) and not D.dirty then return;end;
						D.dirty=math.abs(dd)>=1e-3;
						if dr then
							-- лобби: все части скина, которые мы двигаем каждый кадр, - строго вниз по мировой Y (поворот/масштаб не трогаем)
							local off=Vector3.new(0,-dd,0);
							for i=1,#dr do
								local p=dr[i][1];
								if p.Parent then p.CFrame=p.CFrame+off;end;
							end;
						elseif r.dropw then
							-- игра: сварки с родными частями, сдвиг задаём через C0 в системе родной части (чтобы он всегда был строго вниз по миру)
							local wv=Vector3.new(0,-dd,0);
							for i=1,#r.dropw do
								local e=r.dropw[i];
								local wd,o,c0=e[1],e[2],e[3];
								if wd.Parent and o.Parent and wd.Part0==o then wd.C0=CFrame.new(o.CFrame:VectorToObjectSpace(wv))*c0;end;
							end;
						end;
					end;
					A.connect(RS.RenderStepped,function()
						for _,r in pairs(recs) do
							local dr=r.drive;
							if not dr and r.dropw then pcall(dropStep,r,nil);end;
							if dr then
								local cs=r.chain_skip;
								-- 1) части, идущие за родными (корень тела и т.п.)
								for i=1,#dr do
									local pr=dr[i];
									if not pr[4] and not(cs and cs[pr[1]]) and pr[1].Parent and pr[2].Parent then pr[1].CFrame=pr[2].CFrame*(pr[3] or CFrame.identity);end;
								end;
								-- 1b) ноги: сшиваем суставы по аттачментам скина, только сдвигом (без масштаба и без поворота)
								local sn=r.snaps;
								if sn and not r.chain then
									for i=1,#sn do
										local e=sn[i];
										local par,ch,pa,ca=e[1],e[2],e[3],e[4];
										if par.Parent and ch.Parent and pa.Parent and ca.Parent then
											local want=(par.CFrame*pa.CFrame).Position;
											local cur=(ch.CFrame*ca.CFrame).Position;
											local dlt=want-cur;
											if not(e[5] and dlt.Magnitude>e[5]) then ch.CFrame=ch.CFrame+dlt;end;
										end;
									end;
								end;
								-- 2) цепочка суставов: торс -> голова/руки/ноги
								local ch=r.chain;
								if ch then
									for i=1,#ch do
										local c=ch[i];
										local oc,op,nc,np=c[1],c[2],c[3],c[4];
										if oc.Parent and op.Parent and nc.Parent and np.Parent then
											local J=(np.CFrame*c[8]):ToObjectSpace(nc.CFrame*c[7]);
											oc.CFrame=(op.CFrame*c[6])*J*c[5];
										end;
									end;
								end;
								-- 2b) IK конечностей: кисти/стопы строго на родных, локти/колени пересчитаны
								local lbs=r.limbs;
								if lbs and not M.no_limb_ik then local ddv=(r.drop and r.drop.dd) or 0;for i=1,#lbs do pcall(ik_limb,lbs[i],ddv);end;end;
								-- 2c) ARMFK: плечо -> предплечье -> кисть от торса скина; поворот сустава как у родной руки, стыки сшиваем только сдвигом (без растяжения)
								local afk=r.armfk;
								if afk then
									for i=1,#afk do
										local lk=afk[i];
										for k=1,#lk do
											local e=lk[k];
											local sc,sp,np,nc,pa,ca=e[1],e[2],e[3],e[4],e[5],e[6];
											if sc.Parent and sp.Parent and np.Parent and nc.Parent then
												local cf=sp.CFrame*np.CFrame:ToObjectSpace(nc.CFrame);
												if pa and ca then
													local dl=(sp.CFrame*pa).Position-(cf*ca).Position;
													if dl.Magnitude<1.5 then cf=cf+dl;end;
												end;
												sc.CFrame=cf;
											end;
										end;
									end;
								end;
								-- 3) всё, что висит на частях оверлея (аксессуары без родной пары)
								for i=1,#dr do
									local pr=dr[i];
									if pr[4] and pr[1].Parent and pr[2].Parent then pr[1].CFrame=pr[2].CFrame*(pr[3] or CFrame.identity);end;
								end;
								pcall(dropStep,r,dr);
								local G=r.gunf;
								if G then
									if not(G.root.Parent and G.root:IsDescendantOf(G.char)) then
										-- игра заменила оружие в лобби: убираем клон и просим пересборку оверлея
										pcall(function() G.gc:Destroy();end);
										r.gunf=nil;r.gunc=nil;r.want=nil;
									elseif G.nH.Parent and G.sH.Parent then
										pcall(function()
											local nW=G.nH.CFrame*G.nA;
											local sW=G.sH.CFrame*G.sA;
											-- ствол чуть ниже (мировая Y, в студах). по умолчанию 0.3, свой: getgenv().Z_GUN_DY=число (0 = как было)
											local gdy=tonumber(getgenv and getgenv().Z_GUN_DY);
											if gdy==nil then gdy=0.3;end;
											if gdy~=0 then sW=sW+Vector3.new(0,-gdy,0);end;
											local inv=nW:Inverse();
											local gp=G.pairs;
											for i=1,#gp do
												local pr=gp[i];
												if pr[1].Parent and pr[2].Parent then pr[2].CFrame=sW*(inv*pr[1].CFrame);end;
											end;
										end);
									end;
								end;
							end;
						end;
					end);
					-- ===================== ПРЕВЬЮ = ЗЕРКАЛО ЖИВОГО ЛОББИ-АГЕНТА =====================
					-- скин на лобби-агента вешает основная логика (overlay -> workspace.ClientOverlay),
					-- а превью просто каждый кадр повторяет положение всех его частей, так что поза/оружие/скин всегда как в лобби
					PV.hum_quiet=function(m)
						for _,h in ipairs(m:GetDescendants()) do
							if h:IsA("Humanoid") then
								pcall(function()
									h.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None;
									h.HealthDisplayType=Enum.HumanoidHealthDisplayType.AlwaysOff;
									h.BreakJointsOnDeath=false;
									h.RequiresNeck=false;
									h.EvaluateStateMachine=false;
								end);
							end;
						end;
					end;
					PV.sclone=tcache.__sclone;
					PV.vis_count=function(src)
						local n=0;
						local function cnt(rt)
							for _,d in ipairs(rt:GetDescendants()) do
								if d:IsA("BasePart") and d.Name~="HumanoidRootPart" and d.Transparency<0.9 and d.Size.Magnitude<12 then n=n+1;end;
							end;
						end;
						cnt(src);
						local r=recs[src];
						if r then
							if type(r.made)=="table" then
								for _,x in ipairs(r.made) do
									if typeof(x)=="Instance" and x.Parent then cnt(x);end;
								end;
							elseif typeof(r.dummy)=="Instance" and r.dummy.Parent then
								cnt(r.dummy);
							end;
						end;
						return n;
					end;
					PV.live_char=function()
						local cands,seen={}, {};
						local function add(c)
							if typeof(c)=="Instance" and c.Parent and not seen[c] and not PV.bad_src(c) and c:FindFirstChild("UpperTorso",true) and (c:FindFirstChild("HumanoidRootPart",true) or c:FindFirstChild("LowerTorso",true)) then
								seen[c]=true;
								cands[#cands+1]=c;
							end;
						end;
						for _,c in ipairs(mine()) do add(c);end;
						local ok,m=pcall(PV.find_lobby);
						local fast=PV.menu_fast();
						if fast then ok,m=true,fast;end;
						if ok and m then add(m);end;
						local best,bn=nil,0;
						for _,c in ipairs(cands) do
							local n=PV.vis_count(c);
						if ((ok and m) or PV.lobby) and c==((ok and m) or PV.lobby) and n>=3 then n=n+1000;end;
							if n>bn then best,bn=c,n;end;
						end;
						return best,math.floor(bn);
					end;
					PV.mirror_stop=function()
						local mir=card.mirror;
						if mir and mir.conns then
							for _,cn in ipairs(mir.conns) do pcall(function() cn:Disconnect();end);end;
						end;
						card.mirror=nil;
					end;
					PV.mirror_build=function(src)
						local mm=Instance.new("Model");
						mm.Name="LobbyMirror";
						local prs={};
						local roots={src};
						local r=recs[src];
						if r then
							if type(r.made)=="table" then
								for _,x in ipairs(r.made) do
									if typeof(x)=="Instance" and x.Parent then roots[#roots+1]=x;end;
								end;
							elseif typeof(r.dummy)=="Instance" and r.dummy.Parent then
								roots[#roots+1]=r.dummy;
							end;
						end;
						for _,rt in ipairs(roots) do
							local c=PV.sclone(rt);
							if c then
								local mine_pairs={};
								local function walk(a,b)
									if a:IsA("BasePart") and b:IsA("BasePart") then mine_pairs[#mine_pairs+1]={a,b};end;
									local ca,cb=a:GetChildren(),b:GetChildren();
									if #ca==#cb then
										for i=1,#ca do walk(ca[i],cb[i]);end;
									else
										local used={};
										for _,x in ipairs(ca) do
											for j,y in ipairs(cb) do
												if not used[j] and y.Name==x.Name and y.ClassName==x.ClassName then used[j]=true;walk(x,y);break;end;
											end;
										end;
									end;
								end;
								walk(rt,c);
								-- части без пары остались бы на мировых координатах далеко от камеры и раздували рамку модели
								do
									local pset={};
									for _,pr in ipairs(mine_pairs) do pset[pr[2]]=true;end;
									for _,d in ipairs(c:GetDescendants()) do
										if d:IsA("BasePart") and not pset[d] then pcall(function() d:Destroy();end);end;
									end;
								end;
								local junk={};
								for _,d in ipairs(c:GetDescendants()) do
									if d:IsA("BaseScript") or d:IsA("Sound") or d:IsA("Animator") or d:IsA("JointInstance") or d:IsA("WeldConstraint") or d:IsA("Constraint") or d:IsA("ForceField") then junk[#junk+1]=d;end;
								end;
								for _,d in ipairs(junk) do pcall(function() d:Destroy();end);end;
								PV.hum_quiet(c);
								for _,pr in ipairs(mine_pairs) do
									local d=pr[2];
									d.Anchored=true;
									d.CanCollide=false;
									d.CanQuery=false;
									d.CanTouch=false;
									pcall(PV.fix_skin_part,d);
									if d:IsA("MeshPart") then pcall(function() d.RenderFidelity=Enum.RenderFidelity.Precise;end);end;
									prs[#prs+1]=pr;
								end;
								c.Parent=mm;
							end;
						end;
						return mm,prs;
					end;
					PV.mirror_place=function(mir)
						local root=mir.root;
						local inv=root.CFrame:Inverse();
						local rcf=mir.rcf;
						for _,pr in ipairs(mir.pairs) do
							local sp,dp=pr[1],pr[2];
							if sp.Parent then
								dp.CFrame=rcf*(inv*sp.CFrame);
								dp.Transparency=sp.Transparency;
								if (dp.Position-rcf.Position).Magnitude>9 then dp.Transparency=1;end;
								if mir.hide and mir.hide[dp] then dp.Transparency=1;end;
							end;
						end;
						local g=mir.gun;
						if g and g.hand.Parent then
							local hcf=g.hand.CFrame*g.c0;
							for _,gp in ipairs(g.parts) do gp.CFrame=hcf*g.rel[gp];end;
						end;
					end;
					-- оружие из списка "preview gun" вместо оружия лобби-агента
					-- FIX: часть оружия родной модели (любой предок Weapon*/Equipped/Tool внутри src)
					PV.in_weapon=function(sp,src)
						if not(src and sp:IsDescendantOf(src)) then return false;end;
						local a=sp.Parent;
						while a and a~=src do
							local n=a.Name;
							if n=="Equipped" or n:find("^Weapon") or a:IsA("Tool") then return true;end;
							a=a.Parent;
						end;
						return false;
					end;
					PV.mirror_gun=function(mir,mm)
						pcall(tcache.__elev);
						mir.gun,mir.hide=nil,{};
						local BS={Head=1,UpperTorso=1,LowerTorso=1,LeftUpperArm=1,LeftLowerArm=1,LeftHand=1,RightUpperArm=1,RightLowerArm=1,RightHand=1,LeftUpperLeg=1,LeftLowerLeg=1,LeftFoot=1,RightUpperLeg=1,RightLowerLeg=1,RightFoot=1,HumanoidRootPart=1};
						local WN={MuzzlePart=1,Barrel=1,Mag=1,Magazine=1,Bolt=1,other=1,Handle=1,body=1,Hitbox=1,Insert=1,Casing=1,ChargingHandle=1,ChargingLock=1,HandGuard=1,DustCover=1,MagBullets=1,Silencer=1,TriggerGuard=1,Stock=1};
						local mz=mir.src:FindFirstChild("MuzzlePart",true);
						local wroot=mz and mz.Parent;
						if wroot==mir.src then wroot=nil;end;
						for _,pr in ipairs(mir.pairs) do
							local sp,dp=pr[1],pr[2];
							if not BS[sp.Name] then
								if (wroot and sp:IsDescendantOf(wroot)) or PV.in_weapon(sp,mir.src) or (sp:IsDescendantOf(mir.src) and (WN[sp.Name] or sp.Name:find("^Receiver"))) then
									mir.hide[dp]=true;
								end;
							end;
						end;
						if not(PV.gun and PV.gun~="none") then return;end;
						local hand;
						for _,pr in ipairs(mir.pairs) do if pr[2].Name=="RightHand" then hand=pr[2];break;end;end;
						if not hand then return;end;
						local gs=PV.gun_src(PV.gun);
						if not gs then return;end;
						local g=PV.sclone(gs);
						if not g then return;end;
						local all={};
						if g:IsA("BasePart") then all[1]=g;end;
						for _,d in ipairs(g:GetDescendants()) do
							if d:IsA("BasePart") then all[#all+1]=d;
							elseif d:IsA("JointInstance") or d:IsA("WeldConstraint") or d:IsA("BaseScript") or d:IsA("Sound") then pcall(function() d:Destroy();end);end;
						end;
						if #all==0 then pcall(function() g:Destroy();end);return;end;
						local handle;
						for _,gp in ipairs(all) do if gp.Name=="Handle" then handle=gp;break;end;end;
						if not handle then
							local ba=0;
							for _,gp in ipairs(all) do
								local a=gp.Size.X*gp.Size.Y*gp.Size.Z;
								if a>ba then ba=a;handle=gp;end;
							end;
						end;
						local rel={};
						for _,gp in ipairs(all) do
							rel[gp]=handle.CFrame:ToObjectSpace(gp.CFrame);
							gp.Anchored=true;gp.CanCollide=false;gp.CanQuery=false;gp.CanTouch=false;
							if gp:IsA("MeshPart") then pcall(function() gp.RenderFidelity=Enum.RenderFidelity.Precise;end);end;
						end;
						local grip=hand:FindFirstChild("RightGripAttachment");
						local c0=(grip and grip.CFrame) or (CFrame.new(0,-0.125,0)*CFrame.Angles(math.rad(-90),0,0));
						g.Name="PreviewGun";
						g.Parent=mm;
						mir.gun={hand=hand,parts=all,rel=rel,handle=handle,c0=c0,model=g};
					end;
					-- true = превью построено зеркалом, false = лобби-агента не нашли (старый способ)
					-- FIX: в зеркале должно быть минимум 4 видимые части тела
					PV.body_ready=function(prs)
						local n=0;
						for _,pr in ipairs(prs) do
							local d=pr[2];
							if BODYSET[d.Name] and d.Transparency<0.9 then n=n+1;end;
						end;
						return n>=4;
					end;
					PV.mirror_start=function(tpl,w,ok)
						if os.clock()<(PV.nomirror_until or 0) then return false;end;
						tcache.__elev();
						card.tpl,card.w,card.ok=tpl,w,ok;
						card.dflt=(w==nil);
						if not card_build() then return false;end;
						local title,subtxt=tostring(w),"";
						if w==nil then
							title,subtxt="default","main menu operative";
						elseif w:sub(1,5)=="user:" then
							title=w:sub(6);subtxt="skin by nickname";
						else
							local a=agents[w:sub(7)];
							title=a and a.name or w:sub(7);
							subtxt="agent"..((a and a.side and a.side~="?") and (" · "..a.side:upper()) or "");
						end;
						pcall(function() card.title.Text=title;card.sub.Text=subtxt;end);
						local tok=(card.tok or 0)+1;
						card.tok=tok;
						local src=PV.live_char();
						if card.tok~=tok then return true;end;
						if not src then pcall(function() if M.dbg then M.dbg("MIRROR: live_char = nil");end;end);return false;end;
						local root=src:FindFirstChild("HumanoidRootPart",true) or src:FindFirstChild("LowerTorso",true);
