							if not okc then say("зеркало превью не вышло: "..tostring(started));pcall(function() card.sub.Text=card.sub.Text.." · mirror ERR";end);pcall(function() if M.dbg then M.dbg("MIRROR ERR: "..tostring(started));end;end);else say("лобби-агента с видимыми частями не нашёл, показываю шаблон");pcall(function() card.sub.Text=card.sub.Text.." · mirror none";end);pcall(function() if M.dbg then M.dbg("MIRROR none: no visible parts");end;end);end;
