						end;
						-- FIX: dress() уже собрал это превью - второй полный ребилд заставлял модель мигать и появляться поздно
						if card.mirror and card.lastw==w and os.clock()-(card.lastt or -9)<1.5 then return;end;
						local src,why;
						if w:sub(1,5)=="user:" then
							src,why=user_model(w:sub(6));
						else
							local a=agents[w:sub(7)];
							src=a and a.inst;
						end;
						if not src then
							if why then say(why);end;
							return;
						end;
						local ok,tpl=pcall(make_tpl,src);
						if ok and tpl then pcall(card_show,tpl,w,true);end;
					end;

					-- сохранённые скины по нику: плитки в вкладке agents, лежат в vol_nick_skins.json
					local NFILE="vol_nick_skins.json";
					local HS=game:GetService("HttpService");
					local saved={};   -- {{name=,uid=}}
					pcall(function()
						if type(isfile)=="function" and isfile(NFILE) then
							local d=HS:JSONDecode(readfile(NFILE));
							if type(d)=="table" then
								for _,e in ipairs(d) do
									if type(e)=="table" and type(e.name)=="string" and tonumber(e.uid) then
										saved[#saved+1]={name=e.name,uid=tonumber(e.uid)};
									end;
								end;
							end;
						end;
					end);
					local function saved_write()
						pcall(function()
							if type(writefile)=="function" then writefile(NFILE,HS:JSONEncode(saved));end;
						end);
					end;

					task.spawn(function()
						for _,e in ipairs(saved) do
							pcall(user_model,e.name);
							task.wait(0.25);
						end;
					end);

					local function card_items()
						local items={{value="Stock",name="Default"}};
						for _,k in ipairs(order) do
							items[#items+1]={value=k,name=agents[k].tag};
						end;
						for _,e in ipairs(saved) do
							items[#items+1]={value="user:"..e.name,name=e.name,image="rbxthumb://type=AvatarBust&id="..e.uid.."&w=150&h=150"};
						end;
						items[#items+1]={value="__add",name="add skin",add=true};
						return items;
					end;
					PV.decorate_default=function()
					if not cards then return false;end;
					pcall(tcache.__elev);
					local pool=cards.pool;
					if type(pool)~="table" then return false;end;
					local tile;
					for _,t in ipairs(pool) do
						if t.b and t.b.Parent then
							if t.v=="Stock" then tile=t;
							else local o=t.b:FindFirstChild("DefVP");if o then pcall(function() o:Destroy();end);end;end;
						end;
					end;
					if not tile then return false;end;
					if tile.b:FindFirstChild("DefVP") then return true;end;
					local ct,tt;
					for _,ch in ipairs(workspace:GetChildren()) do
						local ts=ch:FindFirstChild("TeamSelect");
						if ts then
							for _,x in ipairs(ts:GetChildren()) do
								if x:IsA("Model") then
									local n=x.Name:lower();
									if n:find("teamselectcharacter") then
										if n:find("ct$") then ct=ct or x;else tt=tt or x;end;
									end;
								end;
							end;
							if ct or tt then break;end;
						end;
					end;
					if not(ct or tt) then return false;end;
					local vp=Instance.new("ViewportFrame");
					vp.Name="DefVP";vp.BackgroundTransparency=1;vp.BorderSizePixel=0;vp.Active=false;vp.ZIndex=3;
					vp.AnchorPoint=Vector2.new(0.5,0);vp.Position=UDim2.new(0.5,0,0,7);vp.Size=UDim2.new(1,-14,1,-34);
					vp.Ambient=Color3.fromRGB(190,190,190);vp.LightColor=Color3.fromRGB(255,255,255);
					local cam=Instance.new("Camera");cam.FieldOfView=30;vp.CurrentCamera=cam;cam.Parent=vp;
					local function put(src,x)
						local m=src and tcache.__sclone(src);
						if not m then return;end;
						for _,d in ipairs(m:GetDescendants()) do
							if d:IsA("BaseScript") or d:IsA("Sound") or d:IsA("Animator") then pcall(function() d:Destroy();end);
							elseif d:IsA("BasePart") then d.Anchored=true;d.CanCollide=false;d.CanQuery=false;d.CanTouch=false;end;
						end;
						pcall(PV.hum_quiet,m);
						m.Parent=vp;
						pcall(function() m:PivotTo(CFrame.new(x,0,0));end);
					end;
					put(ct,1.5);put(tt,-1.5);
					cam.CFrame=CFrame.lookAt(Vector3.new(0,0.3,-13),Vector3.new(0,-0.2,0));
					vp.Parent=tile.b;
					return true;
				end;
				local function build_cards()
						if cards then pcall(function() cards:setvalues(card_items(),true);end);end;
						pcall(PV.decorate_default);
					end;

					-- ник -> userId, сохраняем и сразу надеваем
					local function add_nick(text,done)
						task.spawn(function()
							local name=text;
							local okId,id=pcall(function() return Players:GetUserIdFromNameAsync(name);end);
							if not(okId and id) then id=tonumber(name);end;
							if not id then done(false,"ник не найден");return;end;
							local okN,real=pcall(function() return Players:GetNameFromUserIdAsync(id);end);
							if okN and real then name=real;end;
							for _,e in ipairs(saved) do
								if e.name:lower()==name:lower() then done(false,"уже добавлен");return;end;
							end;
							saved[#saved+1]={name=name,uid=id};
							saved_write();
							build_cards();
							done(true);
							say("скин добавлен: "..name);
							pcall(function() cards:set("user:"..name);end);
						end);
					end;
					local function nick_menu(val,c)
						if type(val)~="string" or val:sub(1,5)~="user:" then return false;end;
						local name=val:sub(6);
						c:button({name="remove",style="danger",cb=function()
							for i=#saved,1,-1 do
								if saved[i].name:lower()==name:lower() then table.remove(saved,i);end;
							end;
							saved_write();
							ucache[name:lower()]=nil;
							build_cards();
							if cards and cards.val==val then pcall(function() cards:set("Stock");end);end;
							say("удалён: "..name);
						end});
						return true;
					end;

					----------------------------------------------------------------
					-- CUSTOM MODELS: внешние модели из папки в workspace экзекутора (bs_models/)
					--   файл .rbxm/.rbxmx      готовая модель: R15-риг / одежда+аксессуары / аксессуар / проп из частей
					--   файл .obj/.mesh        один меш (+ одноимённый .png/.jpg как текстура) -> аксессуар
					--   ПАПКА с .obj (+.mtl, текстуры рядом или в подпапке) -> .obj режется по материалам, каждому своя текстура
					-- .obj движок Roblox напрямую не читает ("unknown version") - скрипт сам конвертирует его в формат Roblox .mesh v1.00 и кладёт в bs_models_cache/
					-- опции в имени файла/папки через @:  имя@attach=HatAttachment@scale=0.5@height=5@x=0@y=-0.3@z=0@rot=180@flip=1@inv=1@msc=2@hide=1
					-- (старый формат тоже работает: имя@Attachment@масштаб)
					----------------------------------------------------------------
					local CUSTOM_DIR="bs_models";
					local CACHE_DIR="bs_models_cache";
					local custom={n=0};
					local cgca=getcustomasset or getsynasset;
					local clbl;
					local CEXT={rbxm=true,rbxmx=true,obj=true,mesh=true};
					local function csay(t)
						pcall(function() if clbl then clbl:settext(t);end;end);
					end;
					-- всё, что пишет загрузчик, дублируем в общий DBG-буфер скрипта (кнопка DBG -> copy)
					local function custom_dbg(log)
						for _,l in ipairs(log) do pcall(function() M.dbg("CUSTOM "..tostring(l));end);end;
						pcall(function() if type(writefile)=="function" then writefile("bs_models_scan.txt",table.concat(log,"\n"));end;end);
					end;
					local function custom_holder()
						if custom.holder and custom.holder.Parent then return custom.holder;end;
						pcall(tcache.__elev);
						local okF,f=pcall(Instance.new,"Folder");
						if not(okF and f) then return nil;end;
						f.Name=tostring(math.random(10000000,90000000));
						local cands={};
						pcall(function() if gethui then cands[#cands+1]=gethui();end;end);
						pcall(function() cands[#cands+1]=game:GetService("CoreGui");end);
						pcall(function() cands[#cands+1]=game:GetService("ReplicatedStorage");end);
						for _,par in ipairs(cands) do
							if par then
								pcall(function() f.Parent=par;end);
								if f.Parent then custom.holder=f;return f;end;
							end;
						end;
						return nil;
					end;
					A.teardown(function()
						pcall(function() if custom.holder then custom.holder:Destroy();end;end);
					end);
					-- живая подстройка размера / высоты (слайдеры в секции custom models)
					M.cust=M.cust or {sizeMul=1,yoff=0,off=CFrame.new()};
					M.cust.refresh=function()
						M.cust.off=CFrame.new(0,M.cust.yoff or 0,0);
						for _,r in pairs(recs) do
							if r.bsparts then
								local mul=(r.bsmul or 1)*(M.cust.sizeMul or 1);
								for _,p in ipairs(r.bsparts) do
									local sm=p:FindFirstChildOfClass("SpecialMesh");
									if sm then
										local b=sm:GetAttribute("bs_s");
										if typeof(b)=="Vector3" then sm.Scale=b*mul;end;
									end;
								end;
								if r.bsweld then
									for _,e in ipairs(r.bsweld) do
										if e[1].Parent then e[1].C0=e[2]*M.cust.off;end;
									end;
								end;
							end;
						end;
					end;
					-- скрытие родного тела (опция hide) держим в силе каждый кадр
					A.connect(RS.RenderStepped,function()
						for c,r in pairs(recs) do
							local dv=r.bsdrive;
							if dv then
								for i=1,#dv do
									local e=dv[i];
									if e[1].Parent and e[2].Parent then e[1].CFrame=e[2].CFrame*M.cust.off*e[3];end;
								end;
							end;
							local pp=r.bsparts;
							if pp and c.Parent then
								local lt=0;
								if c:GetAttribute("ClientCharacterPresentationVisible")==false or c:GetAttribute("Dead")==true then lt=1;end;
								local cam=workspace.CurrentCamera;
								local hd=r.bshead;
								if lt==0 and cam and hd and hd.Parent and (cam.CFrame.Position-hd.Position).Magnitude<1.3 then lt=1;end;
								for i=1,#pp do
									local p=pp[i];
									if p.Parent and p.LocalTransparencyModifier~=lt then p.LocalTransparencyModifier=lt;end;
								end;
							end;
							local h=r.bshide;
							if h then
								for i=1,#h do
									local p=h[i];
									if p.Parent and p.Transparency<1 then p.Transparency=1;end;
								end;
							end;
						end;
					end);
					local function custom_opts(stem)
						local seg={};
						for s in (stem.."@"):gmatch("([^@]*)@") do seg[#seg+1]=s;end;
						local o={name=(seg[1]~="" and seg[1] or stem),height=5,x=0,z=0,rot=0,flip=false};
						local pos=0;
						for i=2,#seg do
							local k,v=seg[i]:match("^(%w+)=(.+)$");
							if k then
								k=k:lower();
								if k=="attach" then o.attach=v;
								elseif k=="scale" then o.scale=tonumber(v);
								elseif k=="height" then o.height=tonumber(v) or 5;o.hset=true;
								elseif k=="x" then o.x=tonumber(v) or 0;
								elseif k=="y" then o.y=tonumber(v);
								elseif k=="z" then o.z=tonumber(v) or 0;
								elseif k=="rot" then o.rot=tonumber(v) or 0;
								elseif k=="flip" then o.flip=(v=="1" or v:lower()=="true");
								elseif k=="hide" then o.hide=(v=="1" or v:lower()=="true");
								elseif k=="inv" then o.inv=(v=="1" or v:lower()=="true");
								elseif k=="msc" then o.msc=tonumber(v);
								end;
							elseif seg[i]~="" then
								pos=pos+1;
								if pos==1 then o.attach=seg[i];elseif pos==2 then o.scale=tonumber(seg[i]);end;
							end;
						end;
						o.stem=stem;
						return o;
					end;
					local function custom_parse(file)
						local stem,ext=file:match("^(.+)%.(%w+)$");
						if not stem then return nil;end;
						ext=ext:lower();
						if not CEXT[ext] then return nil;end;
						local o=custom_opts(stem);
						o.ext=ext;
						o.attach=o.attach or "BodyFrontAttachment";
						o.scale=o.scale or 1;
						return o;
					end;
					-- где ручка сидит относительно точки крепления: сдвиг x/y/z + поворот rot (градусы по Y)
					local function custom_att_cf(info,defy)
						local cf=CFrame.new(info.x or 0,info.y or defy or 0,info.z or 0)*CFrame.Angles(0,math.rad(info.rot or 0),0);
						return cf:Inverse();
					end;
					local function custom_tex(stem)
						for _,e in ipairs({"png","jpg","jpeg"}) do
							local p=CUSTOM_DIR.."/"..stem.."."..e;
							local ok,has=pcall(isfile,p);
							if ok and has then
								local okA,a=pcall(cgca,p);
								if okA and type(a)=="string" then return a;end;
							end;
						end;
						return nil;
					end;
					local function custom_kind(m)
						local body,cloth,acc=0,false,false;
						for _,x in ipairs(m:GetDescendants()) do
							if x:IsA("MeshPart") and BODYSET[x.Name] then body=body+1;
							elseif x:IsA("Clothing") or x:IsA("BodyColors") or x:IsA("ShirtGraphic") then cloth=true;
							elseif x:IsA("Accessory") then acc=true;end;
						end;
						if m:IsA("Accessory") then acc=true;end;
						if body>=8 then return "rig";end;
						if cloth then return "outfit";end;
						if acc then return "acc";end;
						return "prop";
					end;
					-- произвольные части (не R15) -> один Accessory: корневая часть = Handle, остальные на Weld с явным C0
					local function custom_to_accessory(model,info)
						local parts={};
						if model:IsA("BasePart") then parts[1]=model;end;
						for _,d in ipairs(model:GetDescendants()) do
							if d:IsA("BasePart") then parts[#parts+1]=d;end;
						end;
						if #parts==0 then return nil,"в файле нет ни одной части";end;
						local root=(model:IsA("Model") and model.PrimaryPart) or parts[1];
						local hcf,sc=root.CFrame,info.scale;
						local acc=Instance.new("Accessory");
						acc.Name=info.name;
						local clones,handle={},nil;
						for _,p in ipairs(parts) do
							local c=tcache.__lclone(p);
							if c then
								for _,x in ipairs(c:GetDescendants()) do
									if x:IsA("BasePart") or x:IsA("JointInstance") or x:IsA("WeldConstraint") or x:IsA("Constraint") then
										pcall(x.Destroy,x);
									elseif x:IsA("SpecialMesh") then
										pcall(function() x.Scale=x.Scale*sc;end);
									end;
								end;
								c.Anchored=false;c.CanCollide=false;c.CanQuery=false;c.CanTouch=false;c.Massless=true;
								c.Size=p.Size*sc;
								clones[#clones+1]={p=p,c=c};
								if p==root then handle=c;end;
							end;
						end;
						if not handle then return nil,"не вышло клонировать корневую часть";end;
						handle.Name="Handle";
						local at=Instance.new("Attachment");at.Name=info.attach;at.CFrame=custom_att_cf(info,0);at.Parent=handle;
						handle.Parent=acc;
						for _,e in ipairs(clones) do
							if e.c~=handle then
								local off=hcf:Inverse()*e.p.CFrame;
								local w=Instance.new("Weld");
								w.Part0=handle;w.Part1=e.c;
								w.C0=CFrame.new(off.Position*sc)*(off-off.Position);
								w.Parent=e.c;
								e.c.Parent=acc;
							end;
						end;
						return acc;
					end;
					----------------------------------------------------------------
					-- разбор .obj / .mtl, нарезка по материалам
					----------------------------------------------------------------
					local function obj_parse(txt)
						local V,VT,VN={}, {}, {};
						local groups,gorder,cur,mtllib={}, {}, nil,nil;
						local nv,nvt,nvn,lines=0,0,0,0;
						local function grp(name)
							local g=groups[name];
							if not g then g={name=name,faces={}};groups[name]=g;gorder[#gorder+1]=g;end;
							return g;
						end;
						for line in txt:gmatch("[^\r\n]+") do
							lines=lines+1;
							if lines%4000==0 then task.wait();end;
							local c2=line:sub(1,2);
							if c2=="v " then
								local x,y,z=line:match("^v%s+(%S+)%s+(%S+)%s+(%S+)");
								nv=nv+1;V[nv]={tonumber(x) or 0,tonumber(y) or 0,tonumber(z) or 0};
							elseif c2=="vt" then
								local u,v=line:match("^vt%s+(%S+)%s+(%S+)");
								nvt=nvt+1;VT[nvt]={tonumber(u) or 0,tonumber(v) or 0};
							elseif c2=="vn" then
								local x,y,z=line:match("^vn%s+(%S+)%s+(%S+)%s+(%S+)");
								nvn=nvn+1;VN[nvn]={tonumber(x) or 0,tonumber(y) or 0,tonumber(z) or 0};
							elseif c2=="f " then
								local face={};
								for tok in line:sub(3):gmatch("%S+") do
									local a,b,c=tok:match("^(-?%d+)/?(-?%d*)/?(-?%d*)$");
									if a then
										a=tonumber(a);if a<0 then a=nv+1+a;end;
										b=tonumber(b);if b and b<0 then b=nvt+1+b;end;
										c=tonumber(c);if c and c<0 then c=nvn+1+c;end;
										face[#face+1]={a,b,c};
									end;
								end;
								if #face>=3 then
									cur=cur or grp("default");
									cur.faces[#cur.faces+1]=face;
								end;
							elseif line:sub(1,7)=="usemtl " then
								cur=grp((line:match("^usemtl%s+(.-)%s*$")) or "default");
							elseif line:sub(1,7)=="mtllib " then
								mtllib=line:match("^mtllib%s+(.-)%s*$");
							end;
						end;
						return {V=V,VT=VT,VN=VN,groups=groups,order=gorder,mtllib=mtllib};
					end;
					local function obj_bbox(d,bb)
						for _,g in ipairs(d.order) do
							for _,f in ipairs(g.faces) do
								for _,t in ipairs(f) do
									local v=d.V[t[1]];
									if v then
										bb.x0=math.min(bb.x0,v[1]);bb.x1=math.max(bb.x1,v[1]);
										bb.y0=math.min(bb.y0,v[2]);bb.y1=math.max(bb.y1,v[2]);
										bb.z0=math.min(bb.z0,v[3]);bb.z1=math.max(bb.z1,v[3]);
									end;
								end;
							end;
						end;
					end;
					local function safe_name(s)
						return (tostring(s):gsub("[^%w_%-]","_"));
					end;
					-- группы граней -> текст Roblox .mesh v1.00 (треугольники, вершина = [pos][normal][uv,0]); координаты сдвинуты на центр c и умножены на msc
					-- msc=2: в v1.00 движок домножает координаты на 0.5, компенсируем; если модель вышла вдвое больше/меньше - msc=1 или msc=4
					local function mesh_emit(d,groups,c,flipv,inv,msc)
						local cx,cy,cz=c[1],c[2],c[3];
						local out,nf={}, 0;
						local ey0,ey1=math.huge,-math.huge;
						local function vtx(t,fn)
							local v=d.V[t[1]];
							local n=(t[3] and d.VN[t[3]]) or fn;
							local uv=t[2] and d.VT[t[2]];
							local u,w=0,0;
							if uv then u=uv[1];w=flipv and (1-uv[2]) or uv[2];end;
							local yy=(v[2]-cy)*msc;
							if yy<ey0 then ey0=yy;end;
							if yy>ey1 then ey1=yy;end;
							return string.format("[%.5f,%.5f,%.5f][%.4f,%.4f,%.4f][%.5f,%.5f,0]",(v[1]-cx)*msc,yy,(v[3]-cz)*msc,n[1],n[2],n[3],u,w);
						end;
						for _,g in ipairs(groups) do
							for _,f in ipairs(g.faces) do
								for k=2,#f-1 do
									local a,b,cc=f[1],f[k],f[k+1];
									local va,vb,vc=d.V[a[1]],d.V[b[1]],d.V[cc[1]];
									if va and vb and vc then
										if inv then b,cc=cc,b;vb,vc=vc,vb;end;
										local ux,uy,uz=vb[1]-va[1],vb[2]-va[2],vb[3]-va[3];
										local wx,wy,wz=vc[1]-va[1],vc[2]-va[2],vc[3]-va[3];
										local nx,ny,nz=uy*wz-uz*wy,uz*wx-ux*wz,ux*wy-uy*wx;
										local ln=math.sqrt(nx*nx+ny*ny+nz*nz);
										if ln>1e-12 then nx,ny,nz=nx/ln,ny/ln,nz/ln;else nx,ny,nz=0,1,0;end;
										local fn={nx,ny,nz};
										nf=nf+1;
										out[nf]=vtx(a,fn)..vtx(b,fn)..vtx(cc,fn);
										if nf%3000==0 then task.wait();end;
									end;
								end;
							end;
						end;
						if nf==0 then return nil;end;
						return "version 1.00\n"..nf.."\n"..table.concat(out),nf,ey0,ey1;
					end;
					-- пишет .mesh в кэш-папку и отдаёт rbxasset:// (имя уникальное на каждую загрузку, старый кэш чистим один раз за сессию)
					local function cache_asset(tag,txt)
						pcall(makefolder,CACHE_DIR);
						if not custom.cleaned then
							custom.cleaned=true;
							local okC,old=pcall(listfiles,CACHE_DIR);
							if okC and type(old)=="table" then
								for _,p in ipairs(old) do pcall(delfile,p);end;
							end;
						end;
						custom.n=custom.n+1;
						local cpath=CACHE_DIR.."/"..safe_name(tag).."__"..tostring(os.time())..tostring(custom.n)..".mesh";
						if not pcall(writefile,cpath,txt) then return nil,"writefile не записал "..cpath;end;
						local ok,a=pcall(cgca,cpath);
						if ok and type(a)=="string" then return a,cpath;end;
						return nil,"getcustomasset: "..tostring(a);
					end;
					local function mtl_map(txt)
						local map,cur={}, nil;
						for line in txt:gmatch("[^\r\n]+") do
							local nm=line:match("^%s*newmtl%s+(.-)%s*$");
							if nm then cur=nm;
							else
								local p=line:match("^%s*map_Kd%s+(.-)%s*$");
								if p and cur and not map[cur] then map[cur]=p:match("([^/\\]+)$") or p;end;
							end;
						end;
						return map;
					end;
					-- папка-модель: нарезаем .obj по материалам, цепляем текстуры, собираем один Accessory из нескольких частей
					local function custom_build_dir(dir,info,log)
						local okL,files=pcall(listfiles,dir);
						if not(okL and type(files)=="table") then return nil,"listfiles не открыл папку";end;
						table.sort(files);
						local idx,objs={}, {};
						local function addfile(p)
							local b=tostring(p):match("([^/\\]+)$");
							if b then idx[b:lower()]=p;end;
						end;
						for _,p in ipairs(files) do
							local okF,isf=pcall(isfolder,p);
							if okF and isf then
								local okS,sub=pcall(listfiles,p);
								if okS and type(sub)=="table" then
									for _,q in ipairs(sub) do addfile(q);end;
								end;
							else
								addfile(p);
								if tostring(p):lower():match("%.obj$") then objs[#objs+1]=p;end;
							end;
						end;
						do
							local okT,tl=pcall(listfiles,CUSTOM_DIR.."/textures");
							if okT and type(tl)=="table" then
								for _,q in ipairs(tl) do
									local b=tostring(q):match("([^/\\]+)$");
									if b and not idx[b:lower()] then idx[b:lower()]=q;end;
								end;
							end;
						end;
						do
							local names={};
							for k in pairs(idx) do names[#names+1]=k;end;
							table.sort(names);
							log[#log+1]="  files seen ("..#names.."): "..table.concat(names,", ");
						end;
						if #objs==0 then return nil,"в папке нет .obj";end;
						-- парсим все .obj, общий bbox
						local datas,bb={}, {x0=math.huge,x1=-math.huge,y0=math.huge,y1=-math.huge,z0=math.huge,z1=-math.huge};
						for _,p in ipairs(objs) do
							local okR,txt=pcall(readfile,p);
							if not(okR and type(txt)=="string") then return nil,"не прочитался "..tostring(p);end;
							local d=obj_parse(txt);
							d.path=p;
							-- материал -> имя текстуры
							local mtlPath;
							if d.mtllib then mtlPath=idx[(d.mtllib:match("([^/\\]+)$") or d.mtllib):lower()];end;
							if not mtlPath then
								local st=(tostring(p):match("([^/\\]+)$") or ""):gsub("%.%w+$","");
								mtlPath=idx[st:lower()..".mtl"];
							end;
							if not mtlPath then
								for k,v in pairs(idx) do if k:match("%.mtl$") then mtlPath=v;break;end;end;
							end;
							d.mtl={};
							if mtlPath then
								local okM,mt=pcall(readfile,mtlPath);
								if okM and type(mt)=="string" then d.mtl=mtl_map(mt);end;
							end;
							do
								local ms={};
								for k,v in pairs(d.mtl) do ms[#ms+1]=k.."="..v;end;
								log[#log+1]="  mtl="..tostring(mtlPath).." obj="..tostring(p).." mtllib="..tostring(d.mtllib).." map: "..table.concat(ms,"; ");
							end;
							obj_bbox(d,bb);
							datas[#datas+1]=d;
						end;
						local H=bb.y1-bb.y0;
						if not(H>0) then return nil,"пустая геометрия";end;
						local msc=info.msc or 2;
						local scale;
						local IMGEXT={png=true,jpg=true,jpeg=true,bmp=true,tga=true};
						local nidx,imgs={}, {};
						for k,v in pairs(idx) do
							local st,ex=k:match("^(.+)%.(%w+)$");
							if st and IMGEXT[ex] then
								nidx[(st:gsub("[^%w]",""))]=v;
								imgs[#imgs+1]=v;
							end;
						end;
						log[#log+1]="  images found: "..#imgs;
						-- ищем картинку: имя из .mtl -> имя материала (регистр, пробелы, _ и - не важны) -> частичное совпадение
						local function find_img(base,matname)
							if base then
								local k=(base:lower():gsub("%.%w+$",""):gsub("[^%w]",""));
								if nidx[k] then return nidx[k];end;
							end;
							local m=(tostring(matname):lower():gsub("[^%w]",""));
							if nidx[m] then return nidx[m];end;
							if m~="" then
								for k,v in pairs(nidx) do
									if k:find(m,1,true) or m:find(k,1,true) then return v;end;
								end;
							end;
							return nil;
						end;
						local entries={};
						local total=0;
						for _,d in ipairs(datas) do
							local ostem=safe_name((tostring(d.path):match("([^/\\]+)$") or "obj"):gsub("%.%w+$",""));
							for _,g in ipairs(d.order) do
								total=total+1;
								local txt,_,ey0,ey1=mesh_emit(d,{g},{(bb.x0+bb.x1)/2,(bb.y0+bb.y1)/2,(bb.z0+bb.z1)/2},not info.flip,info.inv,msc);
								if txt then
									local asset,werr=cache_asset(info.stem.."__"..ostem.."__"..tostring(g.name),txt);
									if asset then
										-- текстура: map_Kd из .mtl -> имя материала -> единственная картинка в папке
										local tpath=find_img(d.mtl[g.name],g.name) or (#imgs==1 and imgs[1] or nil);
										local tex;
										if tpath then
											local okT,ta=pcall(cgca,tpath);
											if okT and type(ta)=="string" then tex=ta;end;
										end;
										log[#log+1]="  part "..tostring(g.name).." faces="..#g.faces.." tex="..tostring(tpath).." texAsset="..tostring(tex~=nil).." mesh="..tostring(werr);
										entries[#entries+1]={name=g.name,asset=asset,tex=tex,ext=(ey1 or 0)-(ey0 or 0)};
									else
										log[#log+1]="  part "..tostring(g.name).." FAIL: "..tostring(werr);
									end;
								end;
								task.wait();
							end;
						end;
						-- калибровка размера: спрашиваем у движка реальный MeshSize загруженного меша (сравниваем с тем, что записали в файл)
						local kk;
						if not info.scale then
							pcall(tcache.__elev);
							local tries=0;
							for _,e in ipairs(entries) do
								if e.ext>0.3*H*msc and tries<2 then
									tries=tries+1;
									local okM,mp=pcall(function()
										local m=Instance.new("MeshPart");
										m.MeshId=e.asset;
										return m;
									end);
									if okM and mp then
										pcall(function() mp.Parent=custom_holder();end);
										pcall(function() game:GetService("ContentProvider"):PreloadAsync({mp});end);
										local okS,ms=pcall(function() return mp.MeshSize;end);
										pcall(mp.Destroy,mp);
										if okS and typeof(ms)=="Vector3" and ms.Y>0.001 then
											local k=ms.Y/e.ext;
											log[#log+1]="  calib: part "..tostring(e.name).." MeshSize.Y="..string.format("%.3f",ms.Y).." written="..string.format("%.3f",e.ext).." k="..string.format("%.3f",k);
											if k>0.02 and k<50 then kk=k;break;end;
										else
											log[#log+1]="  calib: MeshSize не прочитался ("..tostring(ms)..")";
										end;
									else
										log[#log+1]="  calib: MeshPart.MeshId недоступен ("..tostring(mp)..")";
									end;
								end;
							end;
						end;
						scale=info.scale or (info.height/(H*msc*(kk or 0.5)));
						log[#log+1]="  scale="..string.format("%.4f",scale).." H="..string.format("%.2f",H).." msc="..msc.." k="..tostring(kk or "assumed 0.5");
						local acc=Instance.new("Accessory");acc.Name=info.name;
						local handle;
						local made=0;
						local function mkpart(asset,tex)
							local pt=Instance.new("Part");
							pt.Size=Vector3.one;pt.CanCollide=false;pt.CanQuery=false;pt.CanTouch=false;pt.Massless=true;pt.Anchored=false;
							local sm=Instance.new("SpecialMesh");
							sm.MeshType=Enum.MeshType.FileMesh;sm.MeshId=asset;
							if tex then sm.TextureId=tex;end;
							sm.Scale=Vector3.one*scale;
							sm:SetAttribute("bs_s",sm.Scale);
							sm.Parent=pt;
							return pt;
						end;
						for _,e in ipairs(entries) do
							local pt=mkpart(e.asset,e.tex);
							pt.Name=handle and ("P_"..safe_name(e.name)) or "Handle";
							if not handle then
								handle=pt;
								local at=Instance.new("Attachment");
								at.Name=info.attach or "WaistCenterAttachment";
								at.CFrame=custom_att_cf(info,-0.3);
								at.Parent=pt;
								pt.Parent=acc;
							else
								local w=Instance.new("Weld");
								w.Part0=handle;w.Part1=pt;w.C0=CFrame.new();w.C1=CFrame.new();
								w.Parent=pt;
								pt.Parent=acc;
							end;
							made=made+1;
						end;
						if made==0 then pcall(acc.Destroy,acc);return nil,"ни одна часть не собралась";end;
						local model=Instance.new("Model");
						acc.Parent=model;
						model.Name=info.name;
						model:SetAttribute("bs_prop",true);
						model:SetAttribute("bs_mesh",true);
						model:SetAttribute("bs_h",info.height);
						if info.hset then model:SetAttribute("bs_hu",info.height);end;
						if info.hide~=false then model:SetAttribute("bs_hide",true);end;
						return model,"папка: частей "..made.."/"..total..", scale "..string.format("%.3f",scale)..", k="..tostring(kk or "0.5?");
					end;

					local function custom_build(path,info)
						local ext,model,kind=info.ext;
						local asset;
						if ext~="obj" then
							local okG,ga=pcall(cgca,path);
							if not(okG and type(ga)=="string") then return nil,"getcustomasset: "..tostring(ga);end;
							asset=ga;
						end;
						if ext=="rbxm" or ext=="rbxmx" then
							local okO,objs=pcall(game.GetObjects,game,asset);
							if not(okO and type(objs)=="table" and #objs>0) then
								local okI,o2=pcall(function() return game:GetService("InsertService"):LoadLocalAsset(asset);end);
								if okI and typeof(o2)=="Instance" then objs={o2};
								else return nil,"GetObjects/LoadLocalAsset не открыли файл: "..tostring(objs);end;
							end;
							if #objs==1 then model=objs[1];
							else
								model=Instance.new("Model");
								for _,o in ipairs(objs) do pcall(function() o.Parent=model;end);end;
							end;
							if model:IsA("LuaSourceContainer") then pcall(model.Destroy,model);return nil,"в файле только скрипт";end;
							for _,d in ipairs(model:GetDescendants()) do
								if d:IsA("LuaSourceContainer") then pcall(d.Destroy,d);end;
							end;
							kind=custom_kind(model);
							if kind=="prop" then
								local acc,why=custom_to_accessory(model,info);
								pcall(model.Destroy,model);
								if not acc then return nil,why;end;
								model=Instance.new("Model");
								acc.Parent=model;
							elseif kind=="acc" and model:IsA("Accessory") then
								local wrap=Instance.new("Model");
								model.Parent=wrap;
								model=wrap;
							end;
						else
							if ext=="obj" then
								local okR,txt=pcall(readfile,path);
								if not(okR and type(txt)=="string") then return nil,"не прочитался .obj";end;
								local d=obj_parse(txt);
								local mt=mesh_emit(d,d.order,{0,0,0},not info.flip,info.inv,info.msc or 2);
								if not mt then return nil,"в .obj нет граней";end;
								local werr;
								asset,werr=cache_asset(info.stem,mt);
								if not asset then return nil,tostring(werr);end;
							end;
							local tex=custom_tex(info.stem);
							local acc=Instance.new("Accessory");acc.Name=info.name;
							local h=Instance.new("Part");
							h.Name="Handle";h.Size=Vector3.one;h.CanCollide=false;h.CanQuery=false;h.CanTouch=false;h.Massless=true;
							local sm=Instance.new("SpecialMesh");
							sm.MeshType=Enum.MeshType.FileMesh;sm.MeshId=asset;
							if tex then sm.TextureId=tex;end;
							sm.Scale=Vector3.one*info.scale;
							sm:SetAttribute("bs_s",sm.Scale);
							sm.Parent=h;
							local at=Instance.new("Attachment");at.Name=info.attach;at.CFrame=custom_att_cf(info,0);at.Parent=h;
							h.Parent=acc;
							model=Instance.new("Model");
							acc.Parent=model;
							kind="mesh";
						end;
						model.Name=info.name;
						if kind~="rig" and kind~="outfit" then
							model:SetAttribute("bs_prop",true);
							if kind=="mesh" then model:SetAttribute("bs_mesh",true);end;
							if info.hide then model:SetAttribute("bs_hide",true);end;
						end;
						return model,kind;
					end;
					-- читает папку и добавляет найденное в agents/order (карточки строит вызывающий)
					local function custom_inject(log)
						log=log or {};
						local n,bad=0,0;
						if not(type(isfolder)=="function" and type(listfiles)=="function" and type(cgca)=="function" and type(readfile)=="function" and type(writefile)=="function") then
							log[#log+1]="custom: экзекутор без isfolder/listfiles/readfile/writefile/getcustomasset";
							return 0,"custom models: экзекутору не хватает функций файлов";
						end;
						pcall(tcache.__elev);
						local okd,hasd=pcall(isfolder,CUSTOM_DIR);
						if not(okd and hasd) then
							pcall(makefolder,CUSTOM_DIR);
							log[#log+1]="custom: создал папку "..CUSTOM_DIR;
							return 0,"папка workspace/"..CUSTOM_DIR.." создана - кидай туда модели и жми reload";
						end;
						local okl,files=pcall(listfiles,CUSTOM_DIR);
						if not(okl and type(files)=="table") then return 0,"listfiles не отработал";end;
						table.sort(files);
						for _,path in ipairs(files) do
							local file=tostring(path):match("([^/\\]+)$");
							local okF,isf=pcall(isfolder,path);
							local info,isdir;
							if okF and isf then
								if file then
									info=custom_opts(file);
									isdir=true;
								end;
							else
								info=file and custom_parse(file);
							end;
							if info then
								local ok,model,kind;
								if isdir then
									log[#log+1]="custom dir: "..file;
									ok,model,kind=pcall(custom_build_dir,path,info,log);
								else
									ok,model,kind=pcall(custom_build,path,info);
								end;
								if ok and model then
									local par=custom_holder();
									if par then pcall(function() model.Parent=par;end);end;
									log[#log+1]="  holder="..tostring(par and par:GetFullName()).." modelParented="..tostring(model.Parent~=nil);
									local nm=(info.name:gsub("_"," "));
									local key="custom|"..info.stem;
									agents[key]={inst=model,name=nm,side="?",tag="MY · "..nm,custom=true,kind=kind};
									order[#order+1]=key;
									n=n+1;
									log[#log+1]="custom: "..tostring(file).." -> "..tostring(kind);
								else
									bad=bad+1;
									log[#log+1]="custom FAIL: "..tostring(file).." | "..tostring(ok and kind or model);
								end;
								task.wait();
							end;
						end;
						return n,"моделей из workspace/"..CUSTOM_DIR..": "..n..(bad>0 and (", ошибок "..bad.." (см. bs_models_scan.txt)") or "");
					end;
					local function custom_reload()
						for i=#order,1,-1 do
							local a=agents[order[i]];
							if a and a.custom then
								pcall(function() a.inst:Destroy();end);
								agents[order[i]]=nil;
								table.remove(order,i);
							end;
						end;
						local log={"custom reload"};
						local _,msg=custom_inject(log);
						custom_dbg(log);
						table.sort(order,function(a,b)
							local x,y=agents[a],agents[b];
							if x.side~=y.side then return x.side<y.side;end;
							return x.name<y.name;
						end);
						pcall(function() if type(writefile)=="function" then writefile("bs_models_scan.txt",table.concat(log,"\n"));end;end);
						build_cards();
						csay(msg);
					end;

					local function scan()
					agents,order={}, {};
					local seen,log,cnt={}, {"scan ReplicatedStorage"},0;
					local function add(inst)
						if seen[inst] then return;end;
						seen[inst]=true;
						local sd=side_of(inst);
						local nm=inst.Name:gsub("_"," ");
						local key=sd.."|"..inst.Name;
						if agents[key] then key=key.."|"..tostring(#order+1);end;
						local tag=(sd=="t" and "T" or sd=="ct" and "CT" or "?").." · "..nm;
						agents[key]={inst=inst,name=nm,side=sd,tag=tag};
						order[#order+1]=key;
						log[#log+1]="agent: "..inst:GetFullName().." ["..sd.."]";
					end;
					local roots={RSt};
					for _,n in ipairs({"ReplicatedFirst","StarterPlayer","Lighting"}) do
						pcall(function() roots[#roots+1]=game:GetService(n);end);
					end;
					roots[#roots+1]=workspace;
					pcall(function() roots[#roots+1]=lp:FindFirstChildOfClass("PlayerGui");end);
					local kws={"agent","operative","outfit","playermodel","characterskin"};
					local function named(s)
						s=s:lower();
						for k=1,#kws do if s:find(kws[k],1,true) then return true;end;end;
						return false;
					end;
					for _,root in ipairs(roots) do
						for _,c in ipairs(root:GetDescendants()) do
							cnt=cnt+1;
							if cnt%3000==0 then task.wait();end;
							if (c:IsA("Folder") or c:IsA("Model")) and named(c.Name) and not Players:GetPlayerFromCharacter(c) then
								log[#log+1]="container: "..c:GetFullName();
								local added=false;
								for _,ch in ipairs(c:GetChildren()) do
									if is_outfit(ch) then
										add(ch);
										added=true;
									elseif ch:IsA("Folder") then
										for _,g in ipairs(ch:GetChildren()) do
											if is_outfit(g) then add(g);added=true;end;
										end;
									end;
								end;
								if not added and c:IsA("Model") and is_outfit(c) then add(c);end;
							end;
						end;
					end;
					-- запасной вариант: папка в RS, где >=2 прямых детей — наряды (имя может быть любое)
					if next(agents)==nil then
						log[#log+1]="-- по имени пусто, структурный поиск в ReplicatedStorage";
						for _,c in ipairs(RSt:GetDescendants()) do
							cnt=cnt+1;
							if cnt%3000==0 then task.wait();end;
							if c:IsA("Folder") and c.Name~="Hostages" then
								local kids={};
								for _,ch in ipairs(c:GetChildren()) do
									if is_outfit(ch) then kids[#kids+1]=ch;end;
								end;
								if #kids>=2 then
									log[#log+1]="outfit-folder: "..c:GetFullName();
									for _,ch in ipairs(kids) do add(ch);end;
								end;
							end;
						end;
					end;
					do local okc,_,cmsg=pcall(custom_inject,log);if okc then csay(cmsg);end;pcall(custom_dbg,log);end;
					table.sort(order,function(a,b)
						local x,y=agents[a],agents[b];
						if x.side~=y.side then return x.side<y.side;end;
						return x.name<y.name;
					end);
					if #order==0 then
						log[#log+1]="-- ничего не нашёл; кандидаты по имени:";
						local n2=0;
						for _,c in ipairs(RSt:GetDescendants()) do
							local nm=c.Name:lower();
							if nm:find("agent") or nm:find("outfit") or nm:find("playermodel") or nm:find("characterskin") then
								n2=n2+1;
								if n2>300 then break;end;
								log[#log+1]=c.ClassName.." "..c:GetFullName();
							end;
						end;
					end;
