					-- смена скина ствола во вкладке guns -> превью берёт этот ствол и перестраивается
					do
						local okS,S=pcall(K.load,"aw");
						if okS and type(S)=="table" then
							local function hook(fname,pick)
								local orig=rawget(S,fname);
								if type(orig)~="function" then return;end;
								local wrapped;
								wrapped=function(...)
									local r=table.pack(orig(...));
