			K.aH=function()
				-- ESP preview: агент из лобби (живая поза MenuCharacter) + оверлей, который читает настоящие настройки esp (tSet.en).
				-- Вкладка esp -> страница "preview". Использует PV/tcache из модуля aG (они отдаются через M.PV / M.tcache).
				local E,A=K.load("e"),K.load("a");
				local AG=K.load("aG");
				local PV,tcache=AG and AG.PV,AG and AG.tcache;
				if type(PV)~="table" or type(tcache)~="table" then
					warn("[killed] esp preview: agents module unavailable, skipped");
					return {};
				end;
				local okF,ESPM=pcall(K.load,"F");
				local cfg=(okF and type(ESPM)=="table" and type(ESPM.tSet)=="table") and ESPM.tSet.en or nil;
				if type(cfg)~="table" then
					warn("[killed] esp preview: esp settings unavailable, skipped");
					return {};
				end;
				local tab=E.tabs and E.tabs.visuals;
				local pages=tab and tab.pages;
				local page=type(pages)=="table" and pages[1] or nil;
				if not page then
					warn("[killed] esp preview: ESP players page unavailable, skipped");
					return {};
				end;
				local Players=game:GetService("Players");
				local RS=game:GetService("RunService");
				local UIS=game:GetService("UserInputService");
				local TextService=game:GetService("TextService");
				local lp=Players.LocalPlayer;

				local BODY={Head=1,UpperTorso=1,LowerTorso=1,LeftUpperArm=1,LeftLowerArm=1,LeftHand=1,RightUpperArm=1,RightLowerArm=1,RightHand=1,LeftUpperLeg=1,LeftLowerLeg=1,LeftFoot=1,RightUpperLeg=1,RightLowerLeg=1,RightFoot=1,Torso=1,["Left Arm"]=1,["Right Arm"]=1,["Left Leg"]=1,["Right Leg"]=1};
				local BONES={{"Head","UpperTorso"},{"UpperTorso","LowerTorso"},{"UpperTorso","LeftUpperArm"},{"LeftUpperArm","LeftLowerArm"},{"LeftLowerArm","LeftHand"},{"UpperTorso","RightUpperArm"},{"RightUpperArm","RightLowerArm"},{"RightLowerArm","RightHand"},{"LowerTorso","LeftUpperLeg"},{"LeftUpperLeg","LeftLowerLeg"},{"LeftLowerLeg","LeftFoot"},{"LowerTorso","RightUpperLeg"},{"RightUpperLeg","RightLowerLeg"},{"RightLowerLeg","RightFoot"}};

				local S={hp=100,armor=100,zoom=1,drag=0,want=true};

				----------------------------------------------------------------
				-- UI: компактное превью сверху слева на существующей странице Players во вкладке ESP
				----------------------------------------------------------------
				-- Use the existing ESP/Players subtab and put the compact preview at the top of its left column.
				local sec=page:section({name="preview",side=1});
				pcall(function() if sec.host and sec.host.frame then sec.host.frame.LayoutOrder=-1;end;end);
				local host=sec:free(220);
				if not host then
					warn("[killed] esp preview: no host frame, skipped");
					return {};
				end;
				local sec2=page:section({name="preview options",side=2});
				sec2:slider({name="health",flag="pvesp.hp",min=1,max=100,default=100,suffix="%",cb=function(v)
					S.hp=math.clamp(tonumber(v) or 100,1,100);
				end});
				sec2:slider({name="armor",flag="pvesp.armor",min=0,max=100,default=100,suffix="%",cb=function(v)
					S.armor=math.clamp(tonumber(v) or 0,0,100);
				end});
				sec2:button({name="rebuild preview",style="primary",cb=function()
					S.want=true;
				end});
				sec2:label({text="drag to rotate, wheel or pinch to zoom"});

				----------------------------------------------------------------
				-- GUI
				----------------------------------------------------------------
				local root=Instance.new("Frame");
				root.Name="EspPreview";
				root.Size=UDim2.new(1,0,1,0);
				root.BackgroundColor3=Color3.fromRGB(12,12,16);
				root.BackgroundTransparency=0.3;
				root.BorderSizePixel=0;
				root.ClipsDescendants=true;
				root.Parent=host;
				do
					local cr=Instance.new("UICorner");
					cr.CornerRadius=UDim.new(0,8);
					cr.Parent=root;
					local st=Instance.new("UIStroke");
					st.Color=Color3.new(1,1,1);
					st.Transparency=0.9;
					st.Thickness=1;
					st.Parent=root;
				end;
				A.own(root);

				local vp=Instance.new("ViewportFrame");
				vp.Name="View";
				vp.BackgroundTransparency=1;
				vp.Size=UDim2.new(1,0,1,0);
				vp.Ambient=Color3.fromRGB(190,190,200);
				vp.LightColor=Color3.new(1,1,1);
				vp.Active=true;
				vp.Parent=root;
				local cam=Instance.new("Camera");
				cam.FieldOfView=30;
				cam.Parent=vp;
				vp.CurrentCamera=cam;

				local ov=Instance.new("Frame");
				ov.Name="Overlay";
				ov.BackgroundTransparency=1;
				ov.BorderSizePixel=0;
				ov.Size=UDim2.new(1,0,1,0);
				ov.ZIndex=5;
				ov.ClipsDescendants=true;
				ov.Parent=root;

				local ALL={};
				local function reg(o)
					ALL[#ALL+1]=o;
					return o;
				end;
				local function frame(z,transparent)
					local f=Instance.new("Frame");
					f.BorderSizePixel=0;
					f.BackgroundColor3=Color3.new(1,1,1);
					f.BackgroundTransparency=transparent and 1 or 0;
					f.Visible=false;
					f.ZIndex=z or 6;
					f.Parent=ov;
					return reg(f);
				end;
				local function stroke(f)
					local s=Instance.new("UIStroke");
					s.ApplyStrokeMode=Enum.ApplyStrokeMode.Border;
					s.Thickness=1;
					s.Color=Color3.new(1,1,1);
					s.Parent=f;
					return s;
				end;
				local function label(z)
					local t=Instance.new("TextLabel");
					t.BackgroundTransparency=1;
					t.BorderSizePixel=0;
					t.Font=Enum.Font.Code;
					t.TextSize=13;
					t.Text="";
					t.Size=UDim2.fromOffset(130,13);
					t.TextWrapped=false;
					t.Visible=false;
					t.ZIndex=z or 8;
					t.Parent=ov;
					return reg(t);
				end;

				local F={};
				F.fill=frame(6);
				F.bo1=frame(7,true);F.bo1s=stroke(F.bo1);F.bo1s.Color=Color3.new(0,0,0);
				F.bo2=frame(7,true);F.bo2s=stroke(F.bo2);F.bo2s.Color=Color3.new(0,0,0);
				F.bm=frame(8,true);F.bms=stroke(F.bm);
				F.cs,F.cb={}, {};
				for i=1,8 do
					F.cb[i]=frame(7);F.cb[i].BackgroundColor3=Color3.new(0,0,0);
					F.cs[i]=frame(8);
				end;
				F.sk={};
				for i=1,#BONES do F.sk[i]=frame(7);end;
				local function mkbar()
					local b={};
					b.bg=frame(7);
					b.clip=frame(8);b.clip.ClipsDescendants=true;b.clip.BackgroundTransparency=1;
					local fl=Instance.new("Frame");
					fl.BorderSizePixel=0;fl.BackgroundColor3=Color3.new(1,1,1);fl.ZIndex=9;fl.Parent=b.clip;
					b.fill=fl;
					return b;
				end;
				F.hb=mkbar();
				F.ab=mkbar();
				F.name=label();
				F.av=Instance.new("ImageLabel");
				F.av.BackgroundTransparency=1;F.av.BorderSizePixel=0;F.av.ZIndex=8;F.av.Visible=false;
				F.av.Size=UDim2.fromOffset(16,16);
				F.av.Image="rbxthumb://type=AvatarHeadShot&id="..tostring(lp.UserId).."&w=48&h=48";
				F.av.Parent=ov;reg(F.av);
				F.wep=label();F.dis=label();F.mon=label();F.pn=label();F.ht=label();
				F.bomb=label();F.scope=label();F.flashed=label();F.defuse=label();
				F.icon=frame(8);
				do
					local cr=Instance.new("UICorner");
					cr.CornerRadius=UDim.new(0,2);
					cr.Parent=F.icon;
				end;
				F.note=Instance.new("TextLabel");
				F.note.BackgroundTransparency=1;F.note.Font=Enum.Font.GothamMedium;F.note.TextSize=13;
				F.note.TextColor3=Color3.fromRGB(150,155,175);F.note.Text="looking for the lobby agent...";
				F.note.Size=UDim2.new(1,0,0,20);F.note.Position=UDim2.new(0,0,0.5,-10);F.note.ZIndex=9;F.note.Parent=root;

				----------------------------------------------------------------
				-- хелперы значений настроек
				----------------------------------------------------------------
				local function pair(t,dc,da)
					if type(t)~="table" then return dc,da;end;
					local c=t[1];
					if typeof(c)~="Color3" then c=dc;end;
					local a=tonumber(t[2]);
					if a==nil then a=da;end;
					return c,a;
				end;
				local function grad(inst,on,t,rot)
					local g=inst:FindFirstChild("G");
					if on and type(t)=="table" and typeof(t[1])=="Color3" and typeof(t[2])=="Color3" then
						if not g then
							g=Instance.new("UIGradient");
							g.Name="G";
							g.Parent=inst;
						end;
						g.Rotation=rot or 90;
						g.Color=ColorSequence.new(t[1],t[2]);
						g.Enabled=true;
					elseif g then
						g.Enabled=false;
					end;
				end;
				local function sd(v,def)
					if v=="left" or v=="right" or v=="top" or v=="bottom" then return v;end;
					return def;
				end;
				local function place(o,x,y,w,h)
					o.Position=UDim2.fromOffset(math.floor(x+0.5),math.floor(y+0.5));
					if w then o.Size=UDim2.fromOffset(math.floor(w+0.5),math.floor(h+0.5));end;
				end;
				local function shown(g)
					local o=g;
					while o and o~=game do
						if o:IsA("GuiObject") then
							if not o.Visible then return false;end;
						elseif o:IsA("LayerCollector") then
							if not o.Enabled then return false;end;
						end;
						o=o.Parent;
					end;
					return o==game;
				end;

				----------------------------------------------------------------
				-- модель: клон лобби-агента с живой позой
				----------------------------------------------------------------
				local function gun_signature()
					local choice=tostring(PV.gun or "none");
					local name=choice;
					if type(PV.cur_gun_name)=="function" then
						local okn,n=pcall(PV.cur_gun_name);
						if okn and type(n)=="string" and n~="" then name=n;end;
					end;
					local skin="";
					if type(PV.ui_skin)=="function" and name~="none" then
						local oks,v=pcall(PV.ui_skin,name);
						if oks and v~=nil then skin=tostring(v);end;
					end;
					return choice.."|"..name.."|"..skin;
				end;
				local function destroy_model()
					if S.orig then
						S.orig=nil;
					end;
					if S.model then pcall(function() S.model:Destroy();end);end;
					if S.wm then pcall(function() S.wm:Destroy();end);end;
					if S.scene then pcall(function() S.scene:Destroy();end);end;
					S.model,S.wm,S.rig,S.live,S.src,S.parts,S.skp,S.tsig=nil,nil,nil,nil,nil,nil,nil,nil;
					S.scene,S.scamcf,S.gun,S.gunSig=nil,nil,nil,nil;
				end;

				local function build()
					tcache.__elev();
					destroy_model();
					local src,lobby;
					local okf,fm=pcall(PV.menu_fast);
					if okf and fm then
						src,lobby=fm,true;
					else
						local ch=lp.Character;
						if ch and ch:FindFirstChild("HumanoidRootPart",true) then src=ch;end;
					end;
					if not src then return false;end;
					local m=tcache.__sclone(src);
					if not m then return false;end;
					for _,x in ipairs(m:GetDescendants()) do
						if x:IsA("BaseScript") or x:IsA("Sound") or x:IsA("Animator") then pcall(function() x:Destroy();end);end;
					end;
					pcall(PV.hum_quiet,m);
					local seen=0;
					for _,x in ipairs(m:GetDescendants()) do
						if x:IsA("BasePart") and BODY[x.Name] and x.Transparency<0.9 then seen=seen+1;end;
					end;
					for _,x in ipairs(m:GetDescendants()) do
						if x:IsA("BasePart") then
							x.Anchored=true;x.CanCollide=false;x.CanQuery=false;x.CanTouch=false;
							if x.Name=="HumanoidRootPart" then
								x.Transparency=1;
							elseif seen<3 and BODY[x.Name] and x.Transparency>=0.9 then
								x.Transparency=0;
							end;
						end;
					end;
					pcall(PV.fix_skin,m);
					-- Match the model-changer static preview exactly: use gun_mount_a (including its grip correction).
					pcall(PV.strip_native_gun,m);
					local wm=tcache.__wm(vp);
					if not wm then pcall(function() m:Destroy();end);return false;end;
					m.Parent=wm;
					S.model,S.wm,S.src,S.lobby=m,wm,src,lobby==true;
					local gun;
					if PV.gun and PV.gun~="none" and type(PV.gun_mount_a)=="function" then
						local okg,gg=pcall(PV.gun_mount_a,m);
						if okg then gun=gg;end;
					end;
					S.gun=gun;
					S.gunSig=gun_signature();
					local parts,skp={}, {};
					for _,d in ipairs(m:GetDescendants()) do
						if d:IsA("BasePart") and BODY[d.Name] then
							parts[#parts+1]=d;
							skp[d.Name]=d;
						end;
					end;
					S.parts,S.skp=parts,skp;
					local hrp=m:FindFirstChild("HumanoidRootPart",true);
					S.rootcf=(hrp and hrp:IsA("BasePart")) and hrp.CFrame or m:GetPivot();
					local oks,scene,scf=pcall(PV.scene_mount,m,vp);
					if oks and typeof(scene)=="Instance" then S.scene,S.scamcf=scene,scf;end;
					local okr,rig=pcall(PV.rig_build,m);
					if okr and rig then
						-- Same as PV.static_animate: add the anchored preview gun to the pose graph explicitly.
						if gun then pcall(PV.gun_link,rig,gun);end;
						S.rig=rig;
						S.live={src=src,map=PV.motor_map(src),n=0};
						pcall(PV.rig_step_live,rig,S.live);
					else
						pcall(PV.play,m,PV.anim_ids());
					end;
					local okb,cf,size=pcall(PV.body_bbox,m);
					if not(okb and cf and size) or size.Magnitude~=size.Magnitude or size.Magnitude>30 then
						cf=CFrame.new(S.rootcf.Position+Vector3.new(0,0.4,0));
						size=Vector3.new(3.5,6.7,2.5);
					end;
					S.center,S.size=cf.Position,size;
					do
						local okbb,bbcf,bsz=pcall(function() return m:GetBoundingBox();end);
						S.bsize=okbb and bsz or nil;
						S.camCenter=(okbb and bbcf and bbcf.Position) or cf.Position;
						S.orbitDist=(okbb and bsz) and ((bsz.Y*0.5)/math.tan(math.rad(17.5))*1.25+bsz.Z*0.5) or 9;
					end;
					S.fail=0;
					F.note.Visible=false;
					return true;
				end;

				-- chams / highlight: плоская заливка частей (Highlight во ViewportFrame не рисуется), оригиналы запоминаются и возвращаются
				local function tint_sig()
					local function s(t)
						if type(t)~="table" then return "-";end;
						local c=t[1];
						if typeof(c)~="Color3" then return "?"..tostring(t[2]);end;
						return string.format("%d,%d,%d,%s",math.floor(c.R*255),math.floor(c.G*255),math.floor(c.B*255),tostring(t[2]));
					end;
					return table.concat({tostring(cfg.chams),s(cfg.chamsFCol),tostring(cfg.hlt),s(cfg.hltFCol)},"|");
				end;
				local function apply_tint()
					if not S.model then return;end;
					if S.orig then
						for inst,o in pairs(S.orig) do
							pcall(function()
								if o.rm then
									inst.Parent=o.par;
								else
									inst.Color=o.c;
									inst.Material=o.m;
									if o.tex~=nil then inst.TextureID=o.tex;end;
								end;
							end);
						end;
						S.orig=nil;
					end;
					if not(cfg.chams==true or cfg.hlt==true) then return;end;
					local col,op,neon;
					if cfg.chams==true then
						local c1,a1=pair(cfg.chamsFCol,Color3.new(1,1,1),0.5);
						col,op,neon=c1,math.max(a1,0.35),true;
					else
						local c1,a1=pair(cfg.hltFCol,Color3.new(1,1,1),0.5);
						col,op,neon=c1,a1,false;
					end;
					local orig={};
					for _,d in ipairs(S.model:GetDescendants()) do
						if d:IsA("SurfaceAppearance") or d:IsA("Clothing") then
							orig[d]={rm=true,par=d.Parent};
							pcall(function() d.Parent=nil;end);
						elseif d:IsA("BasePart") and d.Name~="HumanoidRootPart" then
							local o={c=d.Color,m=d.Material};
							if d:IsA("MeshPart") then
								o.tex=d.TextureID;
								pcall(function() d.TextureID="";end);
							end;
							orig[d]=o;
							pcall(function()
								d.Color=o.c:Lerp(col,math.clamp(op,0,1));
								if neon then d.Material=Enum.Material.Neon;end;
							end);
						end;
					end;
					S.orig=orig;
				end;

				----------------------------------------------------------------
				-- оверлей
				----------------------------------------------------------------
				local function hide_all()
					for i=1,#ALL do ALL[i].Visible=false;end;
				end;

				local function setText(L,txt,tcol,out,ocol,gon,gcol)
					local col,a=pair(tcol,Color3.new(1,1,1),1);
					L.Text=txt;
					L.TextColor3=gon and Color3.new(1,1,1) or col;
					L.TextTransparency=1-a;
					if out then
						L.TextStrokeTransparency=0.35;
						L.TextStrokeColor3=typeof(ocol)=="Color3" and ocol or Color3.new(0,0,0);
					else
						L.TextStrokeTransparency=1;
					end;
					grad(L,gon,gcol,0);
					L.Visible=true;
				end;

				local function draw(W,H)
					local c=cfg;
					local cf=cam.CFrame;
					local th=math.tan(math.rad(cam.FieldOfView)*0.5);
					local asp=W/H;
					local function pr(p)
						local v=cf:PointToObjectSpace(p);
						local d=-v.Z;
						if d<0.05 then return nil,nil;end;
						return (v.X/(d*th*asp)*0.5+0.5)*W,(0.5-v.Y/(d*th)*0.5)*H;
					end;

					hide_all();

					-- прямоугольник игрока из 8 углов каждой части тела
					local x0,y0,x1,y1=math.huge,math.huge,-math.huge,-math.huge;
					for _,p in ipairs(S.parts) do
						local hs=p.Size*0.5;
						local pc=p.CFrame;
						for sx=-1,1,2 do
							for sy=-1,1,2 do
								for sz=-1,1,2 do
									local px,py=pr(pc*Vector3.new(hs.X*sx,hs.Y*sy,hs.Z*sz));
									if px then
										if px<x0 then x0=px;end;
										if px>x1 then x1=px;end;
										if py<y0 then y0=py;end;
										if py>y1 then y1=py;end;
									end;
								end;
							end;
						end;
					end;
					if x0==math.huge then return;end;
					x0=math.floor(x0);y0=math.floor(y0);x1=math.ceil(x1);y1=math.ceil(y1);
					local bw,bh=x1-x0,y1-y0;
					if bw<4 or bh<4 then return;end;
					local cx=(x0+x1)*0.5;

					-- заливка + рамка
					if c.box==true then
						if c.boxF==true then
							local fc,fa=pair(c.boxFCol,Color3.new(1,0,0),0.5);
							local fg=c.boxFGrd==true;
							F.fill.Visible=true;
							place(F.fill,x0,y0,bw,bh);
							F.fill.BackgroundColor3=fg and Color3.new(1,1,1) or fc;
							F.fill.BackgroundTransparency=1-fa;
							grad(F.fill,fg,c.boxFGrdCol,90);
						end;
						local bcol,bop=pair(c.boxCol,Color3.new(1,0,0),1);
						local gon=c.boxGrd==true;
						local outl=c.boxO==true;
						if c.boxType=="Corners" then
							local L=math.max(6,math.floor(math.min(bw,bh)*0.28));
							local segs={
								{x0,y0,L,1},{x0,y0,1,L},
								{x1-L+1,y0,L,1},{x1,y0,1,L},
								{x0,y1,L,1},{x0,y1-L+1,1,L},
								{x1-L+1,y1,L,1},{x1,y1-L+1,1,L},
							};
							for i=1,8 do
								local sg=segs[i];
								if outl then
									local b=F.cb[i];
									b.Visible=true;
									place(b,sg[1]-1,sg[2]-1,sg[3]+2,sg[4]+2);
								end;
								local s=F.cs[i];
								s.Visible=true;
								place(s,sg[1],sg[2],sg[3],sg[4]);
								s.BackgroundColor3=bcol;
								s.BackgroundTransparency=1-bop;
							end;
						else
							if outl then
								F.bo1.Visible=true;place(F.bo1,x0-1,y0-1,bw+2,bh+2);
								F.bo2.Visible=true;place(F.bo2,x0+1,y0+1,bw-2,bh-2);
								local oc,oa=pair(c.boxOCol,Color3.new(0,0,0),1);
								F.bo1s.Color=oc;F.bo2s.Color=oc;
								F.bo1s.Transparency=1-oa;F.bo2s.Transparency=1-oa;
							end;
							F.bm.Visible=true;
							place(F.bm,x0,y0,bw,bh);
							F.bms.Color=gon and Color3.new(1,1,1) or bcol;
							F.bms.Transparency=1-bop;
							grad(F.bms,gon,c.boxGrdCol,90);
						end;
					end;

					-- скелет
					if c.skel==true then
						local sc,sa=pair(c.skelCol,Color3.new(1,1,1),1);
						for i=1,#BONES do
							local a,b=S.skp[BONES[i][1]],S.skp[BONES[i][2]];
							if a and b then
								local ax,ay=pr(a.Position);
								local bx,by=pr(b.Position);
								if ax and bx then
									local ln=F.sk[i];
									local dx,dy=bx-ax,by-ay;
									ln.Visible=true;
									ln.AnchorPoint=Vector2.new(0.5,0.5);
									ln.Position=UDim2.fromOffset((ax+bx)*0.5,(ay+by)*0.5);
									ln.Size=UDim2.fromOffset(math.max(1,math.sqrt(dx*dx+dy*dy)),1);
									ln.Rotation=math.deg(math.atan2(dy,dx));
									ln.BackgroundColor3=sc;
									ln.BackgroundTransparency=1-sa;
								end;
							end;
						end;
					end;

					-- полоски (здоровье / броня)
					local used={left=0,right=0,top=0,bottom=0};
					local function dobar(B,side,frac,tcol,tdef,gon,gcol,oon,ocol)
						local k=used[side];
						used[side]=k+1;
						local o=3+k*7;
						local vertical=(side=="left" or side=="right");
						local fc,fa=pair(tcol,tdef,1);
						local bx,by,bwid,bhei;
						if side=="left" then bx,by,bwid,bhei=x0-o-5,y0-1,5,bh+2;
						elseif side=="right" then bx,by,bwid,bhei=x1+o,y0-1,5,bh+2;
						elseif side=="top" then bx,by,bwid,bhei=x0-1,y0-o-5,bw+2,5;
						else bx,by,bwid,bhei=x0-1,y1+o,bw+2,5;end;
						if oon~=false then
							local oc,oa=pair(ocol,Color3.new(0,0,0),0.5);
							B.bg.Visible=true;
							place(B.bg,bx,by,bwid,bhei);
							B.bg.BackgroundColor3=oc;
							B.bg.BackgroundTransparency=1-oa;
						end;
						local px,py,pw,ph;
						if vertical then
							local fh=math.max(1,math.floor(bh*frac+0.5));
							px,py,pw,ph=bx+1,y0+(bh-fh),3,fh;
							B.fill.AnchorPoint=Vector2.new(0,1);
							B.fill.Position=UDim2.new(0,0,1,0);
							B.fill.Size=UDim2.fromOffset(3,bh);
						else
							local fw=math.max(1,math.floor(bw*frac+0.5));
							px,py,pw,ph=x0,by+1,fw,3;
							B.fill.AnchorPoint=Vector2.new(0,0);
							B.fill.Position=UDim2.new(0,0,0,0);
							B.fill.Size=UDim2.fromOffset(bw,3);
						end;
						B.clip.Visible=true;
						place(B.clip,px,py,pw,ph);
						B.fill.Visible=true;
						B.fill.BackgroundColor3=gon and Color3.new(1,1,1) or fc;
						B.fill.BackgroundTransparency=1-fa;
						grad(B.fill,gon,gcol,vertical and 90 or 0);
						return bx,by,bwid,bhei,px,py,pw,ph;
					end;

					local hbS,abS=sd(c.hbSide,"left"),sd(c.abSide,"right");
					local hbx,hby,hbw,hbh,hpx,hpy,hpw,hph;
					if c.hb==true then
						hbx,hby,hbw,hbh,hpx,hpy,hpw,hph=dobar(F.hb,hbS,S.hp/100,c.hbCol,Color3.new(0,1,0),c.hbGrd==true,c.hbGrdCol,c.hbo,c.hboCol);
					end;
					if c.ab==true then
						dobar(F.ab,abS,S.armor/100,c.abCol,Color3.fromRGB(0,150,255),c.abGrd==true,c.abGrdCol,c.abo,c.aboCol);
					end;
					if c.hb==true and c.ht==true then
						local L=F.ht;
						setText(L,tostring(math.floor(S.hp+0.5)),c.htCol,c.htOut,c.htOCol,c.htGrd==true,c.htGrdCol);
						L.Size=UDim2.fromOffset(40,13);
						if hbS=="left" then
							L.TextXAlignment=Enum.TextXAlignment.Right;
							place(L,hbx-2-40,hpy-6);
						elseif hbS=="right" then
							L.TextXAlignment=Enum.TextXAlignment.Left;
							place(L,hbx+hbw+2,hpy-6);
						elseif hbS=="top" then
							L.TextXAlignment=Enum.TextXAlignment.Center;
							place(L,hpx+hpw-20,hby-14);
						else
							L.TextXAlignment=Enum.TextXAlignment.Center;
							place(L,hpx+hpw-20,hby+hbh+1);
						end;
					end;

					-- текст и значки вокруг рамки
					local lists={left={},right={},top={},bottom={}};
					local function add(side,inst,w,h,isname)
						local l=lists[side];
						l[#l+1]={inst=inst,w=w,h=h,isname=isname};
					end;
					local function txt(L,key,text,colk,outk,ocolk,grdk,gcolk,posk,defpos)
						if c[key]~=true then return;end;
						setText(L,text,c[colk],c[outk],c[ocolk],c[grdk]==true,c[gcolk]);
						L.Size=UDim2.fromOffset(130,13);
						add(sd(c[posk],defpos),L,130,13);
					end;

					if c.name==true then
						local nm=tostring(lp.Name);
						setText(F.name,nm,c.nCol,c.nOut,c.nOCol,c.nGrd==true,c.nGrdCol);
						F.name.Size=UDim2.fromOffset(170,13);
						F.name.TextXAlignment=Enum.TextXAlignment.Center;
						add("top",F.name,170,13,nm);
					end;
					txt(F.wep,"wep",S.gun or "AK-47","wCol","wOut","wOCol","wGrd","wGrdCol","wPos","bottom");
					if c.wepIcon==true then
						local ic,ia=pair(c.wepIconCol,Color3.new(1,1,1),1);
						local sz=tonumber(c.wepIconSz) or 16;
						F.icon.Visible=true;
						F.icon.BackgroundColor3=ic;
						F.icon.BackgroundTransparency=1-ia*0.6;
						add(sd(c.wepIconPos,"bottom"),F.icon,math.floor(sz*2.4),math.floor(sz*0.7),nil);
					end;
					txt(F.dis,"dis",tostring(S.dist).." studs","dCol","dOut","dOCol","dGrd","dGrdCol","dPos","bottom");
					txt(F.mon,"mon","$"..tostring(S.money),"monCol","monOut","monOCol","monGrd","monGrdCol","monPos","right");
					txt(F.pn,"pn",tostring(S.ping).."ms","pnCol","pnOut","pnOCol","pnGrd","pnGrdCol","pnPos","right");
					local function flag(L,key)
						if c[key]~=true then return;end;
						local col,a=pair(c[key.."Col"],Color3.new(1,1,1),1);
						local gon=c[key.."Grd"]==true;
						setText(L,key,c[key.."Col"],true,Color3.new(0,0,0),gon,c[key.."GrdCol"]);
						L.Size=UDim2.fromOffset(130,13);
						add(sd(c[key.."Pos"],"right"),L,130,13);
					end;
					flag(F.bomb,"bomb");
					flag(F.scope,"scope");
					flag(F.flashed,"flashed");
					flag(F.defuse,"defuse");

					local function put(it,x,y,align)
						place(it.inst,x,y,it.w,it.h);
						if it.inst:IsA("TextLabel") then
							it.inst.TextXAlignment=Enum.TextXAlignment[align];
						end;
					end;
					local function off(s)
						local n=used[s];
						if n>0 then return 3+n*7;end;
						return 0;
					end;
					-- top (растёт вверх)
					local y=y0-off("top")-3;
					for _,it in ipairs(lists.top) do
						y=y-it.h;
						if it.isname and c.av==true then
							local tw=TextService:GetTextSize(it.isname,13,Enum.Font.Code,Vector2.new(400,20)).X;
							local start=cx-(16+3+tw)*0.5;
							F.av.Visible=true;
							place(F.av,start,y-2);
							it.inst.TextXAlignment=Enum.TextXAlignment.Center;
							place(it.inst,start+19+tw*0.5-it.w*0.5,y,it.w,it.h);
						else
							put(it,cx-it.w*0.5,y,"Center");
						end;
					end;
					if c.av==true and not c.name then
						F.av.Visible=true;
						place(F.av,cx-8,y0-off("top")-3-18);
					end;
					-- bottom
					y=y1+off("bottom")+3;
					for _,it in ipairs(lists.bottom) do
						put(it,cx-it.w*0.5,y,"Center");
						y=y+it.h;
					end;
					-- left
					local ex=x0-off("left")-4;
					y=y0;
					for _,it in ipairs(lists.left) do
						put(it,ex-it.w,y,"Right");
						y=y+it.h;
					end;
					-- right
					ex=x1+off("right")+4;
					y=y0;
					for _,it in ipairs(lists.right) do
						put(it,ex,y,"Left");
						y=y+it.h;
					end;
				end;

				----------------------------------------------------------------
				-- ввод: вращение и зум
				----------------------------------------------------------------
				vp.InputBegan:Connect(function(i)
					local t=i.UserInputType;
					if t==Enum.UserInputType.MouseButton1 or t==Enum.UserInputType.Touch then S.dragging=i;end;
				end);
				vp.InputChanged:Connect(function(i)
					if i.UserInputType==Enum.UserInputType.MouseWheel then
						S.zoom=math.clamp((S.zoom or 1)*(1+i.Position.Z*0.12),0.6,4);
					end;
				end);
				-- Same two-finger pinch handling as the model-changer preview.
				pcall(function() vp.TouchPinch:Connect(function(tpos,scale,vel,state)
					if state==Enum.UserInputState.Begin then
						S.pinching=true;
						S.pinch_base=S.zoom or 1;
					elseif state==Enum.UserInputState.Change then
						S.zoom=math.clamp((S.pinch_base or 1)*scale,0.6,4);
					else
						S.pinching=false;
						S.dragging=nil;
					end;
				end) end);
				A.connect(UIS.InputChanged,function(i)
					if S.pinching or not S.dragging then return;end;
					local t=i.UserInputType;
					if t==Enum.UserInputType.MouseMovement or t==Enum.UserInputType.Touch then
						S.drag=S.drag-i.Delta.X*0.012;
					end;
				end);
				A.connect(UIS.InputEnded,function(i)
					local t=i.UserInputType;
					if t==Enum.UserInputType.MouseButton1 or t==Enum.UserInputType.Touch then S.dragging=nil;end;
				end);

				----------------------------------------------------------------
				-- кадр
				----------------------------------------------------------------
				S.dist,S.money,S.ping=18,4750,42;
				pcall(function()
					local g=PV.cur_gun_name();
					if type(g)=="string" and g~="" and g~="none" then S.gun=g;end;
				end);

				local function step()
					local m=S.model;
					if not(m and m.Parent and root.Parent) then return;end;
					if not shown(root) then return;end;
					local W,H=vp.AbsoluteSize.X,vp.AbsoluteSize.Y;
					if W<20 or H<20 then return;end;

					-- поза с живого лобби-агента
					if S.rig and S.live then
						local ok=pcall(PV.rig_step_live,S.rig,S.live);
						S.live.n=(S.live.n or 0)+1;
						if not ok then
							S.fail=(S.fail or 0)+1;
							if S.fail>20 then
								for part,cf0 in pairs(S.rig.orig) do pcall(function() part.CFrame=cf0;end);end;
								S.rig,S.live=nil,nil;
								pcall(PV.play,m,PV.anim_ids());
							end;
						elseif S.live.n==3 then
							local okb,_,sz=pcall(function() return m:GetBoundingBox();end);
							local base=S.bsize;
							if not okb or not sz or sz.Magnitude~=sz.Magnitude or (base and sz.Magnitude>base.Magnitude*1.8) then
								for part,cf0 in pairs(S.rig.orig) do pcall(function() part.CFrame=cf0;end);end;
								S.rig,S.live=nil,nil;
								pcall(PV.play,m,PV.anim_ids());
							end;
						elseif S.live.n==5 then
							local okb,cf2,sz2=pcall(PV.body_bbox,m);
							if okb and cf2 and sz2 and sz2.Magnitude==sz2.Magnitude and sz2.Magnitude<30 then
								S.center,S.size=cf2.Position,sz2;
							end;
						end;
					end;

					-- камера: спереди агента, вращение мышью
					-- Камера синхронизирована с превью агента: те же fit/lobby/orbit, FOV, pitch, yaw и дистанция.
					local mode=PV.cam or "fit";
					if mode=="orbit" then
						cam.FieldOfView=35/(S.zoom or 1);
						local d=S.orbitDist or 9;
						local p=S.camCenter+Vector3.new(math.sin(S.drag)*d,d*0.08,-math.cos(S.drag)*d);
						cam.CFrame=CFrame.lookAt(p,S.camCenter);
					else
						cam.FieldOfView=((mode=="lobby") and (tonumber(PV.fov) or 70) or 40)/(S.zoom or 1);
						local rcf=S.rootcf or CFrame.new(S.center);
						if mode=="lobby" and S.scamcf then
							local rp=rcf.Position;
							cam.CFrame=CFrame.new(rp)*CFrame.Angles(0,S.drag,0)*CFrame.new(-rp)*S.scamcf;
						else
							local fwd=Vector3.new(rcf.LookVector.X,0,rcf.LookVector.Z);
							if fwd.Magnitude>0.01 then fwd=fwd.Unit;else fwd=Vector3.new(0,0,-1);end;
							local yaw=(tonumber(PV.yaw0) or math.rad(25))+S.drag;
							local cs,sn=math.cos(yaw),math.sin(yaw);
							fwd=Vector3.new(fwd.X*cs+fwd.Z*sn,0,-fwd.X*sn+fwd.Z*cs);
							local focus,d;
							if mode=="lobby" then
								focus=rcf.Position+Vector3.new(0,tonumber(PV.focusY) or 1.5,0);
								d=tonumber(PV.dist) or 12.159;
							else
								focus=rcf.Position+Vector3.new(0,-0.55,0);
								d=10.2;
							end;
							local pitch=tonumber(PV.pitch) or math.rad(15);
							local pos=focus+fwd*(d*math.cos(pitch))+Vector3.new(0,d*math.sin(pitch),0);
							cam.CFrame=CFrame.lookAt(pos,focus);
						end;
					end;

					-- chams / highlight
					local sig=tint_sig();
					if sig~=S.tsig then
						S.tsig=sig;
						pcall(apply_tint);
					end;

					local okd,err=pcall(draw,W,H);
					if not okd and not S.warned then
						S.warned=true;
						warn("[killed] esp preview draw: "..tostring(err));
					end;
				end;
				A.connect(RS.RenderStepped,function()
					local oks,errs=pcall(step);
					if not oks and not S.warned2 then
						S.warned2=true;
						warn("[killed] esp preview step: "..tostring(errs));
					end;
				end);

				-- сборка/пересборка: первый показ, кнопка rebuild, исчезла или появилась лобби-модель
				A.spawn(function()
					while root.Parent do
						task.wait(0.75);
						if shown(root) then
							local need=S.want==true;
							if not need then
								if not(S.model and S.model.Parent and S.src and S.src.Parent) then
									need=true;
								elseif gun_signature()~=S.gunSig then
									need=true;
								elseif not S.lobby then
									local okf,fm=pcall(PV.menu_fast);
									if okf and fm then need=true;end;
								end;
							end;
							if need then
								S.want=false;
								local okb,res=pcall(build);
								if not(okb and res) then
									if not okb then warn("[killed] esp preview build: "..tostring(res));end;
									F.note.Visible=true;
								end;
							end;
						end;
					end;
				end);

				A.teardown(function()
					pcall(destroy_model);
				end);

				return {state=S};
			end;
			-- trimmed build: only ESP + skin changer (knives/gloves/guns) + agents remain
			local function SL(id)
				local ok, res = pcall(K.load, id)
				if ok then return res end
				warn("[killed] module '" .. tostring(id) .. "' failed to load, skipped: " .. tostring(res))
				return setmetatable({}, { __index = function() return function() end end })
			end
			local U=K.load("a");
			U.takeover();
			local R=K.load("b").reclaim;
			local ui=K.load("e");
			local pl=SL("p");
			local esp=SL("G");
			local draw=SL("v");
			SL("aA");
			SL("aG");
			local function E(P)
				pcall(P);
				R();
			end;
			local function early()
				E(pl.step);
			end;
			local function late()
				E(draw.pump);
			end;
